INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Abronia alpina', 'Ramshaw Meadows Abronia', null, 'Pink, White, Lavender', null, null, null, null, null, null, null, 'https://calscape.org/Abronia-alpina-%28Ramshaw-Meadows-Abronia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Abronia latifolia', 'Sand Verbena', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Spring, Fall', 'Full Sun', 'Very Low', '<p>Coastal plants such as other Verbena species - Red Sand Verbena (Abronia maritima), Pink Sand Verbena (Abronia umbellata), Common Yarrow (Achillea millefolium), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Saltbush species (<a href="/search/?plant=Atriplex%20(Genus)">Atriplex spp.</a>), Morning-glory species (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Beach Evening Primrose (Camissoniopsis cheiranthifolia), Sandcarpet (Cardionema ramosissimum), Croton (Croton californicus), Seaside Daisy species (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Buckwheat species (Eriogonum latifolium, Eriogonum parvifolium), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Wallflower (<a href="/search/?plant=Erysimum%20(Genus)">Erysimum spp.</a>), Beach Strawberry (Fragaria chiloensis), Coastal Gumplant (Grindelia stricta), Silky Beach Pea (Lathyrus littoralis), Dunedelion (Malacothrix incana), Hummingbird Sage (Salvia spathacea), Penstemon species, Sand Dune Bluegrass (Poa douglasii). Emergent shrubs may be present at low cover including Coyote Bush (Baccharis pilularis), California Goldenbush (Ericameria ericoides), Lupine species (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>).</p>', 'Coastal Sage Scrub, Coastal Strand', '<p>Requires fast draining soil. Prefers sun. Likes sandy soils.</p>', null, 'https://calscape.org/Abronia-latifolia-%28Sand-Verbena%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Abronia maritima', 'Red Sand Verbena', 'Bees, Butterflies, Caterpillars', 'Pink, Purple, Red', 'Winter, Spring, Summer, Fall', 'Full Sun', 'Very Low', 'Plant with other dune wildflowers and shrubs such as Dune Bush Lupine (Lupinus chamissonis), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Sand-loving Wallflower (Erysimum ammophilum), Sandcarpet (Cardionema ramosissimum), and Coastal Buckbrush (Ceanothus cuneatus var. ramulosus).', 'Coastal Strand', 'Requires fast draining soil. Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Abronia-maritima-%28Red-Sand-Verbena%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Abronia nana', 'Dwarf Sand Verbena', 'Butterflies, Caterpillars', 'Pink', null, null, null, null, 'Joshua Tree Woodland, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub', null, null, 'https://calscape.org/Abronia-nana-%28Dwarf-Sand-Verbena%29');
