INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Acmispon glaber', 'Deer Plant', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Winter, Spring, Summer', 'Full Sun', 'Very Low', 'Deerweed has no particular companion plants in the wild, but it can be used with virtually any other natives.', 'Chaparral, Coastal Sage Scrub, Coastal Strand, Joshua Tree Woodland', 'Prefers sun. Likes sandy slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Acmispon-glaber-%28Deer-Plant%29');
