INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aconitum columbianum', 'Columbian Monkshood', 'Butterflies, Caterpillars', 'Blue, Purple, Yellow, White', 'Summer', 'Full Sun, Partial Shade', 'Low, Moderate, High', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 5.4-7.2. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Aconitum columbianum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 50 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of full shade. Prefers sun or part shade. Likes stream banks.', null, 'https://calscape.org/Aconitum-columbianum-%28Columbian-Monkshood%29');
