INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Agastache urticifolia', 'Nettle Leaf Giant Hyssop', 'Butterflies, Caterpillars', 'Red', 'Spring', 'Deep Shade, Partial Shade', null, null, 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Agastache urticifolia is only slightly drought tolerant. It requires a minimum of 18 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of shade.', null, 'https://calscape.org/Agastache-urticifolia-%28Nettle-Leaf-Giant-Hyssop%29');
