INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Agoseris aurantiaca', 'Orange Flowered Agoseris', 'Butterflies, Caterpillars', 'Orange, Yellow', 'Spring', 'Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 6.6-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Agoseris aurantiaca is moderately drought tolerant. It requires a minimum of 19 inches of water per year, and a maximum of 69 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers part shade.', null, 'https://calscape.org/Agoseris-aurantiaca-%28Orange-Flowered-Agoseris%29');
