INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Agoseris glauca', 'Pale Dandelion', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Northern Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Agoseris glauca is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 69 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade. Likes slopes and meadows.', null, 'https://calscape.org/Agoseris-glauca-%28Pale-Dandelion%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Agoseris glauca var. glauca', 'Pale Agoseris', 'Butterflies, Caterpillars', 'Yellow', null, null, null, null, 'Wetland-Riparian', null, null, 'https://calscape.org/Agoseris-glauca-var.-glauca-%28Pale-Agoseris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Agoseris grandiflora', 'California Dandelion', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', 'Low', null, 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 5.8-7.3. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Agoseris grandiflora is moderately drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes grassy areas.', null, 'https://calscape.org/Agoseris-grandiflora-%28California-Dandelion%29');
