INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Allium acuminatum', 'Taper Tipped Onion', 'Bats, Bees, Butterflies, Caterpillars', 'Purple, Pink', 'Summer', 'Partial Shade', 'Moderate', null, 'Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Allium acuminatum is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. It does not tolerate full shade well. Prefers part shade.', null, 'https://calscape.org/Allium-acuminatum-%28Taper-Tipped-Onion%29');
