INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Allium tolmiei', 'Tolmie''s Onion', 'Bees, Butterflies, Caterpillars', 'Red, Pink, White', 'Spring', 'Full Sun', 'Moderate', null, 'Sagebrush Scrub', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Allium tolmiei is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes rocky clay flats.', null, 'https://calscape.org/Allium-tolmiei-%28Tolmie%27s-Onion%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Allium tolmiei var. tolmiei', 'Tolm''s Onion', 'Butterflies, Caterpillars', 'White', null, 'Full Sun', 'Moderate', null, 'Sagebrush Scrub', 'Prefers sun. Likes rocky clay flats.', null, 'https://calscape.org/Allium-tolmiei-var.-tolmiei-%28Tolm%27s-Onion%29');
