INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Allium unifolium', 'One Leaf Onion', 'Bees, Butterflies, Caterpillars', 'Lavender, Pink, Yellow, White, Purple', 'Spring', 'Deep Shade, Partial Shade', 'Moderate', 'Native grasses, Miner''s Lettuce (Claytonia rubra ssp. depressa), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>', 'Chaparral, Montane Chaparral', 'Requires moist soil. Prefers part shade. Likes grassy stream banks with moist clay soils.', null, 'https://calscape.org/Allium-unifolium-%28One-Leaf-Onion%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Allium validum', 'Pacific Mountain Onion', 'Bees, Butterflies, Caterpillars', 'Purple, Lavender, Pink', 'Spring', 'Full Sun', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 8 inches deep, with a pH of 6.2-8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Allium validum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 40 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun. Likes wet meadows.', null, 'https://calscape.org/Allium-validum-%28Pacific-Mountain-Onion%29');
