INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ambrosia ambrosioides', 'Ambrosia Bursage', 'Butterflies, Caterpillars', null, null, 'Full Sun', null, null, 'Coastal Sage Scrub', 'Prefers sun.', null, 'https://calscape.org/Ambrosia-ambrosioides-%28Ambrosia-Bursage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ambrosia chamissonis', 'Beach Bur', 'Bees, Butterflies, Caterpillars', 'Yellow, Green', 'Summer, Fall', 'Full Sun', 'Low', null, 'Coastal Strand', 'Requires fast draining soil. Prefers sun. Likes sandy soils.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Ambrosia-chamissonis-%28Beach-Bur%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ambrosia confertiflora', 'Weakleaf Bur Ragweed', 'Butterflies, Caterpillars', null, null, null, null, null, 'Coastal Sage Scrub, Southern Oak Woodland', null, null, 'https://calscape.org/Ambrosia-confertiflora-%28Weakleaf-Bur-Ragweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ambrosia psilostachya', 'Western Ragweed', 'Butterflies, Caterpillars', 'Green', 'Summer, Fall', 'Full Sun', 'Low, Moderate, High', 'Ambrosia psilostachya can do well in a variety of conditions, so the soil type of your garden will best inform which other plants to choose. Consider using other natives that do well in sunny, sandy sites, such as Nuttall''s scrub oak (Quercus dumosa), Desertbells (Phacelia campanularia), or the Bristly Matilija poppy (Romneya trichocalyx).', 'Weed (disturbed places), Wetland-Riparian', 'Dry or moist soil', null, 'https://calscape.org/Ambrosia-psilostachya-%28Western-Ragweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ambrosia pumila', 'San Diego Ambrosia', 'Butterflies, Caterpillars', 'Yellow, Green', 'Summer, Spring, Fall', 'Full Sun', 'Very Low', '<p>In the wild it is associated with Saltgrass (Distichlis spicata), Mulefat (Baccharis salicifolia), Broom Baccharis (Baccharis sarathroides), California Buckwheat (Eriogonum fasciculatum), and Turkey-mullein (Croton setiger)</p>', 'Chaparral, Coastal Sage Scrub, Freshwater Marsh, Valley Grassland', '<p>Prefers sun.This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as every other week. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Ambrosia-pumila-%28San-Diego-Ambrosia%29');
