INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Anaphalis margaritacea', 'Pearly Everlasting', 'Bats, Butterflies, Caterpillars', 'Yellow, White', 'Summer', 'Partial Shade, Full Sun', 'Low, Moderate', 'This plant will work with many forest, woodland and chaparral plants, especially those of the Sierra and the Coast Ranges.', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', 'Plant in loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Anaphalis margaritacea is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 35 inches of water per year once established. It is moderately tolerant of full shade. Prefers part shade.', null, 'https://calscape.org/Anaphalis-margaritacea-%28Pearly-Everlasting%29');
