INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Anemone multifida', 'Pacific Anemone', null, 'Yellow, White', 'Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Red Fir Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, intolerant calcareous soils, and tolerant of infertile soils. It requires a minimum of 40 inches of water per year, and a maximum of 60 inches of water per year once established. It is very tolerant of shade, but prefers sun or part shade. Likes gravelly or rocky slopes.', null, 'https://calscape.org/Anemone-multifida-%28Pacific-Anemone%29');
