INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Anemopsis californica', 'Yerba Mansa', null, 'White, Cream, Red', 'Spring, Winter', 'Partial Shade, Full Sun', 'High, Moderate', 'Yellow Monkeyflower (Mimulus ''Yellow''), Scarlet Monkeyflower (Erythranthe cardinalis), Stream Orchid (Epipactis gigantea), various Rushes, various sedges, <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, <a href="/search/?plant=Equisetum%20(Genus)">Equisetum spp.</a>', 'Bogs, Freshwater Marsh, Lakes and Ponds, Meadows, Riparian Woodland, Valley and Montane Riparian Woodland', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 6.5-9. It is tolerant of anaerobic soils, tolerant of calcareous soils, tolerant of alkaline soils, and tolerant of infertile soils. <br/>It requires a minimum of 6 inches, and a maximum of 18 inches of supplementary water per year once established. Requires moist soil; it often grows alongside creeks and marshes. Prefers shade. Likes saline or alkaline soils.<br/>This plant is tough and easy to grow. It''s very garden tolerant, and not particularly sensitive to pathogens that grow in warm moist soils. It can handle weekly summer watering.', 'May be attacked by leaf eating insects, but usually not fatal', 'https://calscape.org/Anemopsis-californica-%28Yerba-Mansa%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Antennaria marginata', 'White-margined Everlasting', 'Butterflies, Caterpillars', null, null, null, null, null, null, null, null, 'https://calscape.org/Antennaria-marginata-%28White-margined-Everlasting%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Angelica arguta', 'Angelica', 'Butterflies, Caterpillars', 'White', 'Spring', 'Full Sun, Partial Shade', null, null, 'Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 6.5-7.5. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Angelica arguta is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'https://calscape.org/Angelica-arguta-%28Angelica%29');
