INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Antirrhinum nuttallianum', 'Nuttall''s Snapdragon', 'Bats, Bees, Hummingbirds, Butterflies, Caterpillars', 'Purple, White', 'Spring, Summer', 'Full Sun', 'Extremely Low, Very Low', 'Use with other annuals or herbaceous perennials such as Sitka Columbine (Aquilegia formosa), Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia heterophylla), Western Wallflower (Erysimum capitatum), Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a>), Blue Field Gilia (Gilia capitata); with geophytes such as onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>); and with succulents such as Dudleya spp. or Yucca spp.', 'Chaparral', 'Prefers sun. Likes sandy or rocky soils.', null, 'https://calscape.org/Antirrhinum-nuttallianum-%28Nuttall%27s-Snapdragon%29');
