INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Apocynum androsaemifolium', 'Bitter Dogbane', 'Butterflies, Caterpillars', 'Pink', null, 'Deep Shade, Partial Shade', null, null, 'Foothill Woodland, Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers shade. Likes slopes and rocky soils.', null, 'https://calscape.org/Apocynum-androsaemifolium-%28Bitter-Dogbane%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Apocynum cannabinum', 'Indianhemp Dogbane', 'Bats, Butterflies, Caterpillars', 'Cream, White, Brown', 'Summer', 'Partial Shade', 'Low, Moderate', null, 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 4.5-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Apocynum cannabinum is moderately drought tolerant. It requires a minimum of 15 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers part shade. This plant needs heavy water throughout the year. Water 2x per week.</p>', null, 'https://calscape.org/Apocynum-cannabinum-%28Indianhemp-Dogbane%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aquilegia eximia', 'Van Houtte''s Columbine', 'Birds, Butterflies, Caterpillars', 'Orange, Red', 'Spring, Summer, Fall', 'Deep Shade, Partial Shade', 'Moderate', null, 'Chaparral, Foothill Woodland, Mixed Evergreen Forest, Wetland-Riparian', 'Requires moist soil. Prefers shade. Likes moist slopes.', null, 'https://calscape.org/Aquilegia-eximia-%28Van-Houtte%27s-Columbine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aquilegia formosa', 'Western Columbine', 'Bats, Birds, Butterflies, Caterpillars', 'Red, Yellow', 'Spring', 'Full Sun, Partial Shade, Deep Shade', 'Low, Moderate', 'Trees - Coast Redwood (Sequoia sempervirens), Santa Lucia Fir (Abies bracteata), Douglas Fir (Pseudotsuga menziesii), and many others. <br><br>Shrubs and herbs - Meadow Rue (Thalictrum fendleri), Snowdrop Bush (Styrax redivivus), Yellow Monkeyflower (Erythranthe guttata), Western Azalea (Rhododendron occidentale), and Huckleberry (Vaccinum ovatum).', 'Chaparral, Lodgepole Forest, Northern Juniper Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. It requires a minimum of 15 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. Prefers shade. Likes stream banks.  This plant needs plenty of water throughout the year. Water weekly.', null, 'https://calscape.org/Aquilegia-formosa-%28Western-Columbine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aquilegia formosa ''Yellow''', 'Yellow Scarlet Columbine', 'Bats, Birds, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Full Sun, Partial Shade, Deep Shade', 'Low, Moderate', 'Trees - Coast Redwood (Sequoia sempervirens), Santa Lucia Fir (Abies bracteata), Duoglas Fir (Pseudotsuga menziesii), and many others. <br><br>Shrubs and herbs - Meadow Rue (Thalictrum fendleri), Snowdrop Bush (Styrax redivivus), Yellow Monkeyflower (Erythranthe guttata), Western Azalea (Rhododendron occidentale), and Huckleberry (Vaccinum ovatum).', null, null, null, 'https://calscape.org/Aquilegia-formosa-%27Yellow%27-%28Yellow-Scarlet-Columbine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aquilegia pubescens', 'Sierra Columbine', 'Birds, Butterflies, Caterpillars', 'Pink, Yellow, White', null, 'Deep Shade, Partial Shade', 'Low, Moderate', null, 'Alpine Fell-Fields, Subalpine Forest', 'Requires fast draining soil. Prefers shade. Likes rocky slopes.', null, 'https://calscape.org/Aquilegia-pubescens-%28Sierra-Columbine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aquilegia shockleyi', 'Desert Columbine', 'Birds', null, null, 'Full Sun, Partial Shade', 'Low, Moderate', null, 'Pinyon-Juniper Woodland, Wetland-Riparian', 'Requires moist soil. Prefers sun, part shade.', null, 'https://calscape.org/Aquilegia-shockleyi-%28Desert-Columbine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arabis blepharophylla', 'Coast Rockcress', 'Butterflies, Caterpillars', 'Pink, Purple', 'Winter, Spring', 'Partial Shade', 'Low, Moderate', null, 'Coastal Prairie, Mixed Evergreen Forest, Northern Coastal Scrub', 'Prefers part shade.', null, 'https://calscape.org/Arabis-blepharophylla-%28Coast-Rockcress%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arabis blepharophylla ''Spring Charm''', 'Spring Charm Coast Rock Cress', 'Butterflies, Caterpillars', 'Pink', 'Spring', 'Partial Shade', 'Low, Moderate', null, null, null, null, 'https://calscape.org/Arabis-blepharophylla-%27Spring-Charm%27-%28Spring-Charm-Coast-Rock-Cress%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arabis eschscholtziana', null, 'Butterflies, Caterpillars', 'White', null, null, 'Low, Moderate', null, null, null, null, 'https://calscape.org/Arabis-eschscholtziana-%28%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arabis holboellii', 'Holboell''s Rock Cress', 'Butterflies, Caterpillars', 'Purple', 'Spring', 'Partial Shade', 'Low, Moderate', null, 'Lodgepole Forest, Mixed Evergreen Forest, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 5.4-7.4. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Arabis holboellii is moderately drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 60 inches of water per year once established. It is moderately tolerant of shade. Prefers partial shade.', null, 'https://calscape.org/Arabis-holboellii-%28Holboell%27s-Rock-Cress%29');
