INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aralia californica', 'Elk''s Clover', 'Bees, Butterflies, Caterpillars', 'White, Green', 'Summer, Fall', 'Deep Shade, Partial Shade', 'High, Moderate', 'Use under trees such as Coast Redwood (Sequoia sempervirens), Firs (<a href="/search/?plant=Abies%20(Genus)">Abies spp.</a>), Maples (<a href="/search/?plant=Acer%20(Genus)">Acer spp.</a>), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Bay Laurel (Umbellularia californica), Chinquapin (Chrysolepis chrysophylla or sempervirens), and Tanoak (Notholithocarpus densiflorus), along with other shade-loving and moisture loving plants such as native ferns, Wild Ginger (Asarum caudatum), Columbine (Aquilegia formosa), Chinese Houses (Collinsia heterophylla), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Bleeding Heart, and Bigflower Tellima (Tellima grandiflora).', 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Aralia-californica-%28Elk%27s-Clover%29');
