INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Argemone corymbosa', 'Prickly Poppy', 'Butterflies, Caterpillars', 'White, Orange', 'Spring', 'Full Sun', 'Low, Very Low', null, 'Creosote Bush Scrub', 'Prefers sun. Likes dry flats and slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Argemone-corymbosa-%28Prickly-Poppy%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Argemone munita', 'Chicalote', 'Butterflies, Caterpillars', 'White, Green', null, 'Full Sun', 'Low, Very Low', null, 'Chaparral, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun.', null, 'https://calscape.org/Argemone-munita-%28Chicalote%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aristocapsa insignis', 'Indian Valley Spineflower', null, 'Pink', null, null, null, null, null, null, null, 'https://calscape.org/Aristocapsa-insignis-%28Indian-Valley-Spineflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Armeria maritima', 'Thrift Seapink', 'Butterflies', 'Purple, Pink', 'Spring', 'Full Sun, Partial Shade', 'Moderate', 'Giant Coreopsis (Leptosyne gigantea), Bluff Lettuce (Dudleya farinosa),Coast Dudleya (Dudleya caespitosa), Seaside Fleabane (Erigeron glaucus), Coast Eriogonum (Eriogonum latifolium), Pink Sand Verbena (Abronia umbellata), Gumweed (Grindelia stricta var platyphylla)', 'Closed-cone Pine Forest, Northern Coastal Scrub', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 4.7-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Armeria maritima is only slightly drought tolerant. It requires a minimum of 32 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. It does not tolerate full shade well. Prefers part shade. Likes ocean bluffs.', null, 'https://calscape.org/Armeria-maritima-%28Thrift-Seapink%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Armeria maritima ''Alba''', 'White Sea Thrift', 'Bees, Butterflies', 'White', 'Summer, Spring', 'Full Sun', 'Low', null, null, null, null, 'https://calscape.org/armeria-maritima-alba-alba-sea-thrift');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Armeria maritima ssp. californica', 'California Sea Pink', null, 'Pink', 'Spring', 'Partial Shade', 'Moderate', null, 'Closed-cone Pine Forest, Northern Coastal Scrub', 'Requires fast draining soil. Prefers part shade. Likes sandy soils.', null, 'https://calscape.org/Armeria-maritima-ssp.-californica-%28California-Sea-Pink%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica cernua', 'Serpentine Arnica', null, null, null, 'Full Sun, Partial Shade', null, null, null, null, null, 'https://calscape.org/Arnica-cernua-%28Serpentine-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica chamissonis', 'Chamisso Arnica', null, 'Yellow', 'Summer, Spring', 'Deep Shade, Partial Shade', 'Low, Moderate, High', null, 'Bristlecone Pine Forest, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 6-7.2. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Arnica chamissonis is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 24 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade.', null, 'https://calscape.org/Arnica-chamissonis-%28Chamisso-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica cordifolia', 'Heartleaf Arnica', null, 'Yellow, White', 'Spring', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Arnica cordifolia is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 35 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Arnica-cordifolia-%28Heartleaf-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica fulgens', 'Hillside Arnica', null, 'Yellow', 'Spring', null, null, null, null, null, null, 'https://calscape.org/Arnica-fulgens-%28Hillside-Arnica%29');
