INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica lanceolata ssp. prima', 'Streambank Arnica', null, 'Brown', null, 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Subalpine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-7.3. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Arnica amplexicaulis is only slightly drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 40 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Arnica-lanceolata-ssp.-prima-%28Streambank-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica latifolia', 'Mountain Arnica', null, 'Yellow', 'Summer', 'Full Sun, Partial Shade', null, null, 'Subalpine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 6-7.2. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Arnica latifolia is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 40 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'https://calscape.org/Arnica-latifolia-%28Mountain-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica longifolia', 'Seep Spring Arnica', null, 'Yellow, Orange, Green, Red', 'Summer', 'Deep Shade, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 6-8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Arnica longifolia is not drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Arnica-longifolia-%28Seep-Spring-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica mollis', 'Cordillerean Anica', null, 'Yellow', 'Summer', 'Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 2 inches deep, with a pH of 5-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Arnica mollis is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 100 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers part shade.', null, 'https://calscape.org/Arnica-mollis-%28Cordillerean-Anica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica nevadensis', 'Sierra Arnica', null, 'Yellow', null, null, null, null, 'Alpine Fell-Fields, Lodgepole Forest, Red Fir Forest, Subalpine Forest', null, null, 'https://calscape.org/Arnica-nevadensis-%28Sierra-Arnica%29');
