INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica parryi', 'Nodding Arnica', null, 'Yellow', null, null, null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', null, null, 'https://calscape.org/Arnica-parryi-%28Nodding-Arnica%29');
