INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arnica spathulata', 'Klamath Arnica', null, 'Yellow', null, null, null, null, null, null, null, 'https://calscape.org/Arnica-spathulata-%28Klamath-Arnica%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia borealis', 'Field Sagewort', null, 'Cream, White, Yellow', null, 'Full Sun', 'Low, Moderate', null, 'Meadows', 'Requires moist soil. Prefers sun.', null, 'https://calscape.org/Artemisia-borealis-%28Field-Sagewort%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia borealis ssp. borealis', 'Boreal Sage', null, 'Cream, White, Yellow', null, null, 'Low, Moderate', null, null, null, null, 'https://calscape.org/Artemisia-borealis-ssp.-borealis-%28Boreal-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia douglasiana', 'Mugwort', 'Bats, Birds, Butterflies, Caterpillars', 'Yellow, Cream, White', 'Summer, Spring, Fall', 'Full Sun, Partial Shade, Deep Shade', 'Low, Moderate', '<p>Use with other plants of moist areas, such as Indigo Bush (Amorpha fruticosa), Mule Fat (Baccharis salicifolia), dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), rush (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), sedge (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), currant/gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), wild rose (<a href="/search/?plant=Rosa%20(Genus)">Rosa spp.</a>), willow (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), and wild grape (<a href="/search/?plant=Vitis%20(Genus)">Vitis spp.</a>).</p>', 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Requires moist soil. Grows well in sun, shade or part shade. Likes wet soils. This plant is tough and easy to grow. It''s extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s still very garden tolerant, and not particularly sensitive to pathogens that grow in warm moist soils. It can usually handle weekly summer watering.</p>', null, 'https://calscape.org/Artemisia-douglasiana-%28Mugwort%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia dracunculus', 'Wild Tarragon', 'Bats, Birds, Butterflies, Caterpillars', 'Yellow, Cream, White', 'Summer, Fall', 'Full Sun', 'Low, Moderate', '<p>Can be used with a very wide range of plants</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Joshua Tree Woodland, Red Fir Forest, Valley Grassland, Yellow Pine Forest', '<p>Requires fast draining soil. Prefers sun. Likes moist soils.</p>', null, 'https://calscape.org/Artemisia-dracunculus-%28Wild-Tarragon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia ludoviciana', 'Silver Wormwood', 'Bats, Birds, Butterflies, Caterpillars', 'White, Cream, Yellow', 'Summer, Spring, Fall', 'Full Sun', 'Low, Moderate', null, 'Creosote Bush Scrub, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 6-9. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Artemisia ludoviciana is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 60 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes dry rocky slopes.  This plant is not particularly drought tolerant.  It likes summer water every 4 weeks.', null, 'https://calscape.org/Artemisia-ludoviciana-%28Silver-Wormwood%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia ludoviciana ssp. albula', 'White Mugwort', 'Bats, Birds, Butterflies, Caterpillars', 'Cream, White, Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low, Moderate', null, null, 'Prefers sun. Likes dry rocky slopes.', null, 'https://calscape.org/Artemisia-ludoviciana-ssp.-albula-%28White-Mugwort%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia ludoviciana ssp. candicans', 'White Sagebrush', 'Butterflies, Caterpillars', 'Cream, White, Yellow', null, null, 'Low, Moderate', null, null, null, null, 'https://calscape.org/Artemisia-ludoviciana-ssp.-candicans-%28White-Sagebrush%29');
