INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Artemisia pycnocephala', 'Dune Sagewort', 'Bats, Birds, Butterflies, Caterpillars', 'Cream, White, Yellow', 'Spring, Summer', 'Full Sun', 'Low, Moderate', 'Use with other species of coastal strand such as Verbena (<a href="/search/?plant=Abronia%20(Genus)">Abronia spp.</a>), Beach Morning Glory (Calystegia soldanella), Beach Evening-primrose (Camissioniopsis cheiranthifolia), Cobweb Thistle (Cirsium occidentale), Seaside Daisy (Erigeron glaucus), Coast Buckwheat (Eriogonum latifolium), Seaside Golden Yarrow (Eriophyllum staechadifolium), Gumweed (Grindelia stricta), Lupine (Lupinus spp., and Silverweed Potentilla anserina)', 'Coastal Strand', 'Requires fast draining soil. Prefers sun. Likes rocky or sandy soils.  This plant is not particularly drought tolerant.  It likes summer water every 2-4 weeks.', null, 'https://calscape.org/Artemisia-pycnocephala-%28Dune-Sagewort%29');
