INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Arthrocnemum subterminale', 'Parish''s Pickleweed', null, null, null, 'Full Sun', 'Moderate, High', null, 'Alkali Sink, Coastal Sage Scrub, Coastal Salt Marsh, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes saline or alkaline soils.  This plant needs plenty of water throughout the year.  Water 1-2 times per week.', null, 'https://calscape.org/Arthrocnemum-subterminale-%28Parish%27s-Pickleweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Aruncus dioicus', 'Bride''s Feathers', null, 'White', 'Summer', 'Partial Shade', 'Moderate', null, 'Douglas-Fir Forest, Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers part shade. Likes moist slopes.', null, 'https://calscape.org/Aruncus-dioicus-%28Bride%27s-Feathers%29');
