INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias vestita', 'Woolly Milkweed', 'Butterflies, Caterpillars', 'Cream, Yellow', null, null, 'Low, Very Low', null, 'Chaparral, Foothill Woodland, Valley Grassland', null, null, 'https://calscape.org/Asclepias-vestita-%28Woolly-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asarum caudatum', 'Wild Ginger', null, 'Brown, Purple, Yellow', 'Spring', 'Deep Shade, Partial Shade', 'High, Moderate', 'Use as understory to large trees such as Coast Redwood (Sequoia sempervirens), Douglas Fir (Pseudotsuga menziesii), Yellow Pine (Pinus ponderosa) and many other trees of northern California. Mix with other shade-loving forest plants such as native ferns, Meadow Rue (Thalictrum fendleri), and Elkclover (Aralia californica)', 'Douglas-Fir Forest, Redwood Forest, Yellow Pine Forest', 'Requires moist soil. Prefers part shade.', null, 'https://calscape.org/Asarum-caudatum-%28Wild-Ginger%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asarum hartwegii', 'Wild Ginger', null, 'Brown, White, Purple, Red', 'Spring, Summer', 'Full Sun, Partial Shade, Deep Shade', 'Moderate', null, 'Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Grows well in sun, shade or part shade. Likes dry rocky slopes.', null, 'https://calscape.org/Asarum-hartwegii-%28Wild-Ginger%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asarum lemmonii', 'Lemmon''s Wild Ginger', null, 'Brown, White, Green, Red', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Moderate', null, 'Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes wet soils.', null, 'https://calscape.org/Asarum-lemmonii-%28Lemmon%27s-Wild-Ginger%29');
