INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias asperula', 'Spider Milkweed', 'Birds, Butterflies, Caterpillars', 'Cream, Yellow, Green, Purple', 'Spring, Summer, Fall', 'Full Sun', 'Low, Very Low', null, 'Pinyon-Juniper Woodland', 'Prefers sun. Likes dry rocky soils.', null, 'https://calscape.org/Asclepias-asperula-%28Spider-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias asperula ssp. asperula', 'Antelope-horns', 'Butterflies, Caterpillars', 'Cream, Red', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Asclepias-asperula-ssp.-asperula-%28Antelope-horns%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias californica', 'California Milkweed', 'Birds, Butterflies, Caterpillars', 'Lavender, Pink, White', 'Spring, Summer', 'Full Sun', 'Low, Very Low', 'Milkweeds are most often used to create a butterfly garden. A wide variety of trees and shrubs can be used, including Madrone (Arbutus menziesii), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Junipers (<a href="/search/?plant=Juniperus%20(Genus)">Juniperus spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), and Coyote Brush (<a href="/search/?plant=Baccharis%20(Genus)">Baccharis spp.</a>). Also include other butterfly-attracting herbs such as members of the Asteraceae family, other Milkweeds (Asclepias fascicularis or A. speciosa), Thistles (<a href="/search/?plant=Cirsium%20(Genus)">Cirsium spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Mint (<a href="/search/?plant=Monardella%20(Genus)">Monardella spp.</a>), and Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>). To provide year-round attraction, mix early bloomers with late bloomers and evergreens with deciduous.', 'Chaparral, Pinyon-Juniper Woodland, Yellow Pine Forest', 'Prefers sun. Likes flats and slopes.', 'It is important to avoid all chemical pest control around milkweeds to protect Monarch butterflies and caterpillars.', 'https://calscape.org/Asclepias-californica-%28California-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias cordifolia', 'Heart Leaf Milkweed', 'Birds, Butterflies, Caterpillars', 'Purple, Lavender, Red', 'Spring, Summer', 'Partial Shade, Full Sun', 'Low, Very Low', null, 'Chaparral, Foothill Woodland, Mixed Evergreen Forest, Yellow Pine Forest', '<p>Prefers part shade. Likes rocky slopes and talus lava flows.</p>', null, 'https://calscape.org/Asclepias-cordifolia-%28Heart-Leaf-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias cryptoceras', 'Pallid Milkweed', 'Butterflies, Caterpillars', 'Cream, Red, Pink', null, 'Full Sun, Partial Shade', 'Low, Very Low', null, 'Pinyon-Juniper Woodland, Sagebrush Scrub', 'Prefers sun, part shade. Likes sandy or gravelly slopes.', null, 'https://calscape.org/Asclepias-cryptoceras-%28Pallid-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias eriocarpa', 'Woollypod Milkweed', 'Birds, Butterflies, Caterpillars', 'Cream, Pink, White', 'Summer', 'Full Sun, Partial Shade', 'Low, Very Low', 'Many companions including Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Fir (<a href="/search/?plant=Abies%20(Genus)">Abies spp.</a>), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Sagebrush (<a href="/search/?plant=Artemisia%20(Genus)">Artemisia spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>, Yerba Santa (<a href="/search/?plant=Eriodictyon%20(Genus)">Eriodictyon spp.</a>), Woolly Bluecurls (Trichostema lanatum), and many others', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Valley Grassland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun. Likes dry soils.', 'It is recommended that no pest control be used because this species is host plant to the Monarch butterfly and will be eaten by Monarch caterpillars', 'https://calscape.org/Asclepias-eriocarpa-%28Woollypod-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias erosa', 'Desert Milkweed', 'Birds, Butterflies, Caterpillars', 'Cream, Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low, Very Low', null, 'Creosote Bush Scrub, Joshua Tree Woodland, Pinyon-Juniper Woodland, Valley Grassland', 'Prefers sun. Likes dry slopes and sandy soils.', null, 'https://calscape.org/Asclepias-erosa-%28Desert-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias fascicularis', 'Narrow Leaf Milkweed', 'Birds, Butterflies, Caterpillars', 'Lavender, Pink, White', 'Summer, Fall', 'Full Sun', 'Low, Very Low', '<p>Works well with a wide variety of other plants but is best located where its winter leaf loss and summer consumption by caterpillars will not be the center of attention. Also, plant a number of milkweeds in proximity so caterpillars will have sufficient amounts to eat.</p><p><br></p><p>Use with showy, nectar-rich plants that will also attract adult Monarchs, such as Indian Mallow (Abutilon palmeri), Ceanothus species, Western Thistle (Cersium occidentale), California Aster (Corethrogyne filaginifolia), California Fuchsia (Epilobium canum), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Mint (<a href="/search/?plant=Monardella%20(Genus)">Monardella spp.</a>), Monkeyflower (<a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Sages (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Apricot Mallow (Sphaeralcea ambigua).</p>', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Requires fast draining soil. Prefers sun, and will produce less flowers in partial shade. Likes dry slopes. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils, but can handle clay and some seasonal flooding. It can usually handle summer watering as much as every other week. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', 'It is crucial to not use any pesticide on this plant or in its vicinity, because doing so will be fatal to Monarch caterpillars.', 'https://calscape.org/Asclepias-fascicularis-%28Narrow-Leaf-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias nyctaginifolia', 'Mojave Milkweed', 'Butterflies, Caterpillars', 'Green, White, Purple, Pink', null, 'Full Sun', 'Low, Very Low', null, 'Pinyon-Juniper Woodland', 'Prefers sun. Likes dry slopes and sandy soils.', null, 'https://calscape.org/Asclepias-nyctaginifolia-%28Mojave-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias solanoana', 'Serpentine Milkweed', 'Butterflies, Caterpillars', 'White, Red', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Asclepias-solanoana-%28Serpentine-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias speciosa', 'Showy Milkweed', 'Birds, Butterflies, Caterpillars', 'Purple, Pink, White', 'Summer', 'Full Sun', 'Very Low, Low', null, 'Chaparral, Mixed Evergreen Forest, Wetland-Riparian, Yellow Pine Forest', '<p>Plant in sandy, loamy or clay soils that are at least 18 inches deep, with a pH of 5-7. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, tolerant of alkaline soils, and requires only moderately fertile soils. It requires a minimum of 16 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It does not tolerate shade well and prefers sun. It likes summer water every 2-4 weeks.</p>', null, 'https://calscape.org/Asclepias-speciosa-%28Showy-Milkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Asclepias speciosa ''Davis''', 'Davis Showy Milkweed', 'Birds, Butterflies, Caterpillars', 'Pink', 'Spring, Summer', 'Full Sun', 'Low, Very Low', null, null, null, null, 'https://calscape.org/Asclepias-speciosa-%27Davis%27-%28Davis-Showy-Milkweed%29');
