INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Balsamorhiza hookeri', 'Hooker''s Balsamroot', null, 'Yellow', 'Spring', 'Full Sun', null, null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 18 inches deep, with a pH of 6.6-9. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Balsamorhiza hookeri is moderately drought tolerant. It requires a minimum of 9 inches of water per year, and a maximum of 20 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes slopes.', null, 'https://calscape.org/Balsamorhiza-hookeri-%28Hooker%27s-Balsamroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Balsamorhiza lanata', 'Woolly Balsamroot', null, 'Yellow, White', null, null, null, null, null, null, null, 'https://calscape.org/Balsamorhiza-lanata-%28Woolly-Balsamroot%29');
