INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Balsamorhiza sagittata', 'Arrow Leaved Balsam Root', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 14 inches deep, with a pH of 6.5-8. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Balsamorhiza sagittata is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 25 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'https://calscape.org/Balsamorhiza-sagittata-%28Arrow-Leaved-Balsam-Root%29');
