INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Bidens laevis', 'Bur Marigold', 'Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'High, Moderate', null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 5-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Bidens laevis is only slightly drought tolerant. It requires a minimum of 24 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.This plant is tough and fairly easy to grow.  It''s very drought tolerant. After established, it should survive the dry months with no supplementary water. It''s also very garden tolerant, and can handle weekly watering without much trouble.', null, 'https://calscape.org/Bidens-laevis-%28Bur-Marigold%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Bistorta bistortoides', 'Western Bistort', 'Butterflies, Caterpillars', 'Pink, White', null, 'Full Sun', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 16 inches deep, with a pH of 6.5-8. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Polygonum bistortoides is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 30 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes wet meadows.', null, 'https://calscape.org/Bistorta-bistortoides-%28Western-Bistort%29-2');
