INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Boykinia occidentalis', 'Brook Foam', null, 'White', 'Summer', 'Partial Shade', 'High, Moderate', 'This plant is best used in a damp shade garden with similar plants such as <a href="/search/?plant=Heuchera%20(Genus)">Heuchera spp.</a>, ferns, Meadow Rue (<a href="/search/?plant=Thalictrum%20(Genus)">Thalictrum spp.</a>), Western Dichondra (Dichondra occidentalis), Wild Ginger (<a href="/search/?plant=Asarum%20(Genus)">Asarum spp.</a>), and False Lily of the Valley (Maianthemum dilatatum)', 'Chaparral, Mixed Evergreen Forest, Northern Coastal Scrub, Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes wet stream banks.', null, 'https://calscape.org/Boykinia-occidentalis-%28Brook-Foam%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Boykinia rotundifolia', 'Round Leaved Boykinia', null, 'White', 'Spring, Summer', 'Partial Shade', 'Moderate, High', 'This plant is best used in a damp shade garden with similar plants such as <a href="/search/?plant=Heuchera%20(Genus)">Heuchera spp.</a>, ferns, Meadow Rue (<a href="/search/?plant=Thalictrum%20(Genus)">Thalictrum spp.</a>), and Western Dichondra (Dichondra occidentalis)', 'Chaparral, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes stream banks.', null, 'https://calscape.org/Boykinia-rotundifolia-%28Round-Leaved-Boykinia%29');
