INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Brodiaea elegans', 'Harvest Brodiaea', 'Butterflies', 'Blue, Lavender, Purple, White', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Very Low', '<p>Use with other geophytes such as wild onion (Allium hyalinum or peninsulare) or Yellow Mariposa Lily (Calochortus luteus). Also with annuals or herbaceious perennials such as Milkweed (Asclepias fascicularis or vestita), Owl''s Clover (Castilleja exserta), Clarkia (Clarkia purpurea or unguiculata), Chinese Houses (Collinsia heterphylla), Royal Larkspur (Delphinium variegatum), California Poppy (Eschscholzia californica), Tricolor Gilia (Gilia tricolor), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>)</p>', 'Foothill Woodland, Valley Grassland, Yellow Pine Forest', '<p>Prefers sun or part shade. Likes moist places.</p>', null, 'https://calscape.org/Brodiaea-elegans-%28Harvest-Brodiaea%29');
