INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus luteus', 'Yellow Mariposa Lily', 'Butterflies, Caterpillars', 'Yellow, Red', 'Spring', 'Full Sun, Partial Shade', 'Low, Very Low', 'Plant with annuals, herbaceous perennials, or other geophytes, including wild onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Indian Milkweed (Asclepias eriocarpa), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, <a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>, California Poppy (Eschscholzia californica or other species), Bird''s Eye Gilia (Gilia tricolor), Tidy Tips (<a href="/search/?plant=Layia%20(Genus)">Layia spp.</a>), Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Baby Blue Eyes (Nemophila menziesii), Heliotrope (<a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>), Checkerbloom (<a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>), <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a>', 'Foothill Woodland, Mixed Evergreen Forest, Valley Grassland', 'Requires fast draining soil. Prefers sun or part shade. Likes heavy soils.', null, 'https://calscape.org/Calochortus-luteus-%28Yellow-Mariposa-Lily%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus macrocarpus', 'Sagebrush Mariposa', null, 'Purple, Pink', 'Summer', 'Full Sun, Partial Shade', 'Low, Very Low', null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 5.7-7. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Calochortus macrocarpus is extremely drought tolerant. It requires a minimum of 7 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes volcanic soil.', null, 'https://calscape.org/Calochortus-macrocarpus-%28Sagebrush-Mariposa%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus minimus', 'Sierra Mariposa Lily', null, 'White', null, 'Full Sun', 'Low, Very Low', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian, Yellow Pine Forest', null, null, 'https://calscape.org/Calochortus-minimus-%28Sierra-Mariposa-Lily%29');
