INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus splendens ''Violet Queen''', 'Violet Queen Splendid Mariposa Lily', 'Butterflies, Caterpillars', 'Purple', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Very Low', 'In the garden it works well with other geophytes such as Wild Onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Golden Star (<a href="/search/?plant=Bloomeria%20(Genus)">Bloomeria spp.</a>), Blue Dicks (<a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a>), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Lilies (<a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>), and <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a> Also works with native grasses and herbs, but avoid larger shrubs or the Calochortus may get lost in the understory.', null, null, null, 'https://calscape.org/Calochortus-splendens-%27Violet-Queen%27-%28Violet-Queen-Splendid-Mariposa-Lily%29');
