INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus venustus ''Burgundy''', 'Burgundy Mariposa Lily', 'Butterflies, Caterpillars', 'Purple', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Very Low', 'Grassland species such as other Calochortus species, Allium species, Milkweeds (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Brodiaea species, Amole (<a href="/search/?plant=Chlorogalum%20(Genus)">Chlorogalum spp.</a>), Dichelostemma species, Firtillaria species, various native grasses and various annual wildflowers', null, null, null, 'https://calscape.org/Calochortus-venustus-%27Burgundy%27-%28Burgundy-Mariposa-Lily%29');
