INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Calochortus weedii', 'Weed''s Mariposa Lily', 'Butterflies, Caterpillars', 'Cream, Orange, Purple, Red, Yellow', 'Spring, Summer', 'Full Sun', 'Low, Very Low', 'Use with chaparral shrubs and sub-shrubs such as Lotus (<a href="/search/?plant=Acmispon%20(Genus)">Acmispon spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Spice Bush (Cneoridium dumosum), Bush Poppy (Dendromecon rigida), California Encelia (Encelia californica), Brickell Bush (Brickellia californica), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, California Fuchsia (Epilobium canum), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), and various cactus and succulent species', 'Chaparral', 'Prefers sun. Likes heavy or rocky soil.', 'Gophers will eat most types of bulbs', 'https://calscape.org/Calochortus-weedii-%28Weed%27s-Mariposa-Lily%29');
