INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Camassia quamash', 'Common Camas', null, 'Blue, Purple, Pink, Lavender', 'Spring', 'Full Sun, Partial Shade', 'Moderate', null, 'Mixed Evergreen Forest, North Coastal Coniferous Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 5.7-7. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. It requires a minimum of 16 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Camassia-quamash-%28Common-Camas%29');
