INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Camissoniopsis cheiranthifolia', 'Beach Primrose', 'Butterflies, Caterpillars', 'Red, Yellow', 'Summer, Spring, Winter', 'Full Sun', 'Very Low, Low', '<p>Coast Eriogonum (Eriogonum latifolium),Sand Verbena (<a href="/search/?plant=Abronia%20(Genus)">Abronia spp.</a>), Pt. Reyes Ceanothus (Ceanothus gloriosus), Twinberry (Lonicera involucrata), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Bluff Lettuce (Dudleya farinosa), Coast Silktassel (Garrya elliptica), Yellow Stonecrop (Sedum spathulifolium), and Dune Manzanita (Arctostaphylos pumila), Coastal plants such as other Verbena species (Abronia maritima, Abronia umbellata), Common Yarrow (Achillea millefolium), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Saltbush species (<a href="/search/?plant=Atriplex%20(Genus)">Atriplex spp.</a>), Cakile maritima, Morning-glory species (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Sandcarpet (Cardionema ramosissimum), Croton (Croton californicus), Seaside Daisy species (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Buckwheat species (Eriogonum latifolium, Eriogonum parvifolium), Seaside Woolly Sunflower (Eriophyllum staechadifolium), Wallflower (<a href="/search/?plant=Erysimum%20(Genus)">Erysimum spp.</a>), Beach Strawberry (Fragaria chiloensis), Coastal Gumplant (Grindelia stricta)</p>', 'Coastal Strand', '<p>Prefers sun. Likes sandy slopes. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Camissoniopsis-cheiranthifolia-%28Beach-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Camissoniopsis cheiranthifolia ssp. cheiranthifolia', 'Beach Evening Primrose', 'Butterflies, Caterpillars', 'Yellow', null, 'Full Sun', 'Low, Very Low', null, null, 'Prefers sun. Likes sandy slopes.', null, 'https://calscape.org/Camissoniopsis-cheiranthifolia-ssp.-cheiranthifolia-%28Beach-Evening-Primrose%29');
