INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Castilleja exserta', 'Purple Owl''s Clover', 'Bats, Bees, Butterflies, Caterpillars', 'Lavender, Pink, Purple, White', 'Spring', 'Full Sun', 'Very Low, Low', 'Use in a meadow-like planting with other annuals such as <a href="/search/?plant=Clarkis%20(Genus)">Clarkis spp.</a>, California Poppy (Eschscholzia californica), Baby Blue-eyes (Nemophila menziesii), and Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>); also with geophytes such as wild onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Ithuriels''s Spear (Triteleia laxa), Blue Dicks (Dichelostemma capitatum), and Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>).', 'Chaparral, Coastal Sage Scrub, Coastal Strand, Creosote Bush Scrub, Foothill Woodland, Joshua Tree Woodland, Northern Coastal Scrub, Valley Grassland', 'Prefers sun. Likes grassy areas.', null, 'https://calscape.org/Castilleja-exserta-%28Purple-Owl%27s-Clover%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Castilleja exserta ssp. exserta', 'Pale Purple Owlclover', 'Bees, Butterflies, Caterpillars', 'Lavender, Purple', null, null, null, null, null, 'Prefers sun. Likes grassy areas.', null, 'https://calscape.org/Castilleja-exserta-ssp.-exserta-%28Pale-Purple-Owlclover%29');
