INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Castilleja foliolosa', 'Texas Paintbrush', 'Butterflies, Caterpillars', 'Red, Orange, Yellow, Green, White', 'Spring, Winter', 'Full Sun', 'Extremely Low, Very Low', '<p>It is found with most chaparral plants to which it attaches itself by the roots in a parasitic or semi-parasitic manner.</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Northern Coastal Scrub, Southern Coastal Scrub, Valley Grassland, Yellow Pine Forest', '<p>Requires fast draining soil. Prefers sun. Likes dry soils and rocky slopes.</p>', null, 'https://calscape.org/Castilleja-foliolosa-%28Texas-Paintbrush%29');
