INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Castilleja hispida', 'Harsh Indian Paintbrush', 'Butterflies, Caterpillars', 'Red, Red', 'Spring', 'Partial Shade', null, null, 'Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Castilleja hispida is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 19 inches of water per year once established. It does not tolerate full shade well. Prefers part shade.', null, 'https://calscape.org/Castilleja-hispida-%28Harsh-Indian-Paintbrush%29');
