INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Chaenactis artemisiifolia', 'Artemisia Leaved Chaenactis', 'Birds, Butterflies, Caterpillars', 'White, Pink', 'Spring', 'Full Sun', 'Very Low', 'Use with other annuals, perennials and shrubs of coastal southern California, such as Coyote Brush (Baccharis pilularis), Sweetbush (Bebbia juncea), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), California Poppy (Eschscholzia californica), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Matilija Poppy (Romneya coulteri or trichocalyx), Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), and various cactus species', 'Chaparral, Coastal Sage Scrub', 'Prefers sun. Likes slopes.', null, 'https://calscape.org/Chaenactis-artemisiifolia-%28Artemisia-Leaved-Chaenactis%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Chaenactis carphoclinia', 'Pebble Pincushion', 'Butterflies, Caterpillars', 'White, Cream', null, null, null, null, 'Alkali Sink, Creosote Bush Scrub', null, null, 'https://calscape.org/Chaenactis-carphoclinia-%28Pebble-Pincushion%29');
