INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Chaenactis douglasii', 'Hoary Chaenactis', 'Butterflies, Caterpillars', 'White', 'Summer', 'Full Sun', null, null, 'Chaparral, Lodgepole Forest, Northern Juniper Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 5.8-7. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Chaenactis douglasii is moderately drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 60 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes dry slopes.', null, 'https://calscape.org/Chaenactis-douglasii-%28Hoary-Chaenactis%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Chaenactis douglasii var. alpina', 'Alpine Dusty-maidens', 'Butterflies, Caterpillars', null, null, null, null, null, null, null, null, 'https://calscape.org/Chaenactis-douglasii-var.-alpina-%28Alpine-Dusty-maidens%29');
