INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Chaenactis glabriuscula', 'Common Yellow Chaenactis', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Winter, Spring, Summer', 'Full Sun', 'Very Low', 'Use with other annuals, perennials and shrubs of dry areas such as Coyote Brush (Baccharis pilularis), Sweetbush (Bebbia juncea), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), California Poppy (Eschscholzia californica), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Matilija Poppy (Romneya coulteri or trichocalyx), Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), and various cactus species', 'Chaparral, Coastal Sage Scrub, Coastal Strand, Foothill Woodland, Southern Oak Woodland, Valley Grassland, Yellow Pine Forest', 'Prefers sun. Likes dry soils.', null, 'https://calscape.org/Chaenactis-glabriuscula-%28Common-Yellow-Chaenactis%29');
