INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia amoena', 'Farewell To Spring', 'Bats, Bees, Butterflies, Caterpillars', 'Lavender, Pink, Purple, Red', 'Spring, Summer', 'Full Sun', 'Low', 'Mixes well with other annuals, especially blues such as Lupinus species, Baby Blue Eyes (Nemophila menziesii), Globe Gilia (Gilia capitata); yellows/oranges/golds such as Tidy Tips (Layia playgloss), Western Wallflower (Erysimum capitatum) and California Poppy (Eschscholzia californica). Also good with perennial herbs such as Western Columbine (Aquiligia formosa), Phacelia species, and bulbs/corms such as Calochortus species.', 'Coastal Prairie, Mixed Evergreen Forest, Northern Coastal Scrub, Northern Oak Woodland, Forest', 'Prefers sun. Likes spring-moist, soils.', null, 'https://calscape.org/Clarkia-amoena-%28Farewell-To-Spring%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia amoena ''Aurora''', 'Aurora Farewell-to-Spring', 'Bats, Bees', 'Pink, White', 'Summer, Spring', 'Full Sun', null, null, null, null, null, 'https://calscape.org/Clarkia-amoena-%27Aurora%27-%28Aurora-Farewell-to-Spring%29');
