INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia bottae', 'Punch Bowl Godetia', 'Bats, Bees, Butterflies, Caterpillars', 'Pink, Purple, Lavender, Red', 'Spring', 'Partial Shade, Full Sun', 'Low', 'Use with native grasses, other annuals and herbaceous perennials such as Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), Owl''s Clover (Castilleja exserta), Chinese Houses (Collinsia heterophylla), Blue Dicks (Dichelostemma capitatum), California Poppy (Eschscholzia californica), Tricolor Gilia (Gilia tricolor), Tidy Tips (Layia platyglossa), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Baby Blue Eyes (Nemophila menziesii), Wind Poppy (Papaver heterphyllum), and <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>', 'Chaparral, Closed-cone Pine Forest, Coastal Sage Scrub, Foothill Woodland, Mixed Evergreen Forest, Southern Oak Woodland', 'Prefers sun or part shade.', null, 'https://calscape.org/Clarkia-bottae-%28Punch-Bowl-Godetia%29');
