INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia gracilis', 'Farewell To Spring', 'Bees, Butterflies, Caterpillars', 'Purple, Pink, White, Lavender, Red', 'Spring', 'Full Sun', null, null, 'Foothill Woodland, Mixed Evergreen Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 6.4-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Clarkia gracilis is extremely drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 24 inches of water per year once established. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Clarkia-gracilis-%28Farewell-To-Spring%29');
