INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia rubicunda', 'Ruby Chalice Clarkia', 'Bees, Butterflies, Caterpillars', 'Pink, Red, Purple', 'Spring, Summer', 'Full Sun', 'Very Low', 'Consider other sun-loving plants of Central California, such as small succulents (<a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>) or Purple Needlegrass (Stipa pulchra) and plant with other vibrant wildflowers such as Purple Chinese Houses (Collinsia heterophylla) to create a colorful garden.', 'Mixed Evergreen Forest, Northern Coastal Scrub', 'Prefers sun or part shade.', 'Generally snail and slug resistant.', 'https://calscape.org/Clarkia-rubicunda-%28Ruby-Chalice-Clarkia%29');
