INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia speciosa', 'Red Spotted Clarkia', 'Bees, Butterflies, Caterpillars', 'Pink, Red, Lavender', 'Spring, Summer', 'Full Sun, Partial Shade', 'Very Low', 'Use with other annuals or herbaceous perennials such as Snapdragon (<a href="/search/?plant=Antirrhinum%20(Genus)">Antirrhinum spp.</a>), Sitka Columbine (Aquilegia formosa), Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Chinese Houses (Collinsia heterophylla), Western Wallflower (Erysimum capitatum), Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a>), Blue Field Gilia (Gilia capitata); with geophytes such as onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>); and with small succulents such as Dudleya spp.', 'Chaparral, Foothill Woodland', 'Prefers sun or part shade. Likes sandy soils.', null, 'https://calscape.org/Clarkia-speciosa-%28Red-Spotted-Clarkia%29');
