INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clarkia unguiculata', 'Elegant Clarkia', 'Bats, Bees, Butterflies, Caterpillars', 'Red, Pink', 'Summer, Fall', 'Full Sun, Partial Shade, Deep Shade', 'Low', '<p>Elegant Clarkia occurs as an understory plant with oaks and pines. Other understory plants that occur with it include various native grasses, Mariposa Lilies (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), Western Houndstongue (Adelinia grandis), Blue-Eyed Grass and Yellow-Eyed Grass (<a href="/search/?plant=Sisyrinchium%20(Genus)">Sisyrinchium spp.</a>), and other annual wildflowers</p>', 'Chaparral, Coastal Scrub, Foothill Woodland, Perennial Grassland--Remnant Non-desert Grassland', null, null, 'https://calscape.org/Clarkia-unguiculata-%28Elegant-Clarkia%29');
