INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Claytonia parviflora', 'Streambank Springbeauty', 'Butterflies, Caterpillars', 'White, Pink', 'Winter, Spring', 'Partial Shade, Full Sun', 'Low', 'Works well as an annual understory plant with oaks, other trees or larger shrubs. Can be mixed with more showy annuals or perennial herbs.', null, 'Requires moist soil. Grows well in sun, shade or part shade. Likes vernally moist soils.', null, 'https://calscape.org/Claytonia-parviflora-%28Streambank-Springbeauty%29');
