INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Claytonia perfoliata', 'Rooreh', 'Bats, Butterflies, Caterpillars', 'White', 'Spring, Winter', 'Partial Shade', 'Low, Moderate, High', '<p>Works well as an annual understory plant with oaks, other trees or larger shrubs. Can be mixed with more showy annuals or perennial herbs.</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Joshua Tree Woodland, Mixed Evergreen Forest, Pinyon-Juniper Woodland, Red Fir Forest, Yellow Pine Forest', '<p>Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-7. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Claytonia perfoliata is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 36 inches of water per year once established. Requires moist soil. Prefers shade. Likes vernally moist soils.</p>', null, 'https://calscape.org/Claytonia-perfoliata-%28Rooreh%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Claytonia perfoliata ssp. intermontana', 'Miner''s Lettuce', 'Butterflies, Caterpillars', null, null, 'Full Sun, Partial Shade', null, null, 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Joshua Tree Woodland, Mixed Evergreen Forest, Pinyon-Juniper Woodland, Red Fir Forest, Yellow Pine Forest', null, null, 'https://calscape.org/Claytonia-perfoliata-ssp.-intermontana-%28Miner%27s-Lettuce%29');
