INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Claytonia sibirica', 'Candy Flower', 'Butterflies, Caterpillars', 'Pink, White', 'Spring', 'Partial Shade', 'Moderate, High', null, 'Douglas-Fir Forest, Mixed Evergreen Forest, Northern Coastal Scrub, Red Fir Forest, Forest, Wetland-Riparian', '<p>Requires fast draining soil. Prefers part shade. Likes streambanks and soils.</p>', null, 'https://calscape.org/Claytonia-sibirica-%28Candy-Flower%2CIndian-Lettuce%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Claytonia umbellata', 'Great Basin Claytonia', null, 'Pink, White, Red', null, null, null, null, null, null, null, 'https://calscape.org/Claytonia-umbellata-%28Great-Basin-Claytonia%29');
