INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clematis lasiantha', 'Chaparral Clematis', 'Bats, Butterflies, Caterpillars', 'Cream, White', 'Summer, Spring', 'Full Sun, Partial Shade, Deep Shade', 'Very Low, Low', '<p>Prefers to have trees or large shrubs to climb up, such as Madrone (Arbutus menziesii), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Silktassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Toyon (Heteromeles arbutifolia), Tanoak (Notholithocarpus densiflorus), Pine (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Elderberry (<a href="/search/?plant=Sambucus%20(Genus)">Sambucus spp.</a>)</p>', 'Chaparral, Yellow Pine Forest', '<p>Requires fast draining soil. Prefers shade. Likes slopes soils. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Clematis-lasiantha-%28Chaparral-Clematis%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Cleomella platycarpa', 'Golden Bee Plant', 'Bees, Butterflies, Caterpillars', null, null, null, null, null, null, null, null, 'https://calscape.org/Cleomella-platycarpa-%28Golden-Bee-Plant%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Cleomella plocasperma', 'Twisted Cleomella', null, 'Yellow', null, null, null, null, 'Alkali Sink, Creosote Bush Scrub, Wetland-Riparian', null, null, 'https://calscape.org/Cleomella-plocasperma-%28Twisted-Cleomella%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clematis ligusticifolia', 'Virgin''s Bower', 'Bats, Butterflies, Caterpillars', 'Cream, White', 'Summer', 'Partial Shade, Deep Shade', 'Low, Moderate', '<p>This plant is often found climbing up through larger shrubs such as Birch (<a href="/search/?plant=Betula%20(Genus)">Betula spp.</a>), Ceanothus species, Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Coffeeberry (Frangulas species), Ninebark (Physocarpus capitatus), Wild Rose (<a href="/search/?plant=Rosa%20(Genus)">Rosa spp.</a>), and Western Blueberry (Vaccinium uliginosum ssp. occidentale)</p>', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Plant in sandy, loamy or clay soils that are at least 16 inches deep, with a pH of 5.6-8.4. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Clematis ligusticifolia is moderately drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Likes stream edges and wet soils. This plant is not drought tolerant. It likes summer water every other week.</p>', null, 'https://calscape.org/Clematis-ligusticifolia-%28Virgin%27s-Bower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clematis pauciflora', 'Small Leaved Clematis', 'Bats, Butterflies, Caterpillars', 'White, Yellow', 'Winter, Spring', 'Full Sun, Partial Shade', 'Low, Very Low', 'Plant this vine near a large, openly branched shrub that it can climb up, such as Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Mountain Mahogany (Cercocarpus betuloides or minutiflorus), Summer Holly (Comarostaphylis diversifolia ssp. diversifolia), Flannelbush (<a href="/search/?plant=Fremontodendron%20(Genus)">Fremontodendron spp.</a>), Silk Tassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Toyon (Heteromeles arbutifolia), Mallow (<a href="/search/?plant=Malacothamnus%20(Genus)">Malacothamnus spp.</a>), Laurel Sumace (Malosma laurina), Hollyleaf Cherry (Prunus ilicifolia), Scrub Oak (Quercus berberidifolia or xacutidens), and Mission Manzanita (Xylococcus bicolor)', 'Chaparral', 'Requires fast draining soil. Prefers sun and part shade. Likes dry soils.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Clematis-pauciflora-%28Small-Leaved-Clematis%29');
