INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clinopodium chandleri', 'San Diego Yerba Buena', 'Butterflies, Caterpillars', 'White', 'Summer, Spring', 'Full Sun, Partial Shade', 'Low', '<p>Use with chaparral plants of its native range including Chamise (Adenostoma fasciculatum), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Heart-leaf Penstemon (Keckiella cordifolia), Southern Honeysuckle (Lonicera subspicata), Laurel Sumac (Malosma laurina), Oak (Quercus agrifolia or engelmannii), Sugar Bush (Rhus ovata), and native ferns such as Woodwardia or Dryopteris</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Valley Grassland', '<p>Requires fast draining soil. Prefers shade. Likes rocky slopes. This plant is not drought tolerant. It likes summer water every week or every other week.</p>', null, 'https://calscape.org/Clinopodium-chandleri-%28San-Diego-Yerba-Buena%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clinopodium douglasii', 'Yerba Buena', 'Bats, Butterflies, Caterpillars', 'White', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Low, Moderate', '<p>Trees: Madrone (Arbutus menziesii), Tanoak (Notholithocarpus densiflorus), Monterey Pine (Pinus radiata), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Coast Redwood (Sequoia sempervirens), Bay Laurel (Umbellularia californica)</p><p><br></p><p>Shrubs and herbs: Woodland Strawberry (Fragaria vesca), Monkeyflower (Erythranthe cardinalis or guttatus), Coyote brush (Baccharis pillularis), Douglas Iris (Iris douglasiana), Bluff Lettuce (Dudleya farinosa) and Pacific Stonecrop (Sedum spathulifolium)</p>', 'Chaparral, Closed-cone Pine Forest, Mixed Evergreen Forest, Northern Coastal Scrub, Redwood Forest', '<p>Requires fast draining soil. Tolerates sand and clay. Grows well in sun, shade or part shade, but prefers shade and moisture. It likes summer water every 1-4 weeks. Easy to keep small and will grow in pots.</p>', null, 'https://calscape.org/Clinopodium-douglasii-%28Yerba-Buena%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clinopodium mimuloides', 'Monkey Flower Savory', 'Hummingbirds, Butterflies, Caterpillars', 'Orange, Red', 'Summer, Fall', 'Full Sun, Partial Shade', 'Moderate', 'Use in the understory of central coast trees such as Madrone (Arbutus menziesii), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), and Douglas Fir (Pseudotsuga menziesii), with other perennial herbs, annuals, or geophytes including Yarrow (Achillea millefolium), wild onion (<a href="/search/?plant=Alium%20(Genus)">Alium spp.</a>), Columbine (Aquilegia formosa), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (<a href="/search/?plant=Collinsia%20(Genus)">Collinsia spp.</a>), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Sticky Cinquefoil (Drymocallis glandulosa), Wild Strawberry (Fragraria vesca), <a href="/search/?plant=Gilia%20(Genus)">Gilia spp.</a>, Alum Root (Heuchera micrantha), <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, Tiger Lily (Lilium pardalinum), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Mint (<a href="/search/?plant=Monardella%20(Genus)">Monardella spp.</a>), <a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>, Common Buttercup (Ranunculus californicus), Sonoma Sage (Salvia sonomensis), and Western Vervain (Verbena lasiostachys)', 'Chaparral, Douglas-Fir Forest', 'Prefers sun or part shade. Likes moist soils. Tolerant of sand, clay, poor drainage, and seasonal flooding.', null, 'https://calscape.org/Clinopodium-mimuloides-%28Monkey-Flower-Savory%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Clintonia andrewsiana', 'Blue Bead Lily', null, 'Red, Pink, Purple, Blue', 'Winter, Spring', 'Deep Shade, Partial Shade', 'Moderate', null, 'Forest', 'Requires fast draining soil. Prefers shade. Likes moist soils.', null, 'https://calscape.org/Clintonia-andrewsiana-%28Blue-Bead-Lily%29');
