INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Deinandra fasciculata', 'Clustered Tarweed', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Extremely Low, Very Low', 'Use with other annuals or perennial herbs such as Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a> or <a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a>), Baby Blue Eyes (Nemophila menziesii), Cream Cups (Platystemon californicus), <a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>, Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), and with geophytes such as Onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), and Blue Dicks (Dichelostemma capitatum). Also useful around various cactus and succulents such as Dudleya spp. and with native grasses.', 'Coastal Sage Scrub, Southern Oak Woodland, Valley Grassland', 'Prefers sun or part shade. Likes grassy areas.', null, 'https://calscape.org/Deinandra-fasciculata-%28Clustered-Tarweed%29-2');
