INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Delphinium andersonii', 'Anderson''s Larkspur', 'Bees, Hummingbirds, Butterflies, Caterpillars', 'Purple, Blue, White', 'Spring', 'Partial Shade', null, null, 'North Coastal Coniferous Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy soils that are at least 14 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. It requires a minimum of 14 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers part shade. Likes talus and dry areas.', null, 'https://calscape.org/Delphinium-andersonii-%28Anderson%27s-Larkspur%29');
