INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Delphinium glaucum', 'Glaucus Larkspur', 'Bees, Hummingbirds, Butterflies, Caterpillars', 'Purple, Blue', 'Spring', 'Deep Shade, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 5.6-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires fertile soil. Delphinium glaucum is not drought tolerant. It requires a minimum of 55 inches of water per year, and a maximum of 125 inches of water per year once established. Requires fast draining soil. Prefers shade. Likes wet thickets and streamsides.', null, 'https://calscape.org/Delphinium-glaucum-%28Glaucus-Larkspur%29');
