INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dicentra formosa', 'Bleeding Heart', 'Butterflies, Caterpillars', 'Red, Purple, Pink, White', 'Summer, Spring', 'Full Sun, Partial Shade, Deep Shade', 'Moderate, High', '<p>Trees - Ponderosa Pine (Pinus ponderosa), Tanoak (Notholithocarpus densiflorus), Madrone (Arbutus menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Coast Redwood (Sequoia sempervirens), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>)</p><p><br></p><p>Other Plants - Maidenhair Fern (<a href="/search/?plant=Adiantum%20(Genus)">Adiantum spp.</a>), Deer Fern (Blechnum spicant), Horsetail (<a href="/search/?plant=Equisetum%20(Genus)">Equisetum spp.</a>), Polypody Fern (<a href="/search/?plant=Polypodium%20(Genus)">Polypodium spp.</a>), Sword Fern (<a href="/search/?plant=Polystichum%20(Genus)">Polystichum spp.</a>), Meadow Rue (Thalicturm species), Yerba Buena (Clinopodium douglasii), Western Columbine (Aquilegia formosa), Monkeyflower (Mimulus cardinalis or guttatus)</p>', 'Northern Oak Woodland, Oak Woodland, Red Fir Forest, Yellow Pine Forest', '<p>Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 5.5-6. It is intolerant of anaerobic soils, intolerant calcareous soils, and requires only moderately fertile soils. Dicentra formosa is not drought tolerant. It requires a minimum of 55 inches of water per year, and a maximum of 155 inches of water per year once established. Requires fast draining soil. Prefers shade.</p>', null, 'https://calscape.org/Dicentra-formosa-%28Bleeding-Heart%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dicentra formosa ''Adrian Bloom''', 'Adrian Bloom Western Bleeding Heart', 'Butterflies, Caterpillars', 'Pink', 'Spring, Summer', 'Full Sun, Partial Shade, Deep Shade', 'High, Moderate', 'Trees - Ponderosa Pine (Pinus ponderosa), Tanoak (Notholithocarpus densiflorus), Madrone (Arbutus menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Coast Redwood (Sequoia sempervirens), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>)<br><br>Other Plants - Maidenhair Fern (<a href="/search/?plant=Adiantum%20(Genus)">Adiantum spp.</a>), Deer Fern (Blechnum spicant), Horsetail (<a href="/search/?plant=Equisetum%20(Genus)">Equisetum spp.</a>), Polypody Fern (<a href="/search/?plant=Polypodium%20(Genus)">Polypodium spp.</a>), Sword Fern (<a href="/search/?plant=Polystichum%20(Genus)">Polystichum spp.</a>), Meadow Rue (Thalicturm species), Yerba Buena (Clinopodium douglasii), Western Columbine (Aquilegia formosa), Monkeyflower (Mimulus cardinalis or guttatus)', null, null, null, 'https://calscape.org/Dicentra-formosa-%27Adrian-Bloom%27-%28Adrian-Bloom-Western-Bleeding-Heart%29');
