INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichelostemma capitatum ''Santa Cruz Island Giant''', 'Santa Cruz Island Giant Blue Dicks', 'Butterflies', 'Lavender', 'Spring', 'Full Sun', 'Very Low', 'Native grasses, <a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>, Coast Sagebush, Chamise (Adenostoma fasciculatum var. fasciculatum), Sugar Bush (Rhus ovata), <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, various cactus species', null, null, null, 'https://calscape.org/Dichelostemma-capitatum-%27Santa-Cruz-Island-Giant%27-%28Santa-Cruz-Island-Giant-Blue-Dicks%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichelostemma congestum', 'Ookow', 'Butterflies', 'Blue, Lavender, Purple', 'Spring', 'Full Sun, Partial Shade', 'Very Low', null, 'Foothill Woodland, Mixed Evergreen Forest', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Dichelostemma-congestum-%28Ookow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichelostemma ida-maia', 'Firecracker Brodiaea', 'Butterflies', 'Cream, Red', 'Spring, Summer', 'Full Sun, Partial Shade, Deep Shade', 'Very Low', 'Use in understory of north coast trees such as Coast Redwood (Sequoia sempervirens), Madrone (Arbutus menziesii), or Tanoak (Notholithocarpus densiflorus). Works well with other geophytes such as Mariposa Lilies (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), Oregon Lily (Lilium columbaianum), and <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>', 'Mixed Evergreen Forest, Redwood Forest', 'Requires fast draining soil. Prefers shade or part shade.', null, 'https://calscape.org/Dichelostemma-ida-maia-%28Firecracker-Brodiaea%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichelostemma multiflorum', 'Wild Hyacinth', 'Butterflies', 'Blue, Lavender', 'Spring', 'Full Sun, Partial Shade', 'Very Low', 'Like other members of the genus, it is most effective when massed. Individual corms will not bloom every year. Use with annuals, herbaceous perennials, or geophytes such as onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a> or <a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a>), Baby Blue Eyes (Nemophila menziesii), and Lily (<a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>)', 'Foothill Woodland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade. Likes grassy areas.', null, 'https://calscape.org/Dichelostemma-multiflorum-%28Wild-Hyacinth%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichelostemma volubile', 'Twining Snakelily', 'Butterflies', 'Pink, White, Purple, Red', 'Spring, Summer', 'Full Sun, Partial Shade', 'Very Low', null, 'Woodland', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Dichelostemma-volubile-%28Twining-Snakelily%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichondra donelliana', 'Dichondra', null, null, null, 'Full Sun', 'Low, Moderate', null, 'Coastal Prairie, Northern Coastal Scrub', 'Requires moist soil. Prefers sun. Likes slopes.', null, 'https://calscape.org/Dichondra-donelliana-%28Dichondra%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dichondra occidentalis', 'Western Ponysfoot', null, 'Cream', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Moderate, Very Low', null, 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Northern Coastal Scrub, Valley Grassland', 'Requires fast draining soil. Prefers sun, part shade. Likes slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as every other week.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Dichondra-occidentalis-%28Western-Ponysfoot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dicoria canescens', 'Desert Twinbugs', null, 'White', null, null, null, null, 'Alkali Sink, Creosote Bush Scrub, Joshua Tree Woodland', null, null, 'https://calscape.org/Dicoria-canescens-%28Desert-Twinbugs%29');
