INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dipterostemon capitatus', 'Blue Dicks', 'Butterflies', 'Blue, Lavender', 'Spring, Winter', 'Full Sun, Partial Shade', 'Low', '<p>Native grasses, <a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>, Coast Sagebush, Chamise (Adenostoma fasciculatum var. fasciculatum), Sugar Bush (Rhus ovata), <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, various cactus species</p>', 'Chaparral, Coastal Scrub, Creosote Bush Scrub, Lowland Chaparral, Maritime Desert Scrub, Meadows, Perennial Grassland--Desert Grassland, Perennial Grassland--Remnant Non-desert Grassland, Southern Coastal Scrub', '<p>Requires moist soil. Prefers sun or part shade.This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Dipterostemon-capitatus-%28Blue-Dicks%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dipterostemon capitatus ssp. capitatus', 'Blue Dicks', 'Butterflies', 'Blue, Lavender', null, 'Full Sun, Partial Shade', 'Very Low', null, 'Wetland-Riparian', '<p>Requires moist soil. Prefers sun or part shade.</p>', null, 'https://calscape.org/Dipterostemon-capitatus-ssp.-capitatus-%28Blue-Dicks%29');
