INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya edulis', 'Fingertips', 'Birds, Butterflies, Caterpillars, Hummingbirds', 'Pink, Cream, White', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low, Low', '<p>California Fuchsia (Epilobium canum ssp. latifolium), California Box Thorn (Lycium californicum), Sea Dahlia (Leptosyne maritima), Seacliff Buckwheat, various cactus species</p>', 'Chaparral, Coastal Scrub, Lowland Chaparral, Maritime Desert Scrub, Southern Coastal Scrub', '<p>Requires fast draining soil and prefers sun. Likes rocky slopes that get some natural ground water, and typically are not south facing. This plant looks best if given summer water every 4 weeks after even after it''s established. Without additional water, this plant typically goes summer deciduous, dries up and virtually disappears in the summer, but then come back strong and green once the winter rains start.</p>', null, 'https://calscape.org/Dudleya-edulis-%28Fingertips%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya farinosa', 'Bluff Lettuce', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Red, Yellow, Pink, Green', 'Summer', 'Deep Shade, Partial Shade', 'Low, Very Low', 'Yellow Stonecrop (Sedum spathulifolium), Coast Dudleya (Dudleya caespitosa), Red Maids (Calandrinia menziesii), dwarf or low growing Chamise (Adenostoma fasciculatum), Giant Coreopsis (Leptosyne gigantea), low growing Coyote Bush (Baccharis pilularis), Coast Eriogonum (Eriogonum latifolium), Seaside Fleabane (Erigeron glaucus), Coastal Sagewort (Artemisia pycnocephala)', 'Coastal Sage Scrub, Northern Coastal Scrub', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Dudleya-farinosa-%28Bluff-Lettuce%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya gnoma', 'Munchkin Liveforever', 'Birds, Butterflies, Caterpillars, Hummingbirds', 'Yellow', null, null, 'Very Low, Low', null, null, null, null, 'https://calscape.org/Dudleya-gnoma-%28Munchkin-Liveforever%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya greenei', 'Greene''s Liveforever', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Cream, Yellow', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Low, Very Low', null, 'Chaparral, Coastal Sage Scrub, Foothill Woodland', 'Requires fast draining soil. Prefers shade. Likes rock walls.', null, 'https://calscape.org/Dudleya-greenei-%28Greene%27s-Liveforever%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya traskiae', 'Santa Barbara Island Live Forever', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Yellow, Red', 'Winter, Spring, Summer', 'Partial Shade, Full Sun', 'Low, Very Low', 'Consider using other plants common to the natural habitat of this Dudleya, such as cholla (Cylindropuntia prolifera), prickly pear (Opuntia littoralis), boxthorn (Lycium californicum), and Santa Barbara Island buckwheat (Eriogonum giganteum ssp. compactum).', null, 'Prefers sun. Likes steep slopes.', null, 'https://calscape.org/Dudleya-traskiae-%28Santa-Barbara-Island-Live-Forever%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya lanceolata', 'Lanceleaf Liveforever', 'Birds, Butterflies, Hummingbirds, Caterpillars', 'Orange, Pink, Red, Yellow', 'Spring, Summer', 'Full Sun', 'Low, Very Low', 'Toyon (Heteromeles arbutifolia), Scrub Oaks, Chaparral Mallow (Malacothamnus fasciculatus), California Encelia, California Sagebrush (Artemisia californica), Woolly Bluecurls (Trichostema lanatum), Chamise (Adenostoma fasciculatum var. fasciculatum), <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, various cactus species', 'Chaparral, Coastal Scrub', 'Requires fast draining soil. Prefers sun. Likes rocky slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Dudleya-lanceolata-%28Lanceleaf-Liveforever%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya multicaulis', 'Many-stemmed Dudleya', 'Butterflies, Hummingbirds, Caterpillars', 'Yellow', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Dudleya-multicaulis-%28Many-stemmed-Dudleya%29');
