INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya pulverulenta', 'Chalk Dudleya', 'Birds, Butterflies, Caterpillars, Hummingbirds', 'Red, Orange, Pink', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low, Low', '<p>Chamise (Adenostoma fasciculatum var. fasciculatum), California Encelia, California Buckwheat (Eriogonum fasciculatum var. fasciculatum), Pink Honeysuckle (Lonicera hispidula), Wild Hyacinth (Dichelostemma multiflorum), Oaks, native grasses, <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, various cactus species</p>', 'Chaparral, Coastal Scrub, Lowland Chaparral, Maritime Desert Scrub, Oak Woodland, Southern Coastal Scrub, Southern Oak Woodland', '<p>Prefers sun to part shade. Likes angled rock shelves and rocky soils with very good drainage. After established, it should survive the dry months with no supplementary water. It''s very sensitive to pathogens that grow in warm moist soils, and will usually die if watered more than once during the season. If you do water during the summer, make sure it''s a light watering during the very early morning, and during a stretch of cooler days. Try to simulate a summer storm.</p>', null, 'https://calscape.org/Dudleya-pulverulenta-%28Chalk-Dudleya%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya saxosa', 'Panamint Dudleya', 'Birds, Butterflies, Caterpillars, Hummingbirds', 'Red, Yellow, Green, Pink', null, null, 'Very Low, Low', null, 'Chaparral, Creosote Bush Scrub, Pinyon-Juniper Woodland', null, null, 'https://calscape.org/Dudleya-saxosa-%28Cooper%27s-Dyssodia%29');
