INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya variegata', 'Variegated Dudleya', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Yellow', null, 'Full Sun', 'Low, Very Low', null, 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Freshwater Marsh, Valley Grassland', 'Requires fast draining soil. Prefers sun. Likes dry slopes and flats.', null, 'https://calscape.org/Dudleya-variegata-%28Variegated-Dudleya%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya verityi', 'Verity''s Dudleya', 'Hummingbirds, Butterflies, Caterpillars', 'Yellow, Pink, Green', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Dudleya-verityi-%28Verity%27s-Dudleya%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya virens', 'Bright Green Dudleya', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'White, Yellow, Green', 'Spring', 'Full Sun', 'Low, Very Low', 'Use with other coastal plants of Southern California such as Juncus acutus or Salvia apiana', 'Chaparral, Coastal Sage Scrub', 'Requires fast draining soil. Prefers full sun or light shade. Likes slopes. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', 'Avoid overwatering to reduce liklihood of pests. Watch for mealybugs, snails, slugs, aphids. Wash off aphids on emerging flower stalks with a strong stream of water.', 'https://calscape.org/Dudleya-virens-%28Bright-Green-Dudleya%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Dudleya virens ssp. hassei', 'Bright Green Dudleya', 'Birds, Hummingbirds, Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun', 'Low, Very Low', 'Santa Catalina Island Manzanita (Arctostaphylos catalinae), Catalina Cherry (Prunus ilicifolia ssp lyonii), Island Snapdragon (Gambelia speciosa), White Sage (Salvia apiana), St. Catherine''s Lace (Eriogonum giganteum), Island Ceanothus (Ceanothus arboreus), Giant Coreopsis (Leptosyne gigantea), Golden Yarrow (Eriophyllum confertiflorum), Catalina Currant (Ribes viburnifolium), Hollyleaf Redberry (Rhamnus ilicifolia), dwarf or low growing Chamise (Adenostoma fasciculatum)', null, 'Prefers shade. Likes rock walls.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Dudleya-virens-ssp.-hassei-%28Bright-Green-Dudleya%29');
