INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eclipta prostrata', 'False Daisy', null, 'White', 'Summer', 'Full Sun', null, null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 14 inches deep, with a pH of 5.2-7.9. It is tolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Eclipta prostrata is only slightly drought tolerant. It requires a minimum of 35 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Eclipta-prostrata-%28False-Daisy%29');
