INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Elodea canadensis', 'Elodea', null, 'White', 'Summer', 'Full Sun', null, null, 'Wetland-Riparian', 'Plant in clay soils that are at least 0 inches deep, with a pH of 4.8-7.8. It is tolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Elodea canadensis is not drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun.', null, 'https://calscape.org/Elodea-canadensis-%28Elodea%29');
