INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium canum', 'California Fuchsia', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red', 'Summer, Fall', 'Full Sun, Partial Shade', 'Very Low, Low', 'Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Giant Wild Rye (Elymus condensatus), Sand Aster (Corethrogyne filaginifolia), Sagebrush (Artemisia californica), Monkeyflower (<a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>), Encelia californica, Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Heartleaf Keckiella (Keckiella cordifolia), Penstemon species, Salvia species, Blue-eyed Grass (Sisyrinchium bellum)', 'Chaparral, Coastal Sage Scrub, Lodgepole Forest, Oak Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Prefers sun. Likes dry slopes. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Epilobium-canum-%28California-Fuchsia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium canum ''Everett''s Choice''', 'Everett''s Choice California Fuchsia', 'Bats, Birds, Butterflies, Caterpillars, Hummingbirds', 'Red', 'Summer, Fall, Winter', 'Full Sun, Partial Shade', 'Very Low, Low', null, null, null, null, 'https://calscape.org/Epilobium-canum-%27Everett%27s-Choice%27-%28Everett%27s-Choice-California-Fuchsia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium canum ''Hollywood Flame''', 'Hollywood Flame Hummingbird Fuchsia', 'Bats, Birds, Butterflies, Caterpillars, Hummingbirds', 'Red', 'Summer, Fall', 'Full Sun, Partial Shade', 'Extremely Low, Very Low, Low', null, null, '<p>''Hollywood Flame'' California fuchsia does well being cut back in winter or early spring close to the ground. The plant will grow back even more full than before.</p>', null, 'https://calscape.org/epilobium-canum-hollywood-flame-hollywood-flame-hummingbird-fuchsia');
