INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium septentrionale', 'Humboldt County Fuchsia', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, White, Orange', 'Summer, Fall', 'Partial Shade', 'Low', 'Use with other Cascade plants such as Red Alder (Alnus rubra), Manzanita (Arctostaphylos columbiana or stanfordiana), Coast Barberry (Berberis pinnata), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Hawthorn (Crataegus douglasii or gaylussacia), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Salal (Gaultheria shallon), Crevice Alumroot (Heuchera micrantha), Mock Orange (Philadelphus lewisii), Rosebay (Rhododendron macrophyllum), and Stonecrop (Sedum laxum or spathulifolium)', 'Douglas-Fir Forest, Mixed Evergreen Forest, North Coastal Coniferous Forest, Forest', 'Requires fast draining soil. Prefers part shade. Likes Dry rocky or sandy soils.', null, 'https://calscape.org/Epilobium-septentrionale-%28Humboldt-County-Fuchsia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium septentrionale ''Mattole River''', 'Mattole River Humboldt County Fuchsia', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, Orange', 'Summer', 'Partial Shade', 'Low', '<p>Use with other Cascade plants such as Red Alder (Alnus rubra), Manzanita (Arctostaphylos columbiana or stanfordiana), Coast Barberry (Berberis pinnata), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Hawthorn (Crataegus douglasii or gaylussacia), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Salal (Gaultheria shallon), Crevice Alumroot (Heuchera micrantha), Mock Orange (Philadelphus lewisii), Rosebay (Rhododendron macrophyllum), and Stonecrop (Sedum laxum or spathulifolium)</p>', null, null, null, 'https://calscape.org/Epilobium-septentrionale-%27Mattole-River%27-%28Mattole-River-Humboldt-County-Fuchsia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium septentrionale ''Select Mattole''', 'Select Mattole Humboldt County Fuschsia', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, Orange', 'Summer', 'Partial Shade', 'Low', '<p>Use with other Cascade plants such as Red Alder (Alnus rubra), Manzanita (Arctostaphylos columbiana or stanfordiana), Coast Barberry (Berberis pinnata), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Hawthorn (Crataegus douglasii or gaylussacia), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Salal (Gaultheria shallon), Crevice Alumroot (Heuchera micrantha), Mock Orange (Philadelphus lewisii), Rosebay (Rhododendron macrophyllum), and Stonecrop (Sedum laxum or spathulifolium)</p>', null, null, null, 'https://calscape.org/Epilobium-septentrionale-%27Select-Mattole%27-%28Select-Mattole-Humboldt-County-Fuschsia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Epilobium septentrionale ''Wayne''s Silver''', 'Wayne''s Silver Fuchsia', 'Bats, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, Orange', 'Summer', 'Partial Shade', 'Low', '<p>Use with other Cascade plants such as Red Alder (Alnus rubra), Manzanita (Arctostaphylos columbiana or stanfordiana), Coast Barberry (Berberis pinnata), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Hawthorn (Crataegus douglasii or gaylussacia), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Salal (Gaultheria shallon), Crevice Alumroot (Heuchera micrantha), Mock Orange (Philadelphus lewisii), Rosebay (Rhododendron macrophyllum), and Stonecrop (Sedum laxum or spathulifolium)</p>', null, null, null, 'https://calscape.org/Epilobium-septentrionale-%27Wayne%27s-Silver%27-%28Wayne%27s-Silver-Fuchsia%29');
