INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erigeron compositus', 'Cut Leaved Daisy', 'Bees, Butterflies, Caterpillars', 'White, Yellow', 'Spring', 'Partial Shade', null, null, 'Alpine Fell-Fields, Lodgepole Forest, Subalpine Forest', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 6.1-8.1. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Erigeron compositus is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil. It does not tolerate full shade well. Prefers part shade. Likes rocky slopes.', null, 'https://calscape.org/Erigeron-compositus-%28Cut-Leaved-Daisy%29');
