INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erigeron divergens', 'Spreading Fleabane', 'Bees, Butterflies, Caterpillars', 'Yellow, White, Lavender', 'Spring, Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Foothill Woodland, Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade. Likes sandy soils.', null, 'https://calscape.org/Erigeron-divergens-%28Spreading-Fleabane%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erigeron eatonii', 'Eaton''s Daisy', 'Bees, Butterflies, Caterpillars', 'White, Yellow', 'Spring', 'Full Sun', null, null, null, 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 6.5-8.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Erigeron eatonii is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 14 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes rocky flats .', null, 'https://calscape.org/Erigeron-eatonii-%28Eaton%27s-Daisy%29');
