INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erigeron filifolius', 'Thread Leaved Daisy', 'Bees, Butterflies, Caterpillars', 'Purple, Yellow', 'Summer', 'Partial Shade', null, null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Erigeron filifolius is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 60 inches of water per year once established. It does not tolerate full shade well. Prefers part shade.', null, 'https://calscape.org/Erigeron-filifolius-%28Thread-Leaved-Daisy%29');
