INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum elatum', 'Tall Buckwheat', 'Bees, Butterflies, Caterpillars', 'White, Cream, Pink', 'Spring', 'Partial Shade', 'Low, Very Low', null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Eriogonum elatum is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate full shade well. Prefers part shade. Likes sandy or gravel soils.', null, 'https://calscape.org/Eriogonum-elatum-%28Tall-Buckwheat%29');
