INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum grande', 'Redflower Buckwheat', 'Bees, Birds, Butterflies, Caterpillars', 'Cream, Pink, Red, White', 'Summer, Fall', 'Full Sun', 'Low, Very Low', 'Island companions include Island Ironwood (Lyonothamnus fasciculatus ssp. asplenifolius), Catalina Cherry (Prunus ilicifolia ssp. lyonii), St. Catherine''s Lace (Eriogonum giganteum), Island Buckwheat (Eriogonum arborescens), Island Morning Glory (Calystegia macrostegia), Island Ceanothus (Ceanothus arboreus), Channel Islands Tree Poppy (Dendromecon hardordii), Island Alum Root (Heuchera maxima), Island Mallow (Lavatera assurgentiflora), Island Pitcher Sage (Lepechinia fragrans), Island Oak (Quercus tomentella), Catalina Island Gooseberry (Ribes virburnifolium), and Santa Rosa Island Sage (Salvia brandegeei)', 'Chaparral, Coastal Sage Scrub', 'Prefers sun. Likes dry rock walls.', null, 'https://calscape.org/Eriogonum-grande-%28Redflower-Buckwheat%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum grande var. grande', 'Island Buckwheat', 'Bees, Butterflies, Caterpillars', 'Cream, Pink, White', null, 'Full Sun', 'Low, Very Low', null, 'Coastal Sage Scrub', 'Prefers sun. Likes dry rock walls.', null, 'https://calscape.org/Eriogonum-grande-var.-grande-%28Island-Buckwheat%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum inerme', 'Unarmed Buckwheat', 'Butterflies, Caterpillars', 'Cream, Pink, White', null, null, 'Low, Very Low', null, 'Chaparral, Foothill Woodland, Yellow Pine Forest', null, null, 'https://calscape.org/Eriogonum-inerme-%28Unarmed-Buckwheat%29');
