INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum grande var. rubescens', 'Red-flowered Buckwheat', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Cream, Pink, White, Red', 'Spring, Summer, Fall', 'Full Sun', 'Low, Very Low', 'Island companions include Island Ironwood (Lyonothamnus fasciculatus ssp. asplenifolius), Catalina Cherry (Prunus ilicifolia ssp. lyonii), St. Catherine''s Lace (Eriogonum giganteum), Island Buckwheat (Eriogonum arborescens), Island Morning Glory (Calystegia macrostegia), Island Ceanothus (Ceanothus arboreus), Channel Islands Tree Poppy (Dendromecon hardordii), Island Alum Root (Heuchera maxima), Island Mallow (Lavatera assurgentiflora), Island Pitcher Sage (Lepechinia fragrans), Island Oak (Quercus tomentella), Catalina Island Gooseberry (Ribes virburnifolium), and Santa Rosa Island Sage (Salvia brandegeei)', 'Chaparral, Coastal Beach & Dune, Coastal Scrub', 'Prefers sun. Likes dry rock walls. Tolerates seaside conditions, alkaline soil, and clay. It likes summer water every 2-4 weeks.', null, 'https://calscape.org/Eriogonum-grande-var.-rubescens-%28Red-flowered-Buckwheat%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum grande var. timorum', 'San Nicolas Island Buckwheat', 'Bees, Butterflies, Caterpillars', 'Cream, Pink, White', null, 'Full Sun', 'Low, Very Low', null, null, 'Prefers sun. Likes dry rock walls.', null, 'https://calscape.org/Eriogonum-grande-var.-timorum-%28San-Nicolas-Island-Buckwheat%29');
