INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum kennedyi', 'Kennedy''s Buckwheat', 'Bees, Butterflies, Caterpillars', 'Cream, Pink, White, Brown', 'Summer, Fall', 'Full Sun', 'Low, Very Low', null, 'Alpine Fell-Fields, Pinyon-Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Prefers sun. Likes dry gravel.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Eriogonum-kennedyi-%28Kennedy%27s-Buckwheat%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum kennedyi var. alpigenum', 'Southern Alpine Buckwheat', 'Bees, Butterflies, Caterpillars', 'Cream, Pink, White', null, 'Partial Shade', 'Low, Very Low', null, 'Alpine Fell-Fields, Subalpine Forest', 'Prefers part shade.', null, 'https://calscape.org/Eriogonum-kennedyi-var.-alpigenum-%28Southern-Alpine-Buckwheat%29');
