INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum sphaerocephalum', 'Round Headed Buckwheat', 'Bees, Butterflies, Caterpillars', 'Yellow, Cream, Pink, White', 'Spring', 'Partial Shade', 'Low, Very Low', null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6-8.6. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Eriogonum sphaerocephalum is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate full shade well. Prefers part shade.', null, 'https://calscape.org/Eriogonum-sphaerocephalum-%28Round-Headed-Buckwheat%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum sphaerocephalum var. halimioides', 'Halimium Wild Buckwheat', 'Bees, Butterflies, Caterpillars', 'Cream, Pink, White, Yellow', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Eriogonum-sphaerocephalum-var.-halimioides-%28Halimium-Wild-Buckwheat%29');
