INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriogonum wrightii', 'Bastardsage', 'Bees, Birds, Butterflies, Caterpillars', 'White, Cream, Pink', 'Summer', 'Full Sun', 'Low, Very Low', null, 'Chaparral, Creosote Bush Scrub, Foothill Woodland, Joshua Tree Woodland, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, intolerant calcareous soils, and tolerant of infertile soils. Eriogonum wrightii is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 14 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes dry gravel or rocks.', null, 'https://calscape.org/Eriogonum-wrightii-%28Bastardsage%29');
