INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum confertiflorum', 'Golden Yarrow', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Spring, Winter', 'Full Sun', 'Very Low, Low', '<p>Purple Sage (Salvia leucophylla), Sticky Monkeyflower (Diplacus aurantiacus), California Sagebrush (Artemisia californica), Deerweed (Acmispon glaber), Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Lodgepole Pine (Pinus contorta), Ponderosa Pine (Pinus ponderosa), Red Fir (Abies magnifica), Ceanothus species, Yucca species, native grasses, and Dudleya species</p>', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', '<p>Prefers full sun and good drainage. It is stressdeciduous. Tolerates alkaline soil and clay. It likes summer water every other week.</p>', null, 'https://calscape.org/Eriophyllum-confertiflorum-%28Golden-Yarrow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum confertiflorum ''Lucia''s Gold''', 'Lucia''s Gold Golden Yarrow', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Full Sun', 'Low, Very Low', 'Purple Sage (Salvia leucophylla), Sticky Monkeyflower (Diplacus aurantiacus), California Sagebrush (Artemisia californica), Deerweed (Acmispon glaber), Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Sage (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Lodgepole Pine (Pinus contorta), Ponderosa Pine (Pinus ponderosa), Red Fir (Abies magnifica), Ceanothus species, Yucca species, native grasses, and Dudleya species', null, null, null, 'https://calscape.org/Eriophyllum-confertiflorum-%27Lucia%27s-Gold%27-%28Lucia%27s-Gold-Golden-Yarrow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum confertiflorum var. confertiflorum', 'Yellow Yarrow', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Full Sun', 'Low, Very Low', null, null, 'Requires fast draining soil. Prefers sun.', null, 'https://calscape.org/Eriophyllum-confertiflorum-var.-confertiflorum-%28Yellow-Yarrow%29');
