INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum lanatum', 'Common Woolly Sunflower', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Partial Shade, Full Sun', 'Very Low', 'Use with shrubs such as Toyon (Heteromeles arbutifolia), Bay Laurel (Umbellularia californica), Interior Live Oak (Quercus wislizenii) and Madrone (Arbutus menziesii). Companion perennials include <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>) and Blue-eyed Grass (Sisyrinchium bellum).', 'Chaparral, Coastal Prairie, Douglas-Fir Forest, Foothill Woodland, Lodgepole Forest, Mixed Evergreen Forest, Northern Juniper Woodland, Northern Oak Woodland, Red Fir Forest, Forest, Sagebrush Scrub, Subalpine Forest, Valley Grassland, Yellow Pine Forest', 'Prefers sun.', null, 'https://calscape.org/Eriophyllum-lanatum-%28Common-Woolly-Sunflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum lanatum ''Siskiyou''', 'Siskiyou Oregon Sunshine', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Partial Shade, Full Sun', 'Very Low', 'Use with shrubs such as Toyon (Heteromeles arbutifolia), Bay Laurel (Umbellularia californica), Interior Live Oak (Quercus wislizenii) and Madrone (Arbutus menziesii). Companion perennials include <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>) and Blue-eyed Grass (Sisyrinchium bellum).', null, null, null, 'https://calscape.org/Eriophyllum-lanatum-%27Siskiyou%27-%28Siskiyou-Oregon-Sunshine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eriophyllum lanatum ''Walker''s Beauty''', 'Walker''s Beauty', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Partial Shade, Full Sun', 'Very Low', 'Use with shrubs such as Toyon (Heteromeles arbutifolia), Bay Laurel (Umbellularia californica), Interior Live Oak (Quercus wislizenii) and Madrone (Arbutus menziesii). Companion perennials include <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>) and Blue-eyed Grass (Sisyrinchium bellum).', null, null, null, 'https://calscape.org/Eriophyllum-lanatum-%27Walker%27s-Beauty%27-%28Walker%27s-Beauty%29');
