INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erythranthe cardinalis', 'Scarlet Monkeyflower', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, Orange', 'Spring, Summer, Fall', 'Partial Shade, Full Sun', 'Moderate, High', 'Other plants that would do well in a moist, partly shaded location include Seep Monkeyflower (Erythranthe guttata), Hedge Nettle (Stachy bullata), Blue Flax (Linum lewisii), Western Columbine (Aquilegia formosa), Douglas Iris (Iris douglasiana), and Stream Orchid (Epipactis gigantea).', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy soils that are at least 6 inches deep, with a pH of 6-7.2. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. It requires a minimum of 24 inches of water per year, and a maximum of 45 inches of water per year once established. Requires moist soil. It is very tolerant of shade, but prefers sun. This plant needs regular summer water and is tolerant of seasonal flooding and soil with no drainage.  If prefers to be watered 1-2 times per week.', null, 'https://calscape.org/Erythranthe-cardinalis-%28Scarlet-Monkeyflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erythranthe cardinalis ''Santa Cruz Island Gold''', 'Santa Cruz Island Scarlet Monkeyflower', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Yellow, Orange', 'Spring, Summer', 'Partial Shade, Full Sun', 'Moderate, High', null, null, null, null, 'https://calscape.org/Erythranthe-cardinalis-%27Santa-Cruz-Island-Gold%27-%28Santa-Cruz-Island-Scarlet-Monkeyflower%29');
