INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erythranthe lewisii', 'Lewis'' Monkeyflower', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Pink, Purple, Red', 'Summer', 'Full Sun', 'High', '<p>Trees: White Fir (Abies concolor), Rocky Mountain Maple, (Acer glabrum), Western Juniper (Juniperus occidentalis), Pine (Pinus contorta or monticola), Cottonwood (<a href="/search/?plant=Populus%20(Genus)">Populus spp.</a>), Canyon Oak (Quercus chrysolepis)</p><p><br></p><p><br></p><p>Shrubs: Pine Mat Manzanita (Arctostaphylos nevadensis), Dogwood (Cornus nuttallii or sericea), Honeysuckle (<a href="/search/?plant=Lonicera%20(Genus)">Lonicera spp.</a>), Currant/Gooseberry (Ribes spl.), and Huckleberry (<a href="/search/?plant=Vaccinium%20(Genus)">Vaccinium spp.</a>)</p><p><br></p><p><br></p><p>Herbs: Sitka Columbine (Aquilegia formosa), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Sulphur Buckwheat (Eriogonum umbellatum), Gentian (<a href="/search/?plant=Gentianella%20(Genus)">Gentianella spp.</a> or <a href="/search/?plant=Gentianopsis%20(Genus)">Gentianopsis spp.</a>), Pink Alumroot (Heuchera rubescens), Alpine Lily (Lilium parvum), other <a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>, Idaho Blue Eyed Grass (Sisyrinchium idahoense), and <a href="/search/?plant=Viola%20(Genus)">Viola spp.</a></p>', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', '<p>Requires fast draining soil. Prefers sun. Likes streambanks and seeps.</p>', null, 'https://calscape.org/Erythranthe-lewisii-%28Lewis%27-Monkeyflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erythranthe lewisii x cardinalis', 'Cardinalis Monkey Flower', 'Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Pink', 'Summer, Spring, Fall', 'Full Sun, Partial Shade', 'Moderate', null, null, '<p>Cut back to 3 inches after bloom.</p>', null, 'https://calscape.org/Erythranthe-lewisii-x-cardinalis-%28Cardinalis-Monkey-Flower%29');
