INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Erythranthe primuloides', 'Primrose Monkeyflower', 'Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Yellow', 'Spring, Winter', 'Full Sun', 'High', null, 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 8 inches deep, with a pH of 6-7.2. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Mimulus primuloides is only slightly drought tolerant. It requires a minimum of 24 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun. Likes wet meadows, seeps and streamsides.', null, 'https://calscape.org/Erythranthe-primuloides-%28Primrose-Monkeyflower%29');
