INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eschscholzia caespitosa', 'Tufted Poppy', 'Bees, Birds, Butterflies, Caterpillars', 'Yellow, Orange', 'Spring, Summer', 'Full Sun', 'Very Low', 'Lupinus species, Phacelia species, Clarkia species, Abronia species, Calfornia Buckwheat, White Sage (Salvia apiana), Chinese Houses, California Fuschia', 'Chaparral, Foothill Woodland, Valley Grassland', 'Requires fast draining soil. Prefers sun.', null, 'https://calscape.org/Eschscholzia-caespitosa-%28Tufted-Poppy%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eschscholzia californica', 'California Poppy', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Orange, Yellow', 'Summer, Spring, Fall, Winter', 'Full Sun', 'Very Low', '<p>Great companion plants include these families <a href="/search/?plant=Lupinus%20(Genus)" rel="noopener noreferrer" target="_blank">Lupinus spp.</a>, <a href="/search/?plant=Phacelia%20(Genus)" rel="noopener noreferrer" target="_blank">Phacelia spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)" rel="noopener noreferrer" target="_blank">Clarkia spp.</a>, <a href="/search/?plant=Collinsia%20(Genus)" rel="noopener noreferrer" target="_blank">Collinsia spp.</a>, <a href="/search/?plant=Abronia%20(Genus)" rel="noopener noreferrer" target="_blank">Abronia spp.</a>, <a href="/search/?plant=Eriogonum%20(Genus)" rel="noopener noreferrer" target="_blank">Buckwheat spp.</a>. &nbsp;Frequent companions also include: California Fuchsia (Epilobium canum), White Sage (Salvia apiana), California Buckwheat (Eriogonum fasciculatum).</p>', 'Northern Coastal Scrub, Yellow Pine Forest, Red Fir Forest, Lodgepole Forest, Foothill Woodland, Chaparral, Coastal Prairie, Valley Grassland', '<p>Plant in sandy, loamy, or clay soils that are at least 10 inches deep, with a pH of 5.8-7.5. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Does well along the coast in seaside conditions. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. It is moderately tolerant of shade, but prefers sun.</p>', 'Rabbits and other small herbivores eat this plant, but it grows back so quickly that they are not much of a problem.', 'https://calscape.org/Eschscholzia-californica-%28California-Poppy%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Eschscholzia californica ''Alba''', 'Alba California Poppy', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Cream, White', 'Spring, Summer, Fall', 'Full Sun', 'Very Low', null, null, null, null, 'https://calscape.org/Eschscholzia-californica-%27Alba%27-%28Alba-California-Poppy%29');
