INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis ''Chaval''', 'Chaval Beach Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Spring, Summer, Fall', 'Partial Shade, Full Sun', 'Moderate', 'Use with other low growing coastal plants such as Sand Verbena (Abronia latifolia or umbellata), Beach bur (Ambrosia chamissonis), Beach Morning Glory (Calystegia soldanella), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), and Coast Gumweed (Grindelia strict)', null, null, null, 'https://calscape.org/Fragaria-chiloensis-%27Chaval%27-%28Chaval-Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Galium bifolium', 'Low Mountain Bedstraw', 'Butterflies, Caterpillars', 'White', null, null, null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', null, null, 'https://calscape.org/Galium-bifolium-%28Low-Mountain-Bedstraw%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Euthamia occidentalis', 'Western Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun, Partial Shade', 'Low, Very Low', 'Rushes (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), Willows (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), Mule Fat (Baccharis salicifolia)', 'Coastal Prairie, Coastal Salt Marsh, Freshwater Marsh, Sagebrush Scrub, Valley Grassland, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 4.5-7. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Euthamia occidentalis is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 32 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Euthamia-occidentalis-%28Western-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Extriplex californica', 'California Saltbush', 'Birds, Butterflies, Caterpillars', 'Green, Cream, Yellow', 'Spring', 'Full Sun', 'Low', null, 'Coastal Sage Scrub, Coastal Salt Marsh, Coastal Strand, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes sandy saline soils.', null, 'https://calscape.org/Extriplex-californica-%28California-Saltbush%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Extriplex joaquinana', 'San Joaquin Spearscale', null, null, null, null, null, null, null, null, null, 'https://calscape.org/Extriplex-joaquinana-%28San-Joaquin-Spearscale%29');
