INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis', 'Beach Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Spring, Summer, Winter', 'Partial Shade, Full Sun', 'Moderate', 'Use with other low-growing coastal plants such as Sand Verbena (Abronia latifolia or umbellata), Beach bur (Ambrosia chamissonis), Beach Morning Glory (Calystegia soldanella), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), and Oregon Gumweed (Grindelia stricta)', 'Coastal Strand, Northern Coastal Scrub', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 5.8-7.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. <br/>It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of shade. It does well in gardens with regular water and part shade.', null, 'https://calscape.org/Fragaria-chiloensis-%28Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis ''Aulon''', 'Aulon Beach Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Summer, Spring, Fall', 'Full Sun, Partial Shade', 'Moderate', '<p>Use with other low growing coastal plants such as Sand Verbena (Abronia latifolia or umbellata), Beach bur (Ambrosia chamissonis), Beach Morning Glory (Calystegia soldanella), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), and Coast Gumweed (Grindelia strict)</p>', null, null, null, 'https://calscape.org/Fragaria-chiloensis-%27Aulon%27-%28Aulon-Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis ''Carole Ann''', 'Carole Ann Beach Strawberry', 'Bats, Bees', 'White', 'Spring', 'Full Sun, Partial Shade', null, null, null, null, null, 'https://calscape.org/Fragaria-chiloensis-%27Carole-Ann%27-%28Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fritillaria liliacea', 'Fragrant Fritillary', null, 'White, Green', null, 'Full Sun', 'Low, Moderate, High', null, 'Coastal Prairie, Northern Coastal Scrub, Valley Grassland, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes heavy soils.', null, 'https://calscape.org/Fritillaria-liliacea-%28Fragrant-Fritillary%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis ''Green Pastures''', 'Green Pastures Beach Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Spring, Summer, Fall', 'Partial Shade, Full Sun', 'Moderate', 'Use with other low growing coastal plants such as Sand Verbena (Abronia latifolia or umbellata), Beach bur (Ambrosia chamissonis), Beach Morning Glory (Calystegia soldanella), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), and Coast Gumweed (Grindelia strict)', null, null, null, 'https://calscape.org/Fragaria-chiloensis-%27Green-Pastures%27-%28Green-Pastures-Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria chiloensis ''Lipstick''', 'Lipstick Beach Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'Pink', 'Spring, Summer, Fall', 'Partial Shade, Full Sun', 'Moderate', 'Use with other low growing coastal plants such as Sand Verbena (Abronia latifolia or umbellata), Beach bur (Ambrosia chamissonis), Beach Morning Glory (Calystegia soldanella), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), and Coast Gumweed (Grindelia strict)', null, null, null, 'https://calscape.org/Fragaria-chiloensis-%27Lipstick%27-%28Lipstick-Beach-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria vesca', 'Woodland Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Winter, Spring', 'Deep Shade, Full Sun, Partial Shade', 'Moderate', 'Use with woodland trees, shrubs and herbs such as False Indigo (Amorpha californica), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Incense Cedar (Calocedrus decurrens), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Fleabane (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Silk Tassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Crevice Alumroot (Heuchera micrantha), Ocean Spray (Holodiscus discolor), Leopard Lily (Lilium pardalinum), Tanoak (Notholithocarpus densiflorus), Douglas Fir (Pseudotsuga menziesii), and many others.', 'Chaparral, Closed-cone Pine Forest, Douglas-Fir Forest, Mixed Evergreen Forest, Yellow Pine Forest', 'Prefers sun or part shade.', null, 'https://calscape.org/Fragaria-vesca-%28Woodland-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria vesca ''Montana de Oro''', 'Montana de Oro Wood Strawberry', 'Bats, Birds, Butterflies, Caterpillars', 'White', 'Summer, Spring, Winter', 'Full Sun, Partial Shade, Deep Shade', 'Moderate', '<p>Use with woodland trees, shrubs and herbs such as False Indigo (Amorpha californica), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Incense Cedar (Calocedrus decurrens), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Fleabane (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Silk Tassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Crevice Alumroot (Heuchera micrantha), Ocean Spray (Holodiscus discolor), Leopard Lily (Lilium pardalinum), Tanoak (Notholithocarpus densiflorus), Douglas Fir (Pseudotsuga menziesii), and many others.</p>', null, null, null, 'https://calscape.org/Fragaria-vesca-%27Montana-De-Oro%27-%28Montana-De-Oro-Wood-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fragaria virginiana', 'Mountain Strawberry', 'Birds, Butterflies, Caterpillars', 'White', 'Spring, Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers sun or part shade. Likes moist soils.', null, 'https://calscape.org/Fragaria-virginiana-%28Mountain-Strawberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Frankenia palmeri', 'Palmer''s Seaheath', 'Butterflies, Caterpillars', 'Pink, White', null, 'Full Sun', 'Very Low', null, 'Alkali Sink, Coastal Salt Marsh, Coastal Strand, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes alkali soils.', null, 'https://calscape.org/Frankenia-palmeri-%28Palmer%27s-Seaheath%29');
