INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Frankenia salina', 'Alkali Heath', 'Butterflies, Caterpillars', 'Pink, White', 'Spring, Summer, Fall', 'Full Sun', 'Very Low', '<p>Use with other wetland plants such as Salt Grass (Distichlis spicata), Yellow Monkeyflower (Erythranthe guttata), Sedge (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), Rush (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), Willow (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), and Alkali Weed (Cressa truxillensis)</p>', 'Coastal Salt Marsh, Coastal Strand, Wetland-Riparian', '<p>Requires moist soil. Prefers sun. Likes saline or alkaline soils.</p>', null, 'https://calscape.org/Frankenia-salina-%28Alkali-Heath%29');
