INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fritillaria affinis', 'Checker Lily', null, 'Yellow, Green, Purple, Cream, Brown', 'Spring', 'Partial Shade', 'Very Low', '<p>Best used with native grasses, spring annuals, and other geophytes such as Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>). May be used in the understory of Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), various Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), and larger chaparral shrubs.</p>', 'Chaparral, Foothill Woodland, Mixed Evergreen Forest, Northern Coastal Scrub, Yellow Pine Forest', '<p>Prefers part shade. Likes grassy areas.</p>', null, 'https://calscape.org/Fritillaria-affinis-%28Checker-Lily%29');
