INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Fritillaria pudica', 'Gold Bell', null, 'Yellow, Red', 'Spring, Winter', 'Full Sun', 'Very Low', null, 'Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 6.5-9. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Fritillaria pudica is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes slopes.', null, 'https://calscape.org/Fritillaria-pudica-%28Gold-Bell%29');
