INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Galium trifidum', 'Threepetal Bedstraw', 'Butterflies, Caterpillars', 'White, Pink', 'Summer', 'Partial Shade', null, null, 'Alpine Fell-Fields, Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 4.6-8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Galium trifidum is not drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers part shade. Likes wet soils.', null, 'https://calscape.org/Galium-trifidum-%28Threepetal-Bedstraw%29');
