INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gambelia speciosa ''Boca Rosa''', 'Boca Rosa Showy Island Snapdragon', 'Birds, Butterflies, Hummingbirds', 'Red', 'Spring', 'Full Sun, Partial Shade', 'Very Low', 'Island companion plants include Santa Cruz Island Ironwood (Lyonothamnus floribundus ssp. asplenifolius), Island Live Oak (Quercus tometella), Tree Poppy (Dendromecon harfordii), Island Bristleweed (Hazardia detonsa), Redflower Buckwheat (Eriogonum grande var. rubescens), Catalina Cherry (Prunus ilicifolia ssp. lyonii), and Giant Coreopsis (Leptosyne gigantea). Other chaparral and sage scrub companions include California Encelia (Encelia californica), California Sagebrush (Artemisia californica), Bladderpod (Peritoma arborea), and <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>', null, null, null, 'https://calscape.org/Gambelia-speciosa-%27Boca-Rosa%27-%28Boca-Rosa-Showy-Island-Snapdragon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gambelia speciosa ''Firecracker''', 'Firecracker Showy Island Snapdragon', 'Birds, Butterflies, Hummingbirds', 'Red', 'Spring', 'Full Sun, Partial Shade', 'Very Low', 'Island companion plants include Santa Cruz Island Ironwood (Lyonothamnus floribundus ssp. asplenifolius), Island Live Oak (Quercus tometella), Tree Poppy (Dendromecon harfordii), Island Bristleweed (Hazardia detonsa), Redflower Buckwheat (Eriogonum grande var. rubescens), Catalina Cherry (Prunus ilicifolia ssp. lyonii), and Giant Coreopsis (Leptosyne gigantea). Other chaparral and sage scrub companions include California Encelia (Encelia californica), California Sagebrush (Artemisia californica), Bladderpod (Peritoma arborea), and <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>', null, null, null, 'https://calscape.org/Gambelia-speciosa-%27Firecracker%27-%28Firecracker-Showy-Island-Snapdragon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gambelia speciosa ''Pink Panther''', 'Pink Panther Snapdragon', 'Birds, Butterflies, Hummingbirds', 'Pink', 'Spring', 'Full Sun, Partial Shade', 'Very Low', '<p>Island companion plants include Santa Cruz Island Ironwood (Lyonothamnus floribundus ssp. asplenifolius), Island Live Oak (Quercus tometella), Tree Poppy (Dendromecon harfordii), Island Bristleweed (Hazardia detonsa), Redflower Buckwheat (Eriogonum grande var. rubescens), Catalina Cherry (Prunus ilicifolia ssp. lyonii), and Giant Coreopsis (Leptosyne gigantea). Other chaparral and sage scrub companions include California Encelia (Encelia californica), California Sagebrush (Artemisia californica), Bladderpod (Peritoma arborea), and <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a></p>', null, null, null, 'https://calscape.org/Gambelia-speciosa-%27Pink-Panther%27-%28Pink-Panther-Snapdragon%29');
