INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gentiana calycosa', 'Rainier Pleated Gentian', 'Butterflies, Caterpillars', 'Blue, Purple', 'Summer', 'Deep Shade, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 5.6-7.5. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Gentiana calycosa is not drought tolerant. It requires a minimum of 25 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. Prefers shade. Likes wet meadows and slopes.', null, 'https://calscape.org/Gentiana-calycosa-%28Rainier-Pleated-Gentian%29');
