INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geranium carolinianum', 'Carolina Crane''s-bill', 'Birds, Butterflies, Caterpillars', 'White, Lavender', null, null, 'Moderate', null, 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest', null, null, 'https://calscape.org/Geranium-carolinianum-%28Carolina-Crane%27s-bill%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geranium oreganum', 'Oregon Geranium', 'Birds, Butterflies, Caterpillars', 'Purple, Lavender', 'Spring', 'Partial Shade', 'Moderate', null, 'Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 7-8. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Geranium oreganum is not drought tolerant. It requires a minimum of 55 inches of water per year, and a maximum of 125 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers part shade. Likes moist soils and meadows.', null, 'https://calscape.org/Geranium-oreganum-%28Oregon-Geranium%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geranium richardsonii', 'Richardson''s Geranium', 'Butterflies, Caterpillars', 'Purple, White', 'Spring', null, 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Wetland-Riparian, Yellow Pine Forest', null, null, 'https://calscape.org/Geranium-richardsonii-%28Richardson%27s-Geranium%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gilia aliquanta ssp. aliquanta', 'Puffcalyx Gilia', 'Butterflies, Caterpillars', null, null, null, null, null, null, null, null, 'https://calscape.org/Gilia-aliquanta-ssp.-aliquanta-%28Puffcalyx-Gilia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geranium viscosissimum', 'Sticky Geranium', 'Birds, Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun, Partial Shade', 'Moderate', null, 'Northern Juniper Woodland, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy soils that are at least 6 inches deep, with a pH of 7-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Geranium viscosissimum is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 19 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Geranium-viscosissimum-%28Sticky-Geranium%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geum aleppicum', 'Aleppo', 'Butterflies, Caterpillars', 'Yellow', null, null, 'Moderate', null, null, null, null, 'https://calscape.org/Geum-aleppicum-%28Aleppo%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geum macrophyllum', 'Large Leaved Avens', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Deep Shade, Partial Shade', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 5-7. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Geum macrophyllum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. Prefers shade.', null, 'https://calscape.org/Geum-macrophyllum-%28Large-Leaved-Avens%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geum macrophyllum var. macrophyllum', 'Largeleaf Avens', 'Butterflies, Caterpillars', null, null, null, 'Moderate', null, null, null, null, 'https://calscape.org/Geum-macrophyllum-var.-macrophyllum-%28Largeleaf-Avens%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geum macrophyllum var. perincisum', 'Largeleaf Avens', 'Butterflies, Caterpillars', null, null, null, 'Moderate', null, null, null, null, 'https://calscape.org/Geum-macrophyllum-var.-perincisum-%28Largeleaf-Avens%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Geum triflorum', 'Old Man''s Whiskers', 'Butterflies, Caterpillars', 'Purple', 'Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Northern Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest', 'Plant in loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. It requires a minimum of 16 inches of water per year, and a maximum of 40 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'https://calscape.org/Geum-triflorum-%28Old-Man%27s-Whiskers%29');
