INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gilia tricolor', 'Tricolor Gilia', 'Bats, Bees, Butterflies, Caterpillars', 'Blue, Lavender, White', 'Summer, Spring', 'Full Sun', 'Low', '<p>It is best used in a meadow-like setting with other annuals, herbaceous perennials and geophytes, including Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), Owl''s Clover (Castilleja exserta), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia heterophylla), Blue Dicks (Dichelostemma capitatum), California Poppy (Eschscholzia californica), Tidy Tips (Layia platyglossa), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Baby Blue Eyes (Nemophila menziesii), Wind Poppy (Papaver heterphyllum), and <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a></p>', 'Foothill Woodland, Valley Grassland', '<p>Prefers sun.</p>', null, 'https://calscape.org/Gilia-tricolor-%28Tricolor-Gilia%29');
