INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia camporum', 'Great Valley Gumweed', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Spring, Fall', 'Full Sun', 'Very Low, Low', '<p>Because this plant is fairly widespread across the state, companion plants will depend on locality but may include native grasses, <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Poppies (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a> or <a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a>), and various native cactus and succulents.</p>', 'Chaparral, Coastal Sage Scrub, Valley Grassland, Wetland-Riparian', '<p>Requires moist soil. Prefers sun. Likes deep sandy or saline soils. This plant is not particularly drought tolerant. It likes summer water every 2-4 weeks.</p>', 'Highly resinous nature defends this plant against herbivory from insects.', 'https://calscape.org/Grindelia-camporum-%28Great-Valley-Gumweed%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia fraxinipratensis', 'Ash Meadows Gumplant', 'Butterflies, Caterpillars', 'Yellow', null, null, null, null, null, null, null, 'https://calscape.org/Grindelia-fraxinipratensis-%28Ash-Meadows-Gumplant%29');
