INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia hirsutula', 'Gumweed', 'Butterflies', 'Red, Yellow, Purple, Brown', 'Summer, Fall', 'Full Sun', 'Very Low, Low', null, 'Wetland-Riparian', '<p>Requires moist soil. Prefers sun, part shade. Likes sandy or clay slopes.</p>', null, 'https://calscape.org/Grindelia-hirsutula-%28Gumweed%29-2');
