INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia stricta', 'Oregon Gumweed', 'Bats, Butterflies, Caterpillars', 'Yellow, Red', 'Spring, Summer, Fall', 'Full Sun, Partial Shade', 'Low, Moderate, Very Low', 'Other coastal plants such as Sand Verbena (<a href="/search/?plant=Abronia%20(Genus)">Abronia spp.</a>), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Morningglory (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Beach Evening Primrose (Camissoniopsis cheiranthifolia), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Hummingbird Sage (Salvia spathacea), Penstemon species.', 'Coastal Salt Marsh, Coastal Strand, Northern Coastal Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes streamside.', null, 'https://calscape.org/Grindelia-stricta-%28Oregon-Gumweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia stricta var. angustifolia', 'Marsh Gumplant', 'Bats, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low, Moderate, Very Low', null, 'Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes tidal flats.', null, 'https://calscape.org/Grindelia-stricta-var.-angustifolia-%28Marsh-Gumplant%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Grindelia stricta var. platyphylla', 'Gumweed', 'Bats, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun, Partial Shade', 'Low, Moderate', 'Other coastal plants such as Sand Verbena (<a href="/search/?plant=Abronia%20(Genus)">Abronia spp.</a>), Silver Beachweed (Ambrosia chamissonis), Beach Sage (Artemisia pycnocephala), Morningglory (<a href="/search/?plant=Calystegia%20(Genus)">Calystegia spp.</a>), Beach Evening Primrose (Camissoniopsis cheiranthifolia), Seaside Daisy (<a href="/search/?plant=Erigeron%20(Genus)">Erigeron spp.</a>), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Hummingbird Sage (Salvia spathacea), Penstemon species.', 'Coastal Sage Scrub, Coastal Salt Marsh, Coastal Strand, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes tidal flats.', null, 'https://calscape.org/Grindelia-stricta-var.-platyphylla-%28Gumweed%29');
