INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Gutierrezia californica', 'California Matchweed', 'Bees, Butterflies, Caterpillars', 'Yellow, Red', 'Spring, Summer, Fall', 'Full Sun', 'Very Low', 'May be used with a wide variety of chaparral plants such as Chamise (Adenostema fasciculatum), Big Sagebrush (Artemisia tridentata), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), White Sage (Salvia apiana), Cleveland Sage (Salvia clevelandii), Desert Sage (Salvia dorrii), Rose Sage (Salvia pachyphylla) Antelope Brush (Purshia stansburyana or tridentata), and various cactus and succulents.', 'Chaparral, Oak Woodland, Pinyon-Juniper Woodland, Valley Grassland', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Gutierrezia-californica-%28California-Matchweed%29');
