INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helianthus annuus ''Claremont Sunshine''', 'Claremont Sunshine Sunflower', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low', '<p>This plant can be used with many native plants in the garden as long as they can accept regular water. A good use might be as a border between native plants and vegetables.</p>', null, null, null, 'https://calscape.org/Helianthus-annuus-%27Claremont-Sunshine%27-%28Claremont-Sunshine-Sunflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helenium autumnale', 'Common Sneezeweed', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Fall, Summer', 'Partial Shade', 'Moderate', null, 'Alkali Sink, North Coastal Coniferous Forest, Sagebrush Scrub, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 4-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Helenium autumnale is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers part shade. Likes wet soils.', null, 'https://calscape.org/Helenium-autumnale-%28Common-Sneezeweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helenium bigelovii', 'Bigelow''s Sneezeweed', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'High, Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes wet meadows.', null, 'https://calscape.org/Helenium-bigelovii-%28Bigelow%27s-Sneezeweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helenium bolanderi', 'Coastal Sneezeweed', 'Bees, Butterflies, Caterpillars', 'Yellow', null, null, null, null, 'Northern Coastal Scrub, Wetland-Riparian', null, null, 'https://calscape.org/Helenium-bolanderi-%28Coastal-Sneezeweed%29');
