INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helianthus annuus', 'Sunflower', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Orange, Yellow, Brown', 'Summer', 'Full Sun', 'Low', '<p>This plant can be used with many native plants in the garden as long as they can accept regular water. A good use might be as a border between native plants and vegetables.</p>', 'Weed (disturbed places), Wetland-Riparian', '<p>Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 5.5-7.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Helianthus annuus is moderately drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun.</p>', null, 'https://calscape.org/Helianthus-annuus-%28Sunflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helianthus bolanderi', 'Serpentine Sunflower', 'Bees, Birds, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'Low, Moderate, High', null, 'Chaparral, Foothill Woodland, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers sun.', null, 'https://calscape.org/Helianthus-bolanderi-%28Serpentine-Sunflower%29');
