INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Helianthus gracilentus', 'Slender Sunflower', 'Bees, Birds, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low', 'Use with Toyon (Heteromeles arbutifolia), Lemonadeberry (Rhus integrifolia), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Ceanothus species, Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Giant Wild Rye (Elymus condensatus), Sand Aster (Corethrogyne filaginifolia), Sagebrush (Artemisia californica), Monkeyflower (<a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Heartleaf Keckiella (Keckiella cordifolia), Penstemon species, Salvia species, and Blue-eyed Grass (Sisyrinchium bellum)', 'Chaparral, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun. Likes flat soils.', null, 'https://calscape.org/Helianthus-gracilentus-%28Slender-Sunflower%29');
