INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heterotheca villosa', 'Hairy False Goldenaster', 'Bees, Butterflies, Caterpillars', 'Yellow, Brown', 'Summer', 'Full Sun', 'Low, Moderate', null, 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Joshua Tree Woodland, Mixed Evergreen Forest, Northern Coastal Scrub, Red Fir Forest, Sagebrush Scrub, Valley Grassland, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Heterotheca villosa is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 26 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes rock crevices.', null, 'https://calscape.org/Heterotheca-villosa-%28Hairy-False-Goldenaster%29');
