INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera cylindrica', 'Alpine Alumroot', 'Hummingbirds', 'White, Cream', 'Spring', 'Partial Shade', 'Very Low', null, 'Northern Juniper Woodland, Red Fir Forest, Yellow Pine Forest', 'Plant in sandy soils that are at least 6 inches deep, with a pH of 7-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Heuchera cylindrica is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 35 inches of water per year once established. It is moderately tolerant of full shade. Prefers part shade. Likes rocky slopes.', null, 'https://calscape.org/Heuchera-cylindrica-%28Alpine-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera cylindrica ''Chartreuse''', 'Chartreuse Alumroot', 'Hummingbirds', 'Pink', 'Spring, Summer', 'Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Heuchera-cylindrica-%27Chartreuse%27-%28Chartreuse-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera cylindrica ''Greenfinch''', 'Greenfinch Roundleaf Alumroot', 'Hummingbirds', 'Green', 'Spring', 'Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Heuchera-cylindrica-%27Greenfinch%27-%28Greenfinch-Roundleaf-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera cylindrica ''Red Bud''', 'Red Bud Roundleaf Alumroot', 'Hummingbirds', 'Red, Pink', 'Spring, Summer', 'Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Heuchera-cylindrica-%27Red-Bud%27-%28Red-Bud-Roundleaf-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera hirsutissima', 'Shaggy Haired Alumroot', 'Hummingbirds', 'Pink, White', 'Summer', 'Partial Shade, Deep Shade', 'Low, Moderate', '<p>Can be used with a variety of sub-shrubs and perennial herbs in a rock garden or woodland garden</p>', 'Red Fir Forest, Subalpine Forest', '<p>Requires fast draining soil. Prefers shade. Likes rocky soils.</p>', null, 'https://calscape.org/Heuchera-hirsutissima-%28Shaggy-Haired-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera hirsutissima ''Santa Rosa''', 'Santa Rosa Alumroot', 'Hummingbirds', 'Pink', 'Summer', 'Deep Shade, Partial Shade', 'Low, Moderate', 'Can be used with a variety of sub-shrubs and perennial herbs in a rock garden or woodland garden', null, null, null, 'https://calscape.org/Heuchera-hirsutissima-%27Santa-Rosa%27-%28Santa-Rosa-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera pilosissima', 'Seaside Alumroot', 'Hummingbirds', 'Pink, Yellow, White', null, 'Deep Shade, Partial Shade', 'Very Low', null, 'Closed-cone Pine Forest, Forest', '<p>Requires fast draining soil. Prefers shade. Likes sandy soils.</p>', null, 'https://calscape.org/Heuchera-pilosissima-%28Seaside-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera pilosissima var. hemisphaerica', 'Seaside Alumroot', null, null, null, 'Partial Shade', null, null, 'Closed-cone Pine Forest, Forest', 'Prefers part shade.', null, 'https://calscape.org/Heuchera-pilosissima-var.-hemisphaerica-%28Seaside-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera maxima', 'Island Alum Root', 'Birds, Hummingbirds', 'Pink, White', 'Spring, Winter', 'Full Sun, Partial Shade, Deep Shade', 'Low, Moderate', '<p>Use with other Channel Island species such as:</p><p><br></p><p>Trees: Island Ironwood (Lyonothamnus floribundus ssp. asplenifolius), Island Cherry (Prunus ilicifolia ssp. lyonii), Island Oak (Quercus tomentella)</p><p><br></p><p>Shrubs and herbs: Island Ceanothus (Ceanothus arboreus), California Encelia (Encelia californica), St. Catherine''s Lace (Eriogonum giganteum), Santa Rosa Island Sage (Salvia brandegeei), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, Yucca species</p>', 'Chaparral, Coastal Sage Scrub', '<p>Prefers part shade in coastal regions (without salt spray). Likes rock walls. Tolerates clay rich and alkaline soils. It likes summer water every 2-4 weeks. Great to use as a groundcover under evergreen oaks; does well with mulch if there isn''t enough leaf litter.</p>', null, 'https://calscape.org/Heuchera-maxima-%28Island-Alum-Root%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera merriamii', 'Merriam''s Alumroot', 'Hummingbirds', 'Pink, Yellow, Cream', null, 'Full Sun, Partial Shade', null, null, 'Subalpine Forest', null, null, 'https://calscape.org/Heuchera-merriamii-%28Merriam%27s-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera micrantha', 'Crevice Alumroot', 'Butterflies, Caterpillars, Hummingbirds', 'Green, Purple, Pink, White', 'Summer, Spring', 'Partial Shade, Deep Shade', 'Moderate', '<p>Trees: Tanoak (Notholithocarpus densiflorus), Madrone (Arbutus menziesii), Douglas Fir (Pseudotsuga menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Bay Laurel (Umbellularia californica), Red Fir (Abies magnifica), Ponderosa Pine (Pinus ponderosa)</p><p>Other plants: Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Coffeeberry (Frangula californica), Coast Silktassel (Garrya elliptica), Oceanspray (Holodiscus discolor), <a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>, Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Sticky Monkeyflower (Diplacus aurantiacus), Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), Snowberry (Symphoricarpos albus or mollis)</p>', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Red Fir Forest, Forest, Yellow Pine Forest', '<p>Requires fast draining soil. Prefers shade. Likes moist rocky slopes.</p>', null, 'https://calscape.org/Heuchera-micrantha-%28Crevice-Alumroot%29-4');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera micrantha ''Martha Roderick''', 'Martha Roderick Alumroot', 'Hummingbirds, Butterflies, Caterpillars', 'Pink, Pink', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Moderate', 'Trees: Tanoak (Notholithocarpus densiflorus), Madrone (Arbutus menziesii), Douglas Fir (Pseudotsuga menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Bay Laurel (Umbellularia californica), Red Fir (Abies magnifica), Ponderosa Pine (Pinus ponderosa)<br/><br><br>Other plants: Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Coffeeberry (Frangula californica), Coast Silktassel (Garrya elliptica), Oceanspray (Holodiscus discolor), <a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>, Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Sticky Monkeyflower (Diplacus aurantiacus), Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), Snowberry (Symphoricarpos albus or mollis)', null, null, null, 'https://calscape.org/Heuchera-micrantha-%27Martha-Roderick%27-%28Martha-Roderick-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera parishii', 'Mill Creek Alumroot', 'Hummingbirds', 'Pink', null, 'Partial Shade', null, null, 'Alpine Fell-Fields, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Prefers part shade. Likes rocky soils.', null, 'https://calscape.org/Heuchera-parishii-%28Mill-Creek-Alumroot%29');
