INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera rubescens', 'Pink Alumroot', 'Hummingbirds', 'Pink', 'Spring', 'Partial Shade', 'Low, Moderate, High', 'Use with Western Columbine (Aquilegia formosa), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia heterophylla), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Bleeding Heart (Dicentra formosa), Western Wallflower (Erysimum capitatum), Woodland Strawberry (Fragraria vesca), <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, Lily (<a href="/search/?plant=Lillium%20(Genus)">Lillium spp.</a>), Baby Blue Eyes (Nemophila menziesii), <a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>, Checkerbloom (<a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>), Cardinal Catchfly (Silene laciniata), Meadowrue (Thalictrum fendleri), and Violet (<a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>).', 'Chaparral, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun and part shade. Likes dry rocky soils.', null, 'https://calscape.org/Heuchera-rubescens-%28Pink-Alumroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Heuchera rubescens ''Yosemite''', 'Yosemite Pink Alumroot', 'Hummingbirds', 'White', 'Spring, Summer', 'Partial Shade', 'Low, Moderate, High', 'Use with Western Columbine (Aquilegia formosa), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia heterophylla), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Bleeding Heart (Dicentra formosa), Western Wallflower (Erysimum capitatum), Woodland Strawberry (Fragraria vesca), <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, Lily (<a href="/search/?plant=Lillium%20(Genus)">Lillium spp.</a>), Baby Blue Eyes (Nemophila menziesii), <a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>, Checkerbloom (<a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>), Cardinal Catchfly (Silene laciniata), Meadowrue (Thalictrum fendleri), and Violet (<a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>).', null, null, null, 'https://calscape.org/Heuchera-rubescens-%27Yosemite%27-%28Yosemite-Pink-Alumroot%29');
