INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hieracium albiflorum', 'White Hawkweed', 'Butterflies, Caterpillars', 'White', 'Spring', 'Partial Shade', 'Extremely Low, Very Low', null, 'Douglas-Fir Forest, Lodgepole Forest, Red Fir Forest, Forest, Yellow Pine Forest', 'Plant in loamy soils that are at least 12 inches deep, with a pH of 6.5-7.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Hieracium albiflorum is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of full shade. Prefers part shade.', null, 'https://calscape.org/Hieracium-albiflorum-%28White-Hawkweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hieracium argutum', 'Southern Hawkweed', 'Butterflies, Caterpillars', null, null, 'Full Sun, Partial Shade', null, null, 'Closed-cone Pine Forest, Southern Oak Woodland', null, null, 'https://calscape.org/Hieracium-argutum-%28Southern-Hawkweed%29');
