INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia crassifolia', 'Buck Lotus', 'Bees, Butterflies, Caterpillars', 'Red, Pink, Yellow, Brown', 'Spring, Summer', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 14 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Lotus crassifolius is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 24 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Hosackia-crassifolia-%28Buck-Lotus%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia crassifolia var. crassifolia', 'Big Deervetch', 'Butterflies, Caterpillars', 'Pink, Yellow', null, 'Full Sun, Partial Shade', null, null, 'Chaparral, Woodland', 'Prefers sun or part shade.', null, 'https://calscape.org/Hosackia-crassifolia-var.-crassifolia-%28Big-Deervetch%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia crassifolia var. otayensis', 'Otay Mtn. Lotus', 'Bats, Bees, Butterflies, Caterpillars', 'Purple, Cream', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low, Low, Moderate', '<p>In the wild it is found with numerous chaparral plants of southern California, including Chamise (Adenostema fasciculatum), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Viguiera (Bahiopsis laciniata), Golden-spined Cereus (Bergerocactus emoryi), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Mountain Mahogany (<a href="/search/?plant=Cercocarpus%20(Genus)">Cercocarpus spp.</a>), Cholla Cactus (<a href="/search/?plant=Cylindropuntia%20(Genus)">Cylindropuntia spp.</a>), Bush Poppy (Dendromecon rigida), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Mexican Flannelbush (Fremontodendron mexicanum), Tecate Cypress (Hesperocyparis forbesii), Sages (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Bluecurls (Trichostema lanatum and parishii), and many others. Many other companion plants in the Otay Mountain region are rare species.</p>', 'Chaparral', '<p>Prefers sun or part shade.This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Hosackia-crassifolia-var.-otayensis-%28Otay-Mtn.-Lotus%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia gracilis', 'Seaside Bird''s Foot Trefoil', 'Bats, Bees, Butterflies, Caterpillars', 'Orange, Pink, Red, White, Yellow', 'Spring, Summer', 'Full Sun', 'Low, Moderate, High', 'Use with annuals or herbaceous perennials of the north coast such as Snapdragon (<a href="/search/?plant=Antirrhinum%20(Genus)">Antirrhinum spp.</a>), Sitka Columbine (Aquilegia formosa), Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Chinese Houses (Collinsia heterophylla), Western Wallflower (Erysimum capitatum), Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a>), Blue Field Gilia (Gilia capitata); with geophytes such as onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>); and with small succulents such as Dudleya spp.', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Northern Coastal Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun.', null, 'https://calscape.org/Hosackia-gracilis-%28Seaside-Bird%27s-Foot-Trefoil%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia incana', 'Woolly Bird''s-foot Trefoil', 'Butterflies, Caterpillars', 'Lavender', null, null, null, null, 'Yellow Pine Forest', null, null, 'https://calscape.org/Hosackia-incana-%28Woolly-Bird%27s-foot-Trefoil%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hosackia oblongifolia', 'Streambank Lotus', 'Butterflies, Caterpillars', 'Yellow, White', null, 'Full Sun, Partial Shade', null, null, 'Chaparral, Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers sun or part shade. Likes  moist soils.', null, 'https://calscape.org/Hosackia-oblongifolia-%28Streambank-Lotus%29');
