INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum alpestre', 'Alpine Waterleaf', null, null, null, 'Full Sun, Partial Shade, Deep Shade', null, null, 'Sagebrush Scrub, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or shade. Likes moist soils.', null, 'https://calscape.org/Hydrophyllum-alpestre-%28Alpine-Waterleaf%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum capitatum', 'Ballhead Waterleaf', null, 'Purple', 'Spring', 'Full Sun, Partial Shade, Deep Shade', null, null, 'Sagebrush Scrub, Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 6.4-7.8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Hydrophyllum capitatum is only slightly drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers sun or shade.', null, 'https://calscape.org/Hydrophyllum-capitatum-%28Ballhead-Waterleaf%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum fendleri', 'Fendler''s Waterleaf', null, null, null, 'Deep Shade, Partial Shade', null, null, 'Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes moist slopes.', null, 'https://calscape.org/Hydrophyllum-fendleri-%28Fendler%27s-Waterleaf%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum fendleri var. albifrons', 'White Waterleaf', null, null, null, 'Full Sun, Partial Shade', null, null, 'Red Fir Forest, Wetland-Riparian, Yellow Pine Forest', null, null, 'https://calscape.org/Hydrophyllum-fendleri-var.-albifrons-%28White-Waterleaf%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum occidentale', 'California Waterleaf', null, 'White, Lavender', 'Spring', 'Deep Shade, Partial Shade', null, null, 'Northern Oak Woodland, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy soils that are at least 14 inches deep, with a pH of 6.2-7.5. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Hydrophyllum occidentale is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Hydrophyllum-occidentale-%28California-Waterleaf%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Hydrophyllum tenuipes', 'Pacific Waterleaf', null, 'White, Green, Lavender', null, 'Partial Shade', 'Moderate, High', null, 'Douglas-Fir Forest, Mixed Evergreen Forest, Forest', 'Requires moist soil. Prefers part shade. Likes most wooded slopes.', null, 'https://calscape.org/Hydrophyllum-tenuipes-%28Pacific-Waterleaf%29');
