INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris douglasiana', 'Douglas Iris', 'Butterflies, Caterpillars', 'Blue, Pink, Purple, White, Yellow', 'Winter, Spring', 'Full Sun, Partial Shade, Deep Shade', 'Low, Moderate', 'Use with other plants that prefer rich, heavy soils and more moisture such as rushes (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), spikerush (<a href="/search/?plant=Eleocharis%20(Genus)">Eleocharis spp.</a>), sedges (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), California fuschia (Epilobium canum), Western Columbine (Aquilegia formosa), lilies, California Grape (Vitis californica), Wild Rose (Rosa californica), ferns, and trees such as Sycamore (Platanus racemosa), Bigleaf Maple (Acer macrophyllum), or willows (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>).', 'Closed-cone Pine Forest, Coastal Prairie, Coastal Sage Scrub, Mixed Evergreen Forest', 'Prefers part shade. It is tolerant of sand, clay, serpentine, and seasonal flooding. It likes summer water every 2-4 weeks. Prefers richer soils and does well when planted near building runoff for extra water.', null, 'https://calscape.org/Iris-douglasiana-%28Douglas-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iva axillaris', 'Poverty Weed', null, null, null, null, null, null, 'Alkali Sink, Coastal Salt Marsh, Wetland-Riparian', null, null, 'https://calscape.org/Iva-axillaris-%28Poverty-Weed%29');
