INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris innominata', 'Del Norte County Iris', null, 'Purple, Yellow', 'Spring', 'Partial Shade', 'Low', 'Rushes (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), spikerush (<a href="/search/?plant=Eleocharis%20(Genus)">Eleocharis spp.</a>), sedges (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), Red Columbine (Aquilegia formosa), California Grape (Vitis californica), Wild Rose (Rosa californica), ferns, lillies', 'Yellow Pine Forest', 'Requires fast draining soil with some moisture. Prefers sun or part shade. Likes slopes.', null, 'https://calscape.org/Iris-innominata-%28Del-Norte-County-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris innominata ''Ed Wood''', 'Ed Wood Del Norte County Iris', null, 'Purple', 'Spring', 'Partial Shade', 'Low', 'Rushes (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), spikerush (<a href="/search/?plant=Eleocharis%20(Genus)">Eleocharis spp.</a>), sedges (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), Red Columbine (Aquilegia formosa), California Grape (Vitis californica), Wild Rose (Rosa californica), ferns, lillies', null, null, null, 'https://calscape.org/Iris-innominata-%27Ed-Wood%27-%28Ed-Wood-Del-Norte-County-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris longipetala', 'Central Coast Iris', 'Butterflies, Caterpillars', 'Blue, Lavender, Purple, White', 'Spring', 'Deep Shade, Partial Shade', 'Low, Moderate, High', 'Use with other perennial herbs and annuals of the central and northern coast that share its moisture and soil preferences, such as Milkmaids (Cardamine californica), Cobwebby Thistle (Cirsium occidentale), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Checkerbloom (<a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>), and geophytes such as Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Fritillaria%20(Genus)">Fritillaria spp.</a>, and <a href="/search/?plant=Lilium%20(Genus)">Lilium spp.</a>', 'Coastal Prairie, Mixed Evergreen Forest, Wetland-Riparian', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Iris-longipetala-%28Central-Coast-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris macrosiphon', 'Long Tubed Iris', 'Butterflies, Caterpillars', 'Blue, Cream, Lavender, Pink, Purple, White, Yellow', 'Spring', 'Full Sun, Partial Shade', 'Low', 'Use as an understory with most native trees of northern California', 'Foothill Woodland, Mixed Evergreen Forest, Northern Oak Woodland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade. Likes  slopes.', null, 'https://calscape.org/Iris-macrosiphon-%28Long-Tubed-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris macrosiphon ''Mt. Madonna''', 'Mt. Madonna Ground Iris', 'Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun, Partial Shade', 'Low', 'Use as an understory with most native trees of northern California', null, null, null, 'https://calscape.org/Iris-macrosiphon-%27Mt.-Madonna%27-%28Mt.-Madonna-Ground-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iva hayesiana', 'San Diego Abundanceweed', null, 'Yellow, Green', null, 'Full Sun', 'Very Low, Low', '<p>Menzies'' Goldenbush (Isocoma menziesii), Blue Eyed Grass (Sisyrinchium bellum), Yerba Mansa (Anemopsis californica), Quailbush (Atriplex lentiformis ssp breweri), Deergrass (Muhlenbergia rigens), Western False Indigo (Amorpha fruticosa), San Diego Sedge (Carex spissa), Great Valley Gumweed (Grindelia camporum), Narrow Leaf Milkweed (Asclepias fascicularis), Douglas'' Sagewort (Artemisia douglasiana), Spiny Rush (Juncus acutus), San Diego Sagewort (Artemisia palmeri)</p>', 'Alkali Sink, Wetland-Riparian', '<p>Requires moist soil. Prefers sun. Likes alkali soils. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Iva-hayesiana-%28San-Diego-Povertyweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris missouriensis', 'Western Blue Flag', 'Butterflies, Caterpillars', 'Purple', 'Spring', 'Partial Shade, Full Sun', 'Low, Moderate, High', 'Consider pairing with deer fern (Blechnum spicant) or creek dogwood (Cornus sericea), both which also do well in wetter sites.', 'Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy, or clay soils that are at least 6 inches deep, with a pH of 6-8. It is tolerant of anaerobic soils, calcareous soils, infertile soils, and seasonal flooding. It prefers moist soils and requires a minimum of 24 inches of water per year, and a maximum of 35 inches of water per year once established. It is moderately tolerant of shade, preferring partial shade.', 'Pests to watch out for include the PCI borer (Amphipoea americana var. pacifica), which infects the rhizome. Dig out and remove infected plants entirely; dispose of in sealed plastic bags.', 'https://calscape.org/Iris-missouriensis-%28Western-Blue-Flag%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris munzii', 'Munz''s Iris', null, 'Yellow, Purple, Lavender, White', null, 'Full Sun, Partial Shade', null, null, null, null, null, 'https://calscape.org/Iris-munzii-%28Munz%27s-Iris%29');
