INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris purdyi', 'Purdy''s Iris', null, 'White, Pink, Yellow, Green, Lavender, Red', null, 'Deep Shade, Partial Shade', null, null, 'Mixed Evergreen Forest, North Coastal Coniferous Forest, Forest', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Iris-purdyi-%28Purdy%27s-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris tenax', 'Toughleaf Iris', 'Butterflies, Caterpillars', 'Purple, Lavender, Blue', 'Spring', 'Deep Shade, Partial Shade', 'Low', null, 'Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6-8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Iris tenax is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Iris-tenax-%28Toughleaf-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris tenax ssp. klamathensis', 'Orleans Iris', 'Butterflies, Caterpillars', 'White, Pink', 'Spring', 'Deep Shade', null, null, 'Yellow Pine Forest', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Iris-tenax-ssp.-klamathensis-%28Orleans-Iris%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Iris tenuissima', 'Longtube Iris', 'Butterflies, Caterpillars', 'White, Purple, Red, Brown', 'Spring', 'Full Sun, Partial Shade', 'Very Low, Low', null, 'Foothill Woodland, Mixed Evergreen Forest, Northern Oak Woodland, Yellow Pine Forest', 'Prefers sun or part shade. Likes dry soils.', null, 'https://calscape.org/Iris-tenuissima-%28Longtube-Iris%29');
