INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lasthenia californica', 'California Goldfields', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Winter, Spring', 'Partial Shade, Full Sun', 'Very Low, Low', 'Goldfields occurs with many other plants, but in the garden it is best used in a dense patch with other annuals such as Blue Gilia (Gilia capitata), Baby Blue-eyes (Nemophila menziesii), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Lupines (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Checkerbloom (<a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>), as well as succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a> and <a href="/search/?plant=Sedum%20(Genus)">Sedum spp.</a>', 'Coastal Prairie, Coastal Sage Scrub, Foothill Woodland, Northern Coastal Scrub, Northern Oak Woodland, Valley Grassland', 'Prefers sun.', null, 'https://calscape.org/Lasthenia-californica-%28California-Goldfields%29');
