INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lathyrus japonicus', 'Beach Pea', 'Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun', null, null, 'Coastal Strand', 'Plant in sandy or loamy soils that are at least 16 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Lathyrus japonicus is moderately drought tolerant. It requires a minimum of 30 inches of water per year, and a maximum of 60 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of shade. Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Lathyrus-japonicus-%28Beach-Pea%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lathyrus jepsonii', 'Jepson''s Pea', 'Butterflies, Caterpillars', 'Purple, Pink', null, 'Full Sun, Partial Shade, Deep Shade', null, null, 'Chaparral, Foothill Woodland, Freshwater Marsh, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Grows well in sun, shade or part shade. Likes wet soils.', null, 'https://calscape.org/Lathyrus-jepsonii-%28Jepson%27s-Pea%29');
