INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Layia platyglossa', 'Common Tidy Tips', 'Butterflies, Caterpillars', 'Yellow', 'Spring, Winter', 'Full Sun', 'Low', '<p>Use in a grassland or meadow-like garden with other annuals or herbaceous perennials such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, <a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>, Baby Blue Eyes (Nemophila menziesii) and <a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>; with geophytes such as <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), and Blue Dicks (Dipterostemon capitatus); and with succulents such as Dudleya spp. and various cactus species.</p>', 'Chaparral, Foothill Woodland, Northern Coastal Scrub, Valley Grassland, Yellow Pine Forest', '<p>Prefers sun and clay rich soils. Tolerates seaside conditions.</p>', null, 'https://calscape.org/Layia-platyglossa-%28Common-Tidy-Tips%29');
