INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium columbianum', 'Columbia Lily', 'Butterflies, Hummingbirds, Caterpillars', 'Yellow, Orange', 'Summer', 'Deep Shade, Partial Shade', 'Moderate', null, 'Northern Coastal Scrub, Forest', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Lilium-columbianum-%28Columbia-Lily%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium humboldtii', 'Humboldt''s Lily', 'Bats, Butterflies, Caterpillars, Hummingbirds', 'Red, Orange, Yellow, Purple, Brown', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low, Low, Moderate', '<p>Southern Maidenhair Fern (Adiantum capillus-veneris), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Spice Bush (Calycanthus occidentalis), Tree Anemone (Carpenteria californica), Ceanothus species, Western Redbud (Cercis occidentalis), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Silktassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Mallow (<a href="/search/?plant=Malacothamnus%20(Genus)">Malacothamnus spp.</a>), Mock Orange (Philidelphus lewisii), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), ferns</p>', 'Chaparral, Foothill Woodland, Yellow Pine Forest', '<p>Prefers sun or part shade. Tolerates clay if it is on a slope. Often grows in canyons or on north facing slopes. After established, it should survive the dry months with little to no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Lilium-humboldtii-%28Humboldt%27s-Lily%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium humboldtii ssp. humboldtii', 'Humboldt''s Lily', 'Butterflies, Hummingbirds, Caterpillars', 'Brown, Orange, Purple, Red, Yellow', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Moderate, Very Low', 'Southern Maidenhair Fern (Adiantum capillus-veneris), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Spice Bush (Calycanthus occidentalis), Tree Anemone (Carpenteria californica), Ceanothus species, Western Redbud (Cercis occidentalis), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Silktassel Bush (<a href="/search/?plant=Garrya%20(Genus)">Garrya spp.</a>), Mallow (<a href="/search/?plant=Malacothamnus%20(Genus)">Malacothamnus spp.</a>), Mock Orange (Philidelphus lewisii), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), ferns', 'Chaparral, Yellow Pine Forest', 'Prefers sun or part shade.', null, 'https://calscape.org/Lilium-humboldtii-ssp.-humboldtii-%28Humboldt%27s-Lily%29');
