INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium humboldtii ssp. ocellatum', 'Spotted Humboldt''s Lily', 'Butterflies, Hummingbirds, Caterpillars', 'Brown, Orange, Purple, Red, Yellow', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Moderate, Very Low', 'Use in the understory of trees and large shrubs of the south Coast Ranges or Channel Islands, such as Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Santa Cruz Island Ironwood (Lyonothamnus floribundus ssp. aspleniifolius), Toyon (Heteromeles arbutifolia), Summer Holly (Comarostaphylis diversifolia ssp. diversifolia), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, and Holly-leafed Cherry (Prunus ilicifolia).', 'Chaparral, Foothill Woodland, Yellow Pine Forest', 'Prefers sun or part shade.', null, 'https://calscape.org/Lilium-humboldtii-ssp.-ocellatum-%28Spotted-Humboldt%27s-Lily%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium kelleyanum', 'Kelley''s Lily', 'Butterflies, Hummingbirds, Caterpillars', 'Yellow, Orange, Red', null, 'Deep Shade, Partial Shade', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Lilium-kelleyanum-%28Kelley%27s-Lily%29');
