INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lilium pardalinum', 'Tiger Lily', 'Butterflies, Hummingbirds, Caterpillars', 'Orange, Red, Brown', 'Summer', 'Partial Shade, Full Sun', 'Low, Moderate, Very Low', 'Trees: Coast Redwood (Sequoia sempervirens), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Madrone (Arbutus menziesii), Incense Cedar (Calocedrus decurrens), Coast Silktassel (Garrya elliptica), Tanoak (Notholithocarpus densiflorus), Douglas Fir (Pseudotsuga menziesii), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), California Laurel (Umbellularia californica), and others<br><br>Shrubs/herbs: Oneleaf Onion (Allium unifolium), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Barberry (<a href="/search/?plant=Berberis%20(Genus)">Berberis spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Miner''s Lettuce (Claytonia perfiolata), Yerba Buena (Clinopodium douglasii), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Crevise Alumroot (Heuchera micrantha), <a href="/search/?plant=Iris%20(Genus)">Iris spp.</a>, Pink Honeysuckle (Lonicera hispidula), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Currant (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), <a href="/search/?plant=Trillium%20(Genus)">Trillium spp.</a>, <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a>, and <a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>', 'Mixed Evergreen Forest, North Coastal Coniferous Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers part shade.', null, 'https://calscape.org/Lilium-pardalinum-%28Tiger-Lily%29');
