INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Linnaea borealis', 'WesternTwinflower', null, 'Pink', null, 'Deep Shade, Partial Shade', null, 'Plant with other associated forest species, such as Cascara Sagrada (Frangula purshiana), Western Azalea (Rhododendron occidentale), Western Brakenfern (Pteridium aquilinum), and Bigflower Tellima (Tellima grandiflora).', 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes moist soils.', null, 'https://calscape.org/Linnaea-borealis-%28WesternTwinflower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Linnaea borealis var. longiflora', 'Twin Flower', null, 'Pink', null, 'Deep Shade, Partial Shade', null, 'Western Azalea (Rhododendron occidentale)', 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires fast draining soil. Prefers shade. Likes moist soils.', null, 'https://calscape.org/Linnaea-borealis-var.-longiflora-%28Twin-Flower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Linum lewisii', 'Prairie Flax', 'Bats, Butterflies, Caterpillars', 'Blue, Lavender, White', 'Summer, Spring', 'Full Sun', 'Very Low, Low', '<p>Combine with complementary colored annuals or other perennial herbs such as California Poppy (Eschscholzia californica), Golden Yarrow (Eriophyllum confertiflorum) and Clarkia species</p>', 'Foothill Woodland, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', '<p>Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 5.6-8.4. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. It requires a minimum of 10 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate shade well and prefers sun. Likes dry slopes. It likes summer water at least once per month, and at most twice per week. Does well when grown near the ocean and does okay in the desert if it gets water.</p>', null, 'https://calscape.org/Linum-lewisii-%28Prairie-Flax%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Linum lewisii var. lewisii', 'Prairie Flax', 'Butterflies, Caterpillars', null, null, 'Full Sun', 'Low, Very Low', null, 'Foothill Woodland, Lodgepole Forest, Pinyon-Juniper Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Prefers sun. Likes dry slopes.', null, 'https://calscape.org/Linum-lewisii-var.-lewisii-%28Prairie-Flax%29');
