INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lithospermum ruderale', 'Columbia Puccoon', 'Butterflies, Caterpillars', 'White, Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Northern Juniper Woodland, Sagebrush Scrub', 'Plant in loamy soils that are at least 12 inches deep, with a pH of 6-7.8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lithospermum ruderale is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes dry slopes.', null, 'https://calscape.org/Lithospermum-ruderale-%28Columbia-Puccoon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lobelia cardinalis', 'Cardinal Flower', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red', 'Summer', 'Deep Shade, Partial Shade, Full Sun', 'Moderate, High', null, 'Bogs, Chaparral, Coastal Sage Scrub, Freshwater Marsh, Riparian Woodland, Wetland-Riparian', 'Plant in loamy soils that are at least 12 inches deep, with a pH of 5.8-7.8. It tolerates calcareous and infertile soils. This plant likes lots of water, requiring a minimum of 28 inches of water per year. It is tolerant of seasonal flooding. It is happy in full sun, part shade or full shade, as long as it gets plenty of water. Likes stream bottoms and seeps and even tolerates soil with no drainage. If not planted near a water source or in a year round wet area, in needs regular irrigation.', null, 'https://calscape.org/Lobelia-cardinalis-%28Cardinal-Flower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lobelia cardinalis var. pseudosplendens', 'Cardinal Flower', 'Hummingbirds, Butterflies, Caterpillars', null, null, 'Full Sun', null, null, 'Chaparral, Coastal Sage Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes stream bottoms.', null, 'https://calscape.org/Lobelia-cardinalis-var.-pseudosplendens-%28Cardinal-Flower%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lobelia dunnii', 'Dunn''s Lobelia', 'Butterflies, Hummingbirds, Caterpillars', 'Lavender', 'Summer, Fall', 'Full Sun, Partial Shade, Deep Shade', 'High', null, 'Chaparral, Coastal Sage Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun or shade. Likes moist rock walls.', null, 'https://calscape.org/Lobelia-dunnii-%28Dunn%27s-Lobelia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lobelia dunnii var. serrata', 'Dunn''s Lobelia', 'Butterflies, Hummingbirds, Caterpillars', 'Lavender', 'Summer, Fall', 'Full Sun, Partial Shade, Deep Shade', 'High', null, 'Chaparral, Coastal Sage Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun or shade. Likes moist rock walls.', null, 'https://calscape.org/Lobelia-dunnii-var.-serrata-%28Dunn%27s-Lobelia%29');
