INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lomatium canbyi', 'Canby''s Biscuitroot', 'Butterflies, Caterpillars', 'White', 'Spring', 'Full Sun', null, null, 'Sagebrush Scrub', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 6-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lomatium canbyi is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes rocky soils.', null, 'https://calscape.org/Lomatium-canbyi-%28Canby%27s-Biscuitroot%29');
