INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lomatium dissectum', 'Fernleaf Biscuitroot', 'Butterflies, Caterpillars', 'Purple, Yellow, Red', 'Summer', 'Partial Shade', null, null, 'Mixed Evergreen Forest, Pinyon-Juniper Woodland, Red Fir Forest, Southern Oak Woodland, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 6.5-7.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Lomatium dissectum is extremely drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 100 inches of water per year once established. It is moderately tolerant of full shade. Prefers part shade. Likes wooded or brushy slopes.', null, 'https://calscape.org/Lomatium-dissectum-%28Fernleaf-Biscuitroot%29');
