INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus latifolius', 'Broadleaf Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Blue, Purple', 'Spring', 'Full Sun, Partial Shade, Deep Shade', 'Low', null, 'Chaparral, Coastal Sage Scrub, Douglas-Fir Forest, Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', '<p>Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 6.5-7. It is tolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Lupinus latifolius is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 15 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Grows well in sun, shade or part shade.</p>', null, 'https://calscape.org/Lupinus-latifolius-%28Broadleaf-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus latifolius var. dudleyi', 'Broadleaf Lupine', 'Butterflies, Caterpillars', 'Blue, Lavender, Purple', null, null, 'Low', null, 'Wetland-Riparian', null, null, 'https://calscape.org/Lupinus-latifolius-var.-dudleyi-%28Broadleaf-Lupine%29');
