INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus luteolus', 'Pale Yellow Lupine', 'Bees, Birds, Butterflies, Caterpillars', 'Yellow, Blue, Lavender, Purple', 'Summer', 'Full Sun', 'Moderate', null, 'Foothill Woodland, Northern Oak Woodland, Pinyon-Juniper Woodland, Valley Grassland, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 9 inches deep, with a pH of 6.4-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Lupinus luteolus is extremely drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 30 inches of water per year once established. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Lupinus-luteolus-%28Pale-Yellow-Lupine%29');
