INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus milobakeri', 'Milo Baker''s Lupine', 'Bees, Butterflies, Caterpillars', 'Blue, Lavender, Purple', null, 'Full Sun, Partial Shade', 'Moderate', null, 'Foothill Woodland, Valley Grassland', 'Prefers sun, part shade.', null, 'https://calscape.org/Lupinus-milobakeri-%28Milo-Baker%27s-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus nanus', 'Sky Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Blue, Lavender', 'Winter, Spring', 'Full Sun', 'Moderate', '<p>Use with medium size shrubs that won''t overwhelm it, such as California Brittlebush (Encelia californica), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a> Redberry (Rhamnus crocea); with succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, Yucca (<a href="/search/?plant=Hesperoyucca%20(Genus)">Hesperoyucca spp.</a> and <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>) and cacti; with other wildflowers such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>; and with geophytes such as Wild Onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a></p>', 'Coastal Prairie, Coastal Sage Scrub, Foothill Woodland, Northern Coastal Scrub, Valley Grassland', '<p>Requires fast draining soil. Prefers sun.</p>', null, 'https://calscape.org/Lupinus-nanus-%28Sky-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus pachylobus', 'Big Pod Lupine', 'Bees, Butterflies, Caterpillars', 'Blue, Lavender, Purple', null, null, 'Moderate', null, 'Foothill Woodland, Valley Grassland', null, null, 'https://calscape.org/Lupinus-pachylobus-%28Big-Pod-Lupine%29');
