INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus nanus ''Pacific Pink''', 'Pacific Pink Sky Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Pink', 'Spring', 'Full Sun', 'Moderate', 'Use with medium size shrubs that won''t overwhelm it, such as California Brittlebush (Encelia californica), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a> Redberry (Rhamnus crocea); with succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, Yucca (<a href="/search/?plant=Hesperoyucca%20(Genus)">Hesperoyucca spp.</a> and <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>) and cacti; with other wildflowers such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>; and with geophytes such as Wild Onioins (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a>', null, null, null, 'https://calscape.org/Lupinus-nanus-%27Pacific-Pink%27-%28Pacific-Pink-Sky-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus nanus ''Pixie Delight''', 'Pixie Delight Sky Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Purple, White', 'Spring', 'Full Sun', 'Moderate', 'Use with medium size shrubs that won''t overwhelm it, such as California Brittlebush (Encelia californica), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a> Redberry (Rhamnus crocea); with succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, Yucca (<a href="/search/?plant=Hesperoyucca%20(Genus)">Hesperoyucca spp.</a> and <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>) and cacti; with other wildflowers such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>; and with geophytes such as Wild Onioins (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a>', null, null, null, 'https://calscape.org/Lupinus-nanus-%27Pixie-Delight%27-%28Pixie-Delight-Sky-Lupine%29');
