INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus odoratus', 'Royal Lupine', 'Bees, Birds, Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun', 'Moderate', 'Use with other highe desert plants such as Utah Agave (Agave utahensis), Bigberry Manzanita (Arctostaphylos glauca), Big Sagebrush (Artemisia tridentata), Desert Ceanothus (Ceanothus greggii), Apache Plume (Fallugia paradoxa), California Juniper (Juniperus californica), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Bladderpod (Peritoma arborea), Antelope Brush (Purshia stansburyana), Desert Sage (Salvia dorrii), Mojave Sage (Salvia mohavensis), Jojoba (Simmondsia chinensis), and various cactus species. Also can be used with various other desert annuals or herbaceous perennials.', 'Creosote Bush Scrub, Joshua Tree Woodland', 'Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Lupinus-odoratus-%28Royal-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus odoratus var. odoratus', 'Mojave Lupine', 'Butterflies, Caterpillars', 'Blue, Purple, Lavender', 'Spring', 'Full Sun', 'Moderate', null, 'Creosote Bush Scrub, Joshua Tree Woodland', '<p>Prefers sun.</p>', null, 'https://calscape.org/Lupinus-odoratus-var.-odoratus-%28Mojave-Lupine%29');
