INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus polyphyllus', 'Meadow Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Blue, Lavender, Purple', 'Spring, Summer', 'Full Sun', 'High, Moderate', 'Use with other wetland plants such as Columbine (Aquilegia formosa or exima), Virgin''s Bower (Clematis ligusticifolia), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Sticky Cinquefoil (Drymocallis glandulosa), Stream Orchid (Epipactis gigantea), Gum Plant (<a href="/search/?plant=Grindelia%20(Genus)">Grindelia spp.</a>), Ocean Spray (Holodiscus discolor), Iris species, Leopard Lily (Lilium pardalinum), Scarlet Monkeyflower (Erythranthe cardinalis), Seep Monkeyflower (Erythranthe guttata), Evening Primrose (Oenothera elata), California Buttercup (Ranunculus californicus), Bee Plant (Scrophularia californica), Triteleia species, and Viola species.', 'Meadows, Red Fir Forest, Wetland-Riparian', 'Requires moist soil. Prefers sun.', null, 'https://calscape.org/Lupinus-polyphyllus-%28Meadow-Lupine%29');
