INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus sparsiflorus', 'Coulter''s Lupine', 'Bees, Birds, Butterflies, Caterpillars', 'Blue, Purple', 'Spring', 'Full Sun', 'Moderate', 'Can be used with a wide variety of coastal and inland shrubs, perennials and annuals, such as Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a> or <a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a>), Chaparral Yucca (Hesperoyucca whipplei), Chuparosa (Justicia californica), Mohave Yucca (Yucca shidigera), and various cactus species.', 'Chaparral, Coastal Sage Scrub, Creosote Bush Scrub', 'Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Lupinus-sparsiflorus-%28Coulter%27s-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus sparsiflorus ssp. inopinatus', 'Coulter''s Lupine', 'Butterflies, Caterpillars', 'Blue, Lavender, Purple', 'Spring', 'Full Sun', 'Moderate', null, 'Chaparral, Coastal Sage Scrub, Creosote Bush Scrub', 'Prefers sun.', null, 'https://calscape.org/Lupinus-sparsiflorus-ssp.-inopinatus-%28Coulter%27s-Lupine%29');
