INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lysimachia europaea', 'Arctic Starflower', 'Butterflies, Caterpillars', 'White', null, 'Full Sun', 'High', null, 'Freshwater Marsh, Northern Coastal Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Lysimachia-europaea-%28Arctic-Starflower%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus succulentus', 'Succulent Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Blue, Lavender, White', 'Spring, Winter', 'Full Sun, Partial Shade', 'Moderate', '<p>Works with a wide variety of other plants as long as soil and moisture are compatible, such as Coast Live Oak (Quercus agrifolia), Bay Laurel (Umbellularia californica), Madrone (Arbutus menziesii), California Peony (Paeonia californica), Yerba Buena (Clinopodium douglasii), Ocean Spray (Holodiscus discolor), Snowberry (Symphoricarpos mollis), Miners Lettuce (Claytonia perfiolata), and Canyon Sunflower (Venegasia carpesioides).</p>', 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest', '<p>Prefers part shade.</p>', null, 'https://calscape.org/Lupinus-succulentus-%28Succulent-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus succulentus ''Rodeo Rose''', 'Rodeo Rose Arroyo Lupine', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Pink', 'Spring', 'Full Sun, Partial Shade', 'Moderate', '<p>Works with a wide variety of other plants as long as soil and moisture are compatible, such as Coast Live Oak (Quercus agrifolia), Bay Laurel (Umbellularia californica), Madrone (Arbutus menziesii), California Peony (Paeonia californica), Yerba Buena (Clinopodium douglasii), Ocean Spray (Holodiscus discolor), Snowberry (Symphoricarpos mollis, Miners Lettuce Claytonia perfiolata), and Canyon Sunflower (Venegasia carpesioides).</p>', null, null, null, 'https://calscape.org/Lupinus-succulentus-%27Rodeo-Rose%27-%28Rodeo-Rose-Arroyo-Lupine%29');
