INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus truncatus', 'Collared Annual Lupine', 'Bees, Birds, Butterflies, Caterpillars', 'Lavender, Purple, Pink', 'Winter, Spring', 'Full Sun, Partial Shade', 'Moderate', 'Use with other annuals or perennial herbs such as <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, California Poppy (Eschscholzia californica), and Tidy Tips (Layia platyglossa)', 'Chaparral, Coastal Sage Scrub, Valley Grassland', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Lupinus-truncatus-%28Collared-Annual-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lupinus uncialis', 'Lilliput Lupine', 'Bees', 'Blue, Lavender, Purple', null, null, 'Moderate', null, null, null, null, 'https://calscape.org/Lupinus-uncialis-%28Lilliput-Lupine%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lycopus americanus', 'American Water Horehound', null, 'White', 'Summer', 'Partial Shade', null, null, 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 5.2-7.8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Lycopus americanus is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers part shade.', null, 'https://calscape.org/Lycopus-americanus-%28American-Water-Horehound%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Lycopus asper', 'Rough Bugleweed', null, 'White', 'Summer', null, null, null, 'Alpine Fell-Fields, Chaparral, Foothill Woodland, Wetland-Riparian', null, null, 'https://calscape.org/Lycopus-asper-%28Rough-Bugleweed%29');
