INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Machaeranthera tanacetifolia', 'Tanseyleaf Tansyaster', 'Bees, Butterflies', 'Purple', 'Spring', 'Full Sun, Partial Shade', null, null, 'Woodland', 'Plant in loamy soils that are at least 8 inches deep, with a pH of 6.5-8.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Machaeranthera tanacetifolia is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 24 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes sandy soils.', null, 'https://calscape.org/Machaeranthera-tanacetifolia-%28Tanseyleaf-Tansyaster%29');
