INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Maianthemum dilatatum', 'False Lily Of The Vally', 'Butterflies, Caterpillars', 'White', 'Spring', 'Deep Shade, Partial Shade', 'High, Moderate', 'This plant is best used in a damp shade garden with similar plants such as <a href="/search/?plant=Heuchera%20(Genus)">Heuchera spp.</a>, ferns, Meadow Rue (<a href="/search/?plant=Thalictrum%20(Genus)">Thalictrum spp.</a>), Western Dichondra (Dichondra occidentalis), Wild Ginger (<a href="/search/?plant=Asarum%20(Genus)">Asarum spp.</a>), and Brook Foam (Boykinia occidentalis)', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Forest, Wetland-Riparian', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Maianthemum-dilatatum-%28False-Lily-Of-The-Vally%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Maianthemum racemosum ssp. amplexicaule', 'Large False Solomon''s Seal', 'Butterflies, Caterpillars', 'White', 'Spring, Summer', 'Partial Shade', 'Moderate', null, 'Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers part shade.', null, 'https://calscape.org/Maianthemum-racemosum-ssp.-amplexicaule-%28Large-False-Solomon%27s-Seal%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Maianthemum stellatum', 'False Solomon Seal', 'Butterflies, Caterpillars', 'White, Red', 'Spring', 'Deep Shade, Partial Shade', 'Moderate', 'Use in a shaded woodland garden with various tree species, native ferns, Wild Ginger (Asarum caudatum), and other shade-loving plants. Also goes well with columbine, foamflower, ferns, and baneberries. Plant along paths with bleeding hearts.', 'Chaparral, Foothill Woodland, Mixed Evergreen Forest, Red Fir Forest, Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers part shade.', null, 'https://calscape.org/Maianthemum-stellatum-%28False-Solomon-Seal%29');
