INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Maurandella antirrhiniflora', 'Roving Sailor', 'Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun', null, null, 'Creosote Bush Scrub, Joshua Tree Woodland', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 6.8-9. It is intolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Maurandella antirrhiniflora is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate shade well. Prefers sun.', null, 'https://calscape.org/Maurandella-antirrhiniflora-%28Roving-Sailor%29');
