INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mentha arvensis', 'Field Mint', 'Bats, Butterflies, Caterpillars', 'White, Pink, Purple', 'Spring', 'Full Sun', 'Low, Moderate', null, 'Wetland-Riparian', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 5-7. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Mentha arvensis is only slightly drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Mentha-arvensis-%28Field-Mint%29');
