INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mentzelia lindleyi', 'Lindley''s Blazing Star', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', 'Very Low', 'Use in open areas between trees or shrubs such as Madrone (Arbutus menziesii), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Coffeeberry (<a href="/search/?plant=Frangula%20(Genus)">Frangula spp.</a>), Silktassel bush (Garrya), White Pitcher Sage (Lepechinia calycina), Mallow (<a href="/search/?plant=Malacothamnus%20(Genus)">Malacothamnus spp.</a>), Bush Monkeyflower (Diplacus aurantiacus), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Currant/Gooseberry (<a href="/search/?plant=Ribes%20(Genus)">Ribes spp.</a>), and Nightshades (<a href="/search/?plant=Solanum%20(Genus)">Solanum spp.</a>)<br/><br/><br><br>Works well in a wildflower meadow garden with other annuals or perennials such as Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Poppies (<a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a> or <a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a>), Owl''s Clover (Castilleja exserta), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia sp,), <a href="/search/?plant=Gilia%20(Genus)">Gilia spp.</a>, and many others', 'Coastal Sage Scrub, Escaped Cultivar, Foothill Woodland', 'Requires fast draining soil. Prefers sun or part shade. Likes rocky slopes.', null, 'https://calscape.org/Mentzelia-lindleyi-%28Lindley%27s-Blazing-Star%29');
