INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Menyanthes trifoliata', 'Buckbean', null, 'White', 'Spring', 'Full Sun', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 4.8-6.5. It is tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Menyanthes trifoliata is not drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Menyanthes-trifoliata-%28Buckbean%29');
