INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Microseris nutans', 'Perennial Nodding Microseris', null, 'Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', 'Plant in loamy soils that are at least 10 inches deep, with a pH of 6-7.2. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Microseris nutans is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun or part shade. Likes moist rocky soils.', null, 'https://calscape.org/Microseris-nutans-%28Perennial-Nodding-Microseris%29');
