INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis laevis', 'Desert Wishbone-bush', 'Bats, Butterflies, Caterpillars', 'Purple, Lavender, White', 'Spring, Winter', 'Full Sun, Partial Shade', 'Very Low', '<p>Has many companions depending on location and setting, including Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Coyote Brush (Baccharis pilularis), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Tree Poppy (Dendromecon rigida), Flannelbush (<a href="/search/?plant=Fremontodendron%20(Genus)">Fremontodendron spp.</a>), Toyon (Heteromeles arbutifolia), California Juniper (Juniperus californica), Hollyleaf Cherry (Prunus ilicifolia), and Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>)</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland', '<p>Prefers sun, part shade.</p>', null, 'https://calscape.org/Mirabilis-laevis-%28Desert-Wishbone-bush%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Monardella exilis', 'Mojave Monardella', 'Bees, Butterflies, Caterpillars', 'Purple, White, Green', null, null, null, null, 'Joshua Tree Woodland', null, null, 'https://calscape.org/Monardella-exilis-%28Mojave-Monardella%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis laevis var. crassifolia', 'California Four O''clock', 'Bats, Butterflies, Caterpillars', 'Lavender, Pink, Purple', 'Winter, Spring', 'Full Sun, Partial Shade', 'Low, Very Low', 'Works well with most chaparral and coastal sage scrub plants such as tree or scrub Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Toyon (Heteromeles arbutifolia), Lemonade Berry (Rhus integrifolia), Black Elderberry (Sambuccus nigra), Manzanita species and Ceanothus species.', 'Chaparral, Coastal Sage Scrub, Foothill Woodland', 'Requires fast draining soil. Prefers sun.', null, 'https://calscape.org/Mirabilis-laevis-var.-crassifolia-%28California-Four-O%27clock%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis laevis var. retrorsa', 'Bigelow Four O''clock', 'Butterflies, Caterpillars', 'White', null, null, null, null, null, null, null, 'https://calscape.org/Mirabilis-laevis-var.-retrorsa-%28Bigelow-Four-O%27clock%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis laevis var. villosa', 'Wishbone Bush', 'Butterflies, Caterpillars', 'White, Purple', 'Winter, Spring', 'Full Sun', 'Low, Very Low', 'Use with various other desert plants such as Desert Agave (Agave deserti), Cholla Cactus (<a href="/search/?plant=Cylindropuntia%20(Genus)">Cylindropuntia spp.</a>), Brittlebush (Encelia farinosa), Barrel Cactus (Ferocactus cylindraceus), Chuparosa (Justicia californica), and Joshua Tree (Yucca brevifolia)', 'Creosote Bush Scrub, Pinyon-Juniper Woodland', 'Prefers sun. Likes rocky soils.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as every other week.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Mirabilis-laevis-var.-villosa-%28Wishbone-Bush%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis multiflora', 'Colorado Four O''clock', 'Bats, Butterflies, Caterpillars', 'Purple', 'Spring, Summer', 'Full Sun', 'Low', null, null, 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6.5-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Mirabilis multiflora is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate shade well. Prefers sun. Likes dry rocky soils.', null, 'https://calscape.org/Mirabilis-multiflora-%28Colorado-Four-O%27clock%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis multiflora var. glandulosa', 'Giant Four O''clock', 'Butterflies, Caterpillars', 'Pink', null, null, 'Low', null, null, null, null, 'https://calscape.org/Mirabilis-multiflora-var.-glandulosa-%28Giant-Four-O%27clock%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Mirabilis multiflora var. pubescens', 'Desert Four O''clock', 'Butterflies, Caterpillars', 'Pink', null, 'Full Sun', 'Low', null, 'Creosote Bush Scrub, Pinyon-Juniper Woodland', 'Prefers sun. Likes dry rocky and sandy soils.', null, 'https://calscape.org/Mirabilis-multiflora-var.-pubescens-%28Desert-Four-O%27clock%29');
