INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Monardella macrantha', 'Red Monardella', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red', 'Summer, Fall', 'Full Sun, Partial Shade', 'Low, Moderate', 'Use in the understory of various southern California trees and shrubs including Serviceberry (<a href="/search/?plant=Amelanchier%20(Genus)">Amelanchier spp.</a>), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), along with other perennial herbs such as Goldenrod (<a href="/search/?plant=Solidago%20(Genus)">Solidago spp.</a>), Yarrow (Achillea millfolium), Mule Ears (Wyethia ovata), and native grasses.', 'Chaparral, Yellow Pine Forest', 'Prefers sun or part shade.This plant is not particularly drought tolerant.  It likes summer water every 2-4 weeks.', null, 'https://calscape.org/Monardella-macrantha-%28Red-Monardella%29');
