INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Monardella viminea', 'Willowy Monardella', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Pink, Lavender', 'Summer', 'Full Sun, Partial Shade', 'Low', '<p>Willowy mint commonly grows side-by-side with California buckwheat (Eriogonum fasciculatum), California fuchsia (Epilobium canum), broom baccharis (Baccharis sarothroides), narrowleaf milkweed (Aslepias fascicularis), and poison oak (Toxicodendron diversilobum). Nearby chaparral shrubs include toyon (Heteromeles arbutifolia), mountain mahogany (Cercocarpus minutiflorus), hollyleaf cherry (Prunus ilicifolia), scrub oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), and California sagebrush (Artemisia californica).</p>', 'Chaparral, Coastal Sage Scrub', '<p>Prefers sun or part shade. Likes sandy soils. This plant is not particularly drought tolerant. It likes summer water every 2-4 weeks.</p>', null, 'https://calscape.org/Monardella-viminea-%28Willowy-Monardella%29');
