INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nemophila maculata', 'Fivespot', 'Bats, Bees, Butterflies, Caterpillars', 'White, Blue, Purple', 'Spring, Winter', 'Full Sun, Partial Shade, Deep Shade', 'Low', 'This species works very well with other annual or herbaceous perennial wildflowers in a meadow garden, including the closely related Baby Blue Eyes (Nemophila menziesii), California Poppy (Eschscholzia californica), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Chinese Houses (Collinsia heterophylla), <a href="/search/?plant=Gilia%20(Genus)">Gilia spp.</a>, <a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>, <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, <a href="/search/?plant=Phacelia%20(Genus)">Phacelia spp.</a>, and many others. Also works well with geophytes such as <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>) and <a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a>, as well as various catcus and succulent species such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>', 'Foothill Woodland, Red Fir Forest, Valley Grassland, Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 6.5-7.9. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Nemophila maculata is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 24 inches of water per year once established. Prefers moist soil. It is very tolerant of shade. Grows well in sun, shade or part shade.', null, 'https://calscape.org/Nemophila-maculata-%28Fivespot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nemophila menziesii', 'Baby Blue Eyes', 'Bats, Butterflies, Caterpillars', 'Blue', 'Spring', 'Full Sun, Partial Shade', 'Low', 'Use with other wildflowers such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, and <a href="/search/?plant=Sidalcea%20(Genus)">Sidalcea spp.</a>, with geophytes such as <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>, Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), and Blue Dicks (Dichelostemma capitatum), and with succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a> and various cactus species.', 'Chaparral, Coastal Sage Scrub, Creosote Bush Scrub, Foothill Woodland, Joshua Tree Woodland, Mixed Evergreen Forest, Northern Coastal Scrub, Northern Oak Woodland, Forest, Southern Oak Woodland, Valley Grassland, Yellow Pine Forest', 'Prefers sun or part shade. Likes moist soils.', null, 'https://calscape.org/Nemophila-menziesii-%28Baby-Blue-Eyes%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nemophila menziesii ''Pennie Black''', 'Pennie Black Baby Blue Eyes', 'Bats, Butterflies, Caterpillars', 'Black, White', 'Spring', 'Full Sun, Partial Shade', 'Low', null, null, null, null, 'https://calscape.org/Nemophila-menziesii-%27Pennie-Black%27-%28Pennie-Black-Baby-Blue-Eyes%29');
