INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nolina bigelovii', 'Bigelow''s Nolina', 'Butterflies, Caterpillars', 'White', 'Spring', 'Full Sun', 'Low, Very Low', 'Use with other attractive desert plants such as Desert Agave (Agave deserti), Big Sagebrush (Artemisia tridentata), Desert Lavender (Condea emoryi), Brittlebush (Encelia farinosa), Apache Plume (Fallugia paradoxa), Ocotillo (Fouquieria splendens), <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>, Chuparosa (Justicia californica), Smoketree (Psorothamnus spinosus), Apricot Mallow (Sphaeralcea ambigua), and various cactus and succulent species', 'Creosote Bush Scrub', 'Requires fast draining soil. Prefers sun. Likes rocky slopes.', null, 'https://calscape.org/Nolina-bigelovii-%28Bigelow%27s-Nolina%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nolina parryi', 'Parry''s Nolina', 'Butterflies, Caterpillars', 'Cream, White', 'Spring', 'Full Sun', 'Very Low, Low', '<p>In desert settings, Joshua Tree, Apricot Mallow, Desert Brittlebush, Creosote Bush, Desert Agave, California Juniper, Pinyon Pine and Rush Milkweed. In chaparral settings, San Diego Viguiera, California Buckwheat (ssp. polifolium), <a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>, and Ceanothus species.</p>', 'Chaparral, Coastal Sage Scrub, Joshua Tree Woodland, Pinyon-Juniper Woodland', '<p>Requires fast draining soil. Prefers sun. Likes dry slopes. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Nolina-parryi-%28Parry%27s-Nolina%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Nothocalais alpestris', 'Alpine Lake False-dandelion', null, 'Yellow', null, null, null, null, 'Alpine Fell-Fields, Lodgepole Forest, Subalpine Forest', null, null, 'https://calscape.org/Nothocalais-alpestris-%28Alpine-Lake-False-dandelion%29');
