INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera avita', 'California Primrose', 'Bats, Butterflies, Caterpillars', 'White, Pink', 'Spring', 'Full Sun, Partial Shade', 'Low, Very Low', 'Use with Agave deserti or utahensis, Bigberry Manzanita (Arctostaphylos glauca), Big Sagebrush (Artemisia tridentata), Desert Marigold (Baileya multiradiata or pleniradiata), Desert Ceanothus (Ceanothus greggii), Goldenbush (<a href="/search/?plant=Ericameria%20(Genus)">Ericameria spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Apache Plume (Fallugia paradoxa), Yucca (Hesperoyucca whipplei or Yucca schidigera or Y. baccata), Joshua Tree (Yucca brevifolia), Beargrass (Nolina parryi), Beardtongue (<a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a>), Sage (Salvia Dorrii or mohavensis), Apricot Mallow (Sphaeralcea ambigua)', 'Chaparral, Coastal Sage Scrub, Joshua Tree Woodland, Southern Oak Woodland', 'Prefers sun or part shade. Likes sandy or gravelly soils.', null, 'https://calscape.org/Oenothera-avita-%28California-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera avita ssp. avita', 'California Evening-primrose', 'Butterflies, Caterpillars', 'White, Pink', null, null, 'Low, Very Low', null, null, null, null, 'https://calscape.org/Oenothera-avita-ssp.-avita-%28California-Evening-primrose%29');
