INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera cespitosa', 'Fragrant Evening Primrose', 'Bats, Butterflies, Caterpillars', 'White', 'Summer, Fall', 'Full Sun, Partial Shade', 'Extremely Low, Very Low', null, 'Bristlecone Pine Forest, Pinyon-Juniper Woodland, Shadscale Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6.5-8. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Oenothera caespitosa is extremely drought tolerant. It requires a minimum of 7 inches of water per year, and a maximum of 69 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes sandy dry soils.', null, 'https://calscape.org/Oenothera-cespitosa-%28Fragrant-Evening-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera cespitosa ssp. crinita', 'Cespitose Evening-primrose', 'Butterflies, Caterpillars', 'White', null, null, null, null, null, null, null, 'https://calscape.org/Oenothera-cespitosa-ssp.-crinita-%28Cespitose-Evening-primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera deltoides', 'Dune Primrose', 'Butterflies, Caterpillars', 'White, Pink', 'Spring, Summer, Fall', 'Full Sun', 'Extremely Low, Very Low', null, 'Creosote Bush Scrub, Joshua Tree Woodland, Sagebrush Scrub, Valley Grassland', 'Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Oenothera-deltoides-%28Dune-Primrose%29');
