INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera deltoides ssp. piperi', 'Piper''s Evening Primrose', 'Butterflies, Caterpillars', 'Yellow', null, null, null, null, null, null, null, 'https://calscape.org/Oenothera-deltoides-ssp.-piperi-%28Piper%27s-Evening-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera elata', 'Hooker''s Evening Primrose', 'Bats, Butterflies, Caterpillars', 'Orange, Yellow', 'Summer, Fall', 'Full Sun, Partial Shade', 'Low', '<p>Can be used with virtually any native plant. In a wet garden setting, use with Seep Monkeyflower (Erythranthe guttata), Scarlet Monkeyflower (Erythranthe cardinalis), Stream Orchid (Epipactis gigantea), Yerba Mansa (Anemopsis californica), Hedgenettle (Stachys bullata), and with trees including Willow (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), and Cottonwood (Populus fremontii or P. trichocarpa)</p>', 'Coastal Strand, Disturbed Places, Freshwater Marsh, Lakes and Ponds, Mixed Evergreen Forest, Northern Coastal Scrub, Wetland-Riparian', '<p>Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 5.5-7.5. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Oenothera elata is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 25 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. This plant is tough and fairly easy to grow. It''s very drought tolerant. After established, it should survive the dry months with no supplementary water. It''s also very garden tolerant, and can handle weekly watering without much trouble.</p>', null, 'https://calscape.org/Oenothera-elata-%28Hooker%27s-Evening-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera elata ssp. hirsutissima', 'Hairy Evening Primrose', 'Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'Low', null, 'Wetland-Riparian', 'Requires moist soil. Prefers sun.', null, 'https://calscape.org/Oenothera-elata-ssp.-hirsutissima-%28Hairy-Evening-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Olsynium douglasii', 'Douglas'' Grasswidow', null, 'Purple', null, 'Partial Shade', null, null, 'Foothill Woodland, Northern Juniper Woodland, Northern Oak Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Prefers part shade.', null, 'https://calscape.org/Olsynium-douglasii-%28Douglas%27-Grasswidow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera elata ssp. hookeri', 'Hooker''s Evening Primrose', 'Bats, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Partial Shade, Full Sun', 'Low', 'Hooker''s primrose can reseed vigorously, so be aware when planting it nearby other flowering plants. Taller plants, however, can out-compete. Consider using White Brodeiaea (Triteleia hyacinthina) or the Pitkin Marsh Lily (Lilium pardalinum ssp. pitkinense).', 'Chaparral, Coastal Sage Scrub, Coastal Strand, Foothill Woodland, Lodgepole Forest, Mixed Evergreen Forest, Northern Coastal Scrub, Red Fir Forest, Forest, Sagebrush Scrub, Southern Oak Woodland, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 7-8.5. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Oenothera elata ssp. hookeri is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 15 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers part shade.', 'Host to the bacteria Xylella fastidiosa.', 'https://calscape.org/Oenothera-elata-ssp.-hookeri-%28Hooker%27s-Evening-Primrose%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oenothera flava', 'Yellow Evening Primrose', 'Butterflies, Caterpillars', 'Yellow', 'Spring', null, null, null, 'Northern Juniper Woodland, Sagebrush Scrub, Wetland-Riparian', null, null, 'https://calscape.org/Oenothera-flava-%28Yellow-Evening-Primrose%29');
