INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Osmorhiza brachypoda', 'California Sweetcicely', 'Butterflies, Caterpillars', 'Yellow, Green', null, null, null, null, 'Foothill Woodland, Red Fir Forest, Southern Oak Woodland, Yellow Pine Forest', null, null, 'https://calscape.org/Osmorhiza-brachypoda-%28California-Sweetcicely%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Osmorhiza depauperata', 'Bluntseed Sweetroot', 'Butterflies, Caterpillars', 'White', 'Spring', 'Partial Shade', null, null, 'Yellow Pine Forest', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 5-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Osmorhiza depauperata is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 55 inches of water per year once established. It is very tolerant of shade. Prefers part shade.', null, 'https://calscape.org/Osmorhiza-depauperata-%28Bluntseed-Sweetroot%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Osmorhiza occidentalis', 'Mountain Sweet Cicely', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 16 inches deep, with a pH of 5.2-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Osmorhiza occidentalis is extremely drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 35 inches of water per year once established. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Osmorhiza-occidentalis-%28Mountain-Sweet-Cicely%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Osmorhiza purpurea', 'Purple Sweetroot', 'Butterflies, Caterpillars', null, null, null, null, null, 'Redwood Forest, Wetland-Riparian', null, null, 'https://calscape.org/Osmorhiza-purpurea-%28Purple-Sweetroot%29');
