INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oxalis oregana', 'Redwood Sorrel', 'Bats, Butterflies, Caterpillars', 'Pink, White', 'Spring, Winter', 'Partial Shade', 'Moderate, High', '<p>Use with other shade and moisture loving forest plants such as Wild Ginger (Asarum caudatum), Redwood Violet (Viola sempervirens), Western Sword Fern (Polystichum munitum), Common Trillium (Trillium chloropetalum), and Fawn Lily (<a href="/search/?plant=Erythronium%20(Genus)">Erythronium spp.</a>).</p>', 'Douglas-Fir Forest, Redwood Forest', '<p>Requires moist soil. Prefers part shade.</p>', null, 'https://calscape.org/Oxalis-oregana-%28Redwood-Sorrel%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Oxalis oregana ''Klamath Ruby''', 'Klamath Ruby Redwood Sorrel', 'Bats, Butterflies, Caterpillars', 'White, Pink', 'Spring, Summer', 'Partial Shade', 'High, Moderate', null, null, null, null, 'https://calscape.org/Oxalis-oregana-%27Klamath-Ruby%27-%28Klamath-Ruby-Redwood-Sorrel%29');
