INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Paeonia brownii', 'Western Paeony', null, 'Red, Purple', 'Spring', 'Full Sun, Partial Shade', 'Moderate', null, 'Chaparral, Sagebrush Scrub, Yellow Pine Forest', 'Plant in loamy soils that are at least 10 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Paeonia brownii is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 24 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade.', null, 'https://calscape.org/Paeonia-brownii-%28Western-Paeony%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Paeonia californica', 'California Peony', null, 'Purple, Red', 'Winter, Spring', 'Partial Shade, Full Sun', 'Moderate', 'Use with other chaparral and sage scrub species that tolerate dry summer conditions, such as Eastwood Manzanita (Artcostaphylos glandulosa), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Flannelbush (<a href="/search/?plant=Fremontodendron%20(Genus)">Fremontodendron spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), California Fuchsia (Epilobium canum), Scrub Oak (Quercus berberidifolia or dumosa), Woolly Bluecurls (Trichostema lanatum), succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a> and various cactus species.', 'Chaparral, Coastal Sage Scrub', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Paeonia-californica-%28California-Peony%29');
