INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Papaver heterophyllum', 'Windpoppy', 'Butterflies, Caterpillars', 'Orange, Red', 'Spring', 'Partial Shade', 'Very Low', 'Various Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Toyon (Heteromeles arbutifolia), Lemonade Berry (Rhus integrifolia), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, native grasses and geophytes such as Blue Dicks (Dichelostemma capitatum)', 'Chaparral, Foothill Woodland, Northern Oak Woodland, Southern Oak Woodland, Valley Grassland', 'Requires fast draining soil. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Papaver-heterophyllum-%28Windpoppy%29');
