INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon anguineus', 'Siskiyou Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Purple, Blue', null, 'Partial Shade', null, null, 'Douglas-Fir Forest, Mixed Evergreen Forest, North Coastal Coniferous Forest, Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers part shade.', null, 'https://calscape.org/Penstemon-anguineus-%28Siskiyou-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon azureus', 'Azure Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Green, Purple, Lavender, Blue', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Moderate, High', null, 'Chaparral, Foothill Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Requires moist soil. Prefers sun or part shade.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Penstemon-azureus-%28Azure-Penstemon%29');
