INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon calcareus', 'Limestone Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red, Pink, Purple', null, 'Full Sun, Partial Shade', null, null, 'Creosote Bush Scrub, Joshua Tree Woodland, Pinyon-Juniper Woodland', 'Prefers sun or part shade. Likes rocky slopes and rock crevices.', null, 'https://calscape.org/Penstemon-calcareus-%28Limestone-Beardtongue%29');
