INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon centranthifolius', 'Scarlet Bugler', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Red', 'Summer, Spring', 'Full Sun, Partial Shade', 'Low', '<p>Many companion plants including: Chamise (Adenostema fasciculatum), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Ceanothus species, Bush Poppy (Dendromecon rigida), Sugarbush (Rhus ovata), Hollyleaf Cherry (Prunus ilicifolia), Bladderpod (Peritoma arborea), Mountain Mahogany (<a href="/search/?plant=Cercocarpus%20(Genus)">Cercocarpus spp.</a>), Sages (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), California fuchsia (Epilobium canum), Yucca (<a href="/search/?plant=Hesperoyucca%20(Genus)">Hesperoyucca spp.</a> and <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>), succulents such as <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, and various cactus species</p>', 'Chaparral, Oak Woodland', '<p>Requires fast draining soil. Prefers sun or part shade. This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils. It can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.</p>', null, 'https://calscape.org/Penstemon-centranthifolius-%28Scarlet-Bugler%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon cinereus', 'Gray Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Blue', 'Spring, Summer', 'Full Sun, Partial Shade', null, null, 'Northern Juniper Woodland, Sagebrush Scrub', 'Prefers sun, part shade.', null, 'https://calscape.org/Penstemon-cinereus-%28Gray-Beardtongue%29');
