INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon clevelandii', 'Cleveland''s Beardtongue', 'Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Pink', 'Spring', 'Full Sun, Partial Shade', 'Low', 'Use with other plants of hot inland valleys or desert transition, including Indian Mallow (Abutilon palmeri), Copperleaf (Acalypha californica), Desert Agave (Agave deserti), Big Sagebrush (Artemisia tridentata), Manzanita (Arctostaphylos spl.), Parish''s Viguiera (Bahiopsis parishii), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Creosote Bush (Larrea tridentata), Joshua Tree (Yucca brevifolia) and various cactus species', 'Chaparral, Creosote Bush Scrub, Joshua Tree Woodland', 'Prefers sun or part shade. Likes rocky slopes and rock crevices.', null, 'https://calscape.org/Penstemon-clevelandii-%28Cleveland%27s-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon clevelandii var. clevelandii', 'Cleveland''s Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-clevelandii-var.-clevelandii-%28Cleveland%27s-Beardtongue%29');
