INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon davidsonii var. davidsonii', 'Davidson''s Penstemon', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Purple', null, 'Deep Shade', null, null, 'Alpine Fell-Fields, Subalpine Forest', 'Requires fast draining soil. Prefers shade. Likes talus crevices.', null, 'https://calscape.org/Penstemon-davidsonii-var.-davidsonii-%28Davidson%27s-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon deustus', 'Scabland Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Yellow, Cream', 'Spring', 'Full Sun, Partial Shade', 'Very Low', null, 'Northern Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Penstemon deustus is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 18 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes rocky soils.', null, 'https://calscape.org/Penstemon-deustus-%28Scabland-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon deustus var. deustus', 'Scabland Penstemon', 'Butterflies, Caterpillars', null, null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-deustus-var.-deustus-%28Scabland-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon deustus var. pedicellatus', 'Hot Rock Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red', null, 'Full Sun', null, null, null, 'Prefers sun. Likes Rocky volcanic soils.', null, 'https://calscape.org/Penstemon-deustus-var.-pedicellatus-%28Hot-Rock-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon deustus var. suffrutescens', 'Scabland Penstemon', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'White', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-deustus-var.-suffrutescens-%28Scabland-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon eatonii', 'Firecracker Penstemon', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Red, Yellow', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low', '<p>Use with other high-desert plants such as Big Sagebrush (Artemisia tridentata), Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Apache Plume (Fallugia paradoxa), Juniper (<a href="/search/?plant=Juniperus%20(Genus)">Juniperus spp.</a>), Pinyon Pine (Pinus monophylla),</p><p>Desert Scrub Oak (Quercus cornelius-mulleri), Desert Sage (Salvia dorrii), and Joshua Tree (Yucca brevifolia).</p>', 'Creosote Bush Scrub, Pinyon-Juniper Woodland', '<p>Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 7-8. It is intolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Penstemon eatonii is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 20 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade.</p>', null, 'https://calscape.org/Penstemon-eatonii-%28Firecracker-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon eatonii var. eatonii', 'Eaton''s Penstemon', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-eatonii-var.-eatonii-%28Eaton%27s-Penstemon%29');
