INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon heterophyllus', 'Foothill Penstemon', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Blue, Purple, Lavender', 'Summer, Spring, Winter', 'Full Sun, Partial Shade', 'Very Low', '<p>Shrubs and Trees: Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Toyon (Heteromeles arbutifolia), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Lemonade Berry (Rhus integrifolia), <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a></p><p><br></p><p>Herbs: California Sagebrush (Artemisia californica), California Buckwheat (Eriogonum fasciculatum), California Encelia (Encelia californica), Sticky Monkeyflower (Diplacus aurantiacus), and Scarlet Bugler (Penstemon centranthifolius)</p>', 'Chaparral, Foothill Woodland, Southern Oak Woodland, Yellow Pine Forest', '<p>Prefers sun or part shade.</p>', null, 'https://calscape.org/Penstemon-heterophyllus-%28Foothill-Penstemon%29');
