INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon heterophyllus var. australis', 'Southern Foothill Penstemon', 'Bats, Bees, Butterflies, Hummingbirds, Caterpillars', 'Blue', null, null, null, null, null, 'This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Penstemon-heterophyllus-var.-australis-%28Southern-Foothill-Penstemon%29');
