INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon labrosus', 'San Gabriel Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Red, Yellow, Orange', 'Summer', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Penstemon-labrosus-%28San-Gabriel-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon laetus', 'Mountain Blue Penstemon', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Blue, Lavender, Purple, White', 'Spring', 'Full Sun, Partial Shade', null, 'Use with mountain species such as Bush Chinquapin (Chrysolepis sempervirens), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Bitter Cherry (Prunus emarginata), Western Labrador Team (Rhododendron columbianum), and Creeping Snowberry (Symphoricarpos mollis)', 'Chaparral, Foothill Woodland, Red Fir Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6-7.6. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Penstemon laetus is extremely drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 20 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes spring-moist soils.', null, 'https://calscape.org/Penstemon-laetus-%28Mountain-Blue-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon laetus var. laetus', 'Mountain Blue Penstemon', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Blue, Purple', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-laetus-var.-laetus-%28Mountain-Blue-Penstemon%29');
