INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon newberryi', 'Mountain Pride', 'Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Red, Pink', 'Spring', 'Partial Shade', 'Very Low', 'Sulphur Buckwheat (Eriogonum umbellatum),Common Woolly Sunflower (Eriophyllum lanatum), Antelope Bitterbrush (Purshia tridentata), Pinemat Manzanita (Arctostaphylos nevadensis), Wright''s Buckwheat (Eriogonum wrightii var subscaposum)', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 19 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Penstemon newberryi is extremely drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 36 inches of water per year once established. It is moderately tolerant of full shade. Prefers part shade.', null, 'https://calscape.org/Penstemon-newberryi-%28Mountain-Pride%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon newberryi var. berryi', 'Berry''s Mountain Pride', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Purple', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-newberryi-var.-berryi-%28Berry%27s-Mountain-Pride%29');
