INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon palmeri', 'Palmer''s Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Purple, Blue, Pink', 'Spring', 'Full Sun, Partial Shade', 'Low, Very Low', 'Use with other high desert plants such as Joshua Tree (Yucca brevifolia), Pinyon Pine (Pinus edulis or monophylla), Utah Agave (Agave utahensis), Bigberry Manzanity (Arctostaphylos glauca), Big Sagebrush (Artemisia tridentata), Desert Ceanothus (Ceanothus greggii), Desert Willow (Chilpsis linearis), Mormon Tea (<a href="/search/?plant=Ephedra%20(Genus)">Ephedra spp.</a>), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Apache Plume (Fallugia paradoxa), Chaparral Yucca (Hesperoyucca whipplei), California Juniper (Juniperus californica), Bladderpod (Peritoma arborea), Antelope Brush (Purshia tridentata), Sage (Salvia dorrii or mohavensis), Jojoba (Simmondsia chinensis), Banana Yucca (Yucca baccata), and various cactus species.', 'Joshua Tree Woodland, Pinyon-Juniper Woodland', 'Prefers sun or part shade. Likes sandy soils .  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Penstemon-palmeri-%28Palmer%27s-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon palmeri ''Hybrid''', 'Penstemon Hybrid', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Pink', 'Spring', 'Full Sun, Partial Shade', 'Low, Very Low', null, null, null, null, 'https://calscape.org/Penstemon-palmeri-%27Hybrid%27-%28Penstemon-Hybrid%29');
