INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon procerus var. brachyanthus', 'Small Flowered Penstemon', 'Butterflies, Caterpillars', null, null, 'Full Sun', null, null, 'Wetland-Riparian', '<p>Requires moist soil. Prefers sun.</p>', null, 'https://calscape.org/Penstemon-procerus-var.-brachyanthus-%28Small-Flowered-Penstemon%29');
