INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon pseudospectabilis', 'Desert Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Pink, Red', 'Spring', 'Full Sun', 'Very Low', 'Can be used with a variety of native plants including many not found in its native range, such as Manzanitas (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), California Poppy (Eschscholzia californica), <a href="/search/?plant=Dudleya%20(Genus)">Dudleya spp.</a>, and various cactus species.', 'Creosote Bush Scrub', 'Requires fast draining soil. Prefers sun. Likes gravelly or rocky desert soils.', null, 'https://calscape.org/Penstemon-pseudospectabilis-%28Desert-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon purpusii', 'Snow Mountain Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Pink, Purple, Blue', null, 'Full Sun, Partial Shade', null, null, 'Red Fir Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade. Likes rocky slopes.', null, 'https://calscape.org/Penstemon-purpusii-%28Snow-Mountain-Beardtongue%29');
