INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon rupicola', 'Rock Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Pink, Purple', null, 'Deep Shade, Partial Shade', null, null, 'Red Fir Forest', 'Requires fast draining soil. Prefers shade. Likes rocky slopes.', null, 'https://calscape.org/Penstemon-rupicola-%28Rock-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon rydbergii', 'Rydberg''s Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Blue, Lavender, Purple', 'Summer', 'Full Sun, Partial Shade', 'Moderate, High', 'Use in a mountain meadow garden with native grasses and perennials such as Sitka Columbine (Aquilegia formosa), Sierra Mariposa Lily (Calochortus minimus), Roundleaf Sundew (Drosera rotundifolia), Western Blue Flag (Iris missouriensis), Alpine Lily (Lilium parvum), Bog Orchid (Platanthera sparsiflora), Buttercup (<a href="/search/?plant=Ranunculus%20(Genus)">Ranunculus spp.</a>), <a href="/search/?plant=Triteleia%20(Genus)">Triteleia spp.</a>, and Violet (<a href="/search/?plant=Viola%20(Genus)">Viola spp.</a>)', 'Lodgepole Forest, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 14 inches deep, with a pH of 6-8. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Penstemon rydbergii is only slightly drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 30 inches of water per year once established. Requires fast draining soil. It does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Penstemon-rydbergii-%28Rydberg%27s-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon rydbergii var. oreocharis', 'Mountain Meadow Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Pink', null, 'Full Sun, Partial Shade', null, null, 'Wetland-Riparian', 'Requires fast draining soil. Prefers sun or part shade. Likes moist soils.', null, 'https://calscape.org/Penstemon-rydbergii-var.-oreocharis-%28Mountain-Meadow-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon scapoides', 'Pinyon Beardtongue', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'Purple, Green, Lavender', null, null, null, null, null, null, null, 'https://calscape.org/Penstemon-scapoides-%28Pinyon-Beardtongue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon speciosus', 'Royal Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Blue, Lavender, Purple', 'Summer, Spring', 'Full Sun, Partial Shade', 'Very Low', 'Trees - Joshua Tree (Yucca brevifolia), Pinyon Pine (Pinus monophylla), Juniper (<a href="/search/?plant=Juniperus%20(Genus)">Juniperus spp.</a>), Red Fir (Abies magnifica), Ponderosa Pine (Pinus ponderosa)<br/>Shrubs and herbs - Big Sagebrush (Artemisia tridentata), Sulphur Buckwheat (Eriogonum umbellatum), Blue Flax (Linum lewisii), Scarlet Gilia (Ipomopsis aggregata), and Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>)', 'Joshua Tree Woodland, Pinyon-Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 14 inches deep, with a pH of 6.4-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile and clay rich soils. It requires a minimum of 8 inches of water per year, and a maximum of 24 inches of water per year once established. Requires fast draining soil and does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Penstemon-speciosus-%28Royal-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon x parishii ''Magenta Marvel''', 'Magenta Marvel Hybrid Penstemon', null, 'Red', 'Spring, Summer', 'Full Sun', 'Low', null, null, null, null, 'https://calscape.org/Penstemon-x-parishii-%27Magenta-Marvel%27-%28Magenta-Marvel-Hybrid-Penstemon%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Penstemon spectabilis', 'Showy Penstemon', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Blue, Pink, Purple', 'Spring, Winter', 'Full Sun', 'Very Low', 'Sagebrush (Artemisia californica), San Diego Viguiera (Bahiopsis laciniata), California Encelia (Encelia californica), Buckwheat (Eriogonum fasciculatum), <a href="/search/?plant=Manzanita%20(Genus)">Manzanita spp.</a>, scrub oaks, and various annuals such as California Poppy.', 'Chaparral, Coastal Sage Scrub', 'Prefers sun or part shade. Likes gravelly or sandy slopes, dry creek beds, and sandy soils. Will tolerate clay soils. After established, it should survive the dry months with no supplementary water. It''s moderately sensitive to pathogens that grow in warm moist soils, but can usually handle summer watering as much as once per month. If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.<br/>', null, 'https://calscape.org/Penstemon-spectabilis-%28Showy-Penstemon%29');
