INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Perideridia gairdneri', 'Gairdner''s Yampah', 'Butterflies, Caterpillars', 'White', 'Spring', 'Full Sun', null, null, 'Wetland-Riparian', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 6-7.5. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Perideridia gairdneri is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 24 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Perideridia-gairdneri-%28Gairdner%27s-Yampah%29');
