INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Perityle emoryi', 'Emory''s Rockdaisy', null, 'White, Yellow', 'Winter, Spring', 'Full Sun', 'Low', 'Most effective with other desert plants such as Desert Agave (Agave deserti), Barrel Cactus (Ferocactus cylindraceus), Arizona Chalk Dudleya (Dudleya arizonica), Brittle Bush (Encelia farinosa), Fish Hook Cactus (Mammillaria dioica), Chia (Salvia columbariae), and Mojave Yucca (Yucca shidigera)', 'Coastal Sage Scrub, Creosote Bush Scrub', 'Prefers sun. Likes sandy soils .', null, 'https://calscape.org/Perityle-emoryi-%28Emory%27s-Rockdaisy%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Persicaria amphibia', 'Swamp Knotweed', 'Butterflies, Caterpillars', 'Yellow', null, 'Partial Shade', null, null, 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 4-7. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Polygonum amphibium is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers part shade. Likes wet places.', null, 'https://calscape.org/Persicaria-amphibia-%28Swamp-Knotweed%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Persicaria hydropiperoides', 'Water Pepper', 'Butterflies, Caterpillars', 'Green', null, 'Full Sun', null, null, 'Wetland-Riparian', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 4.5-8.8. It is tolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Polygonum hydropiperoides is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes wet stream banks.', null, 'https://calscape.org/Persicaria-hydropiperoides-%28Water-Pepper%29-2');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Persicaria lapathifolia', 'Willow Weed', 'Butterflies, Caterpillars', 'Pink', null, null, null, null, 'Wetland-Riparian', null, null, 'https://calscape.org/Persicaria-lapathifolia-%28Willow-Weed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Persicaria punctata', 'Water Smartweed', 'Butterflies, Caterpillars', 'White', null, 'Full Sun', null, null, 'Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 14 inches deep, with a pH of 6-8.7. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Polygonum punctatum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes shallow water shores.', null, 'https://calscape.org/Persicaria-punctata-%28Water-Smartweed%29-2');
