INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia californica', 'California Phacelia', 'Bats, Bees, Butterflies, Caterpillars', 'Lavender, White', 'Summer, Spring', 'Full Sun, Partial Shade', 'Low, Moderate', '<p>Blue Eyed Grass (Sisyrinchium bellum), Foothill Penstemon (Penstemon heterophyllus), Checker Bloom (Sidalcea malviflora), Blue Dicks (Dichelostemma capitatum), California Goldenrod (Solidago velutina ssp. californica), Pearly Everlasting (Anaphalis margaritacea)</p>', 'Chaparral, Northern Coastal Scrub', '<p>Requires fast draining soil. Prefers sun or part shade. Likes slopes.</p>', null, 'https://calscape.org/Phacelia-californica-%28Rock-Phacelia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia calthifolia', 'Caltha Leafed Phacelia', 'Bees, Butterflies, Caterpillars', 'Purple', null, 'Full Sun', null, null, 'Creosote Bush Scrub, Joshua Tree Woodland', 'Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Phacelia-calthifolia-%28Caltha-Leafed-Phacelia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia campanularia', 'Desertbells', 'Bats, Bees, Butterflies, Caterpillars', 'Blue, Purple', 'Winter, Spring', 'Full Sun', 'Low', '<p>Creosote Bush (Larrea tridentata), Ocotillo (Fouquieria splendens ssp. splendens), Jojoba (Simmondsia chinensis), Blue Paloverde, White Bursage (Ambrosia dumosa), Chuparosa (Justicia californica), Barrel Cactus, Desert Lavender (Condea emoryi), Indigo Bush, Apricot Mallow (Sphaeralcea ambigua var. rugosa), <a href="/search/?plant=Opuntia%20(Genus)">Opuntia spp.</a>, numerous annual wildflowers</p>', 'Creosote Bush Scrub, Joshua Tree Woodland', '<p>Prefers sun. Likes sandy or gravelly soils.</p>', null, 'https://calscape.org/Phacelia-campanularia-%28Desertbells%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia campanularia var. campanularia', 'Desertbells', 'Bees, Butterflies, Caterpillars', 'Blue', null, null, null, null, null, null, null, 'https://calscape.org/Phacelia-campanularia-var.-campanularia-%28Desertbells%29');
