INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia distans', 'Wild Heliotrope', 'Bees, Butterflies, Caterpillars', 'Purple, Lavender', 'Spring', 'Full Sun', 'Very Low', 'Use with regionally appropriate annual wildflowers and perennial shrubs including Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, California Poppy (Eschscholzia californica), Ocotillo (Fouquieria splendens), Creosote Bush (Larrea tridentata), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Joshua Tree (Yucca brevifolia), and a variety of cactus and succulent speciess', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Valley Grassland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun. Likes clay or rocky slopes.', null, 'https://calscape.org/Phacelia-distans-%28Wild-Heliotrope%29');
