INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia grandiflora', 'Large Flowered Phacelia', 'Bees, Butterflies, Caterpillars', 'Blue, Lavender, Purple', 'Winter, Spring', 'Full Sun', 'Low', 'Chamise (Adenostem fasciculatum), San Diego County Viguiera (Bahiopsis laciniata), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), Coastal Sagebrush (Artemisia californica), Coyote Brush (Baccharis pilularis), Ceanothus species, Common Sandaster (Corethrogyne filaginifolia), Dudleya species, California Fuchsia (Epilobium canum), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Mexican Flannelbush (Fremontodendron mexicanum), Tecate Cypress (Hesperocyparis forbesii), Lupinus species, Penstemon species, Bladderpod (Peritoma arborea), Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), Matilija Poppy (Romneya coulteri), White Sage (Salvia apiana), Woolly Bluecurls (Trichostema lanatum), Yucca species, cactus species, as well as other annuals such as California Poppy (Eschscholzia californica).', 'Chaparral, Coastal Sage Scrub', 'Requires fast draining soil. Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Phacelia-grandiflora-%28Large-Flowered-Phacelia%29');
