INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia hastata', 'Phacelia', 'Bees, Butterflies, Caterpillars', 'White', 'Spring', 'Full Sun, Partial Shade', null, null, 'Northern Juniper Woodland, Red Fir Forest, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 6.1-7.3. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Phacelia hastata is extremely drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 18 inches of water per year once established. It is moderately tolerant of full shade. Prefers sun or part shade. Likes flats and slopes and talus.', null, 'https://calscape.org/Phacelia-hastata-%28Phacelia%29');
