INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia minor', 'California Bluebell', 'Bees, Butterflies, Caterpillars', 'Blue, Lavender', 'Spring', 'Full Sun', 'Very Low', '<p>Use as part of an open wildflower area with a wide variety of shrubs and subshrubs, as well as other annuals. Examples include Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Brittlebush (<a href="/search/?plant=Encelia%20(Genus)">Encelia spp.</a>), Chuparosa (Justicia californica), Jojoba (Simmondsia chinensis), Desert Sand Verbena (Abronia villosa), Thistle Sage (Salvia carduacea), Chia (Salvia columbariae), and <a href="/search/?plant=Penstemon%20(Genus)">Penstemon spp.</a></p>', 'Chaparral, Coastal Sage Scrub, Creosote Bush Scrub', '<p>Prefers sun. Likes slopes.</p>', null, 'https://calscape.org/Phacelia-minor-%28California-Bluebell%29');
