INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia tanacetifolia', 'Lacy Phacelia', 'Bats, Bees, Butterflies, Caterpillars', 'Blue', 'Spring', 'Full Sun', 'Very Low', 'Use for spaces between chaparral shrubs along with other annuals or perennial herbs such as Poppy (<a href="/search/?plant=Eschscholzia%20(Genus)">Eschscholzia spp.</a> or <a href="/search/?plant=Papaver%20(Genus)">Papaver spp.</a>), Baby Blue Eyes (Nemophila menziesii), Cream Cups (Platystemon californicus), and with geophytes such as Onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), and Blue Dicks (Dichelostemma capitatum). Also useful around various cacti and succulents such as Dudleya spp.', 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 6.4-8.6. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Phacelia tanacetifolia is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 18 inches of water per year once established. Requires fast draining soil. It does not tolerate shade well. Prefers sun. Likes sandy or gravelly slopes.', null, 'https://calscape.org/Phacelia-tanacetifolia-%28Lacy-Phacelia%29');
