INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phacelia viscida', 'Sticky Phacelia', 'Bees, Butterflies, Caterpillars', 'Blue', 'Spring', 'Full Sun', 'Very Low', 'Numerous companion plants including Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), Giant Wild Rye (Elymus condensatus), Sand Aster (Corethrogyne filaginifolia), Sagebrush (Artemisia californica), Monkeyflower (<a href="/search/?plant=Mimulus%20(Genus)">Mimulus spp.</a>), Encelia californica, Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Heartleaf Keckiella (Keckiella cordifolia), Penstemon species, Salvia species, Blue-eyed Grass (Sisyrinchium bellum)', 'Chaparral, Coastal Sage Scrub', 'Requires fast draining soil. Prefers sun. Likes sandy soils.', null, 'https://calscape.org/Phacelia-viscida-%28Sticky-Phacelia%29');
