INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Phlox diffusa', 'Spreading Phlox', 'Butterflies, Caterpillars', 'Purple, White', 'Spring', 'Full Sun', null, null, 'Alpine Fell-Fields, Douglas-Fir Forest, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 15 inches deep, with a pH of 6.5-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Phlox diffusa is extremely drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 40 inches of water per year once established. Requires fast draining soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Phlox-diffusa-%28Spreading-Phlox%29');
