INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Plantago patagonica', 'Woolly Plantain', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', null, null, 'Chaparral, Joshua Tree Woodland, Pinyon-Juniper Woodland, Shadscale Scrub', 'Plant in sandy, loamy or clay soils that are at least 6 inches deep, with a pH of 6.4-9. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Plantago patagonica is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It does not tolerate full shade well. Prefers sun or part shade. Likes sandy or rocky slopes.', null, 'https://calscape.org/Plantago-patagonica-%28Woolly-Plantain%29');
