INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Potentilla glaucophylla', 'Varileaf Cinquefoil', 'Butterflies, Caterpillars', 'Yellow', null, 'Full Sun', null, null, 'Alpine Fell-Fields, Lodgepole Forest, Subalpine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 7-8. It is moderately tolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Potentilla diversifolia is only slightly drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 35 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Potentilla-glaucophylla-%28Varileaf-Cinquefoil%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Potentilla glaucophylla var. glaucophylla', 'Blueleaf Cinquefoil', 'Butterflies, Caterpillars', null, null, null, null, null, 'Alpine Fell-Fields, Lodgepole Forest, Subalpine Forest, Wetland-Riparian', null, null, 'https://calscape.org/Potentilla-glaucophylla-var.-glaucophylla-%28Blueleaf-Cinquefoil%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Potentilla gracilis', 'Slender Cinquefoil', 'Bats, Butterflies, Caterpillars', 'Yellow', 'Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Coastal Prairie, Lodgepole Forest, Mixed Evergreen Forest, Northern Oak Woodland, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 4 inches deep, with a pH of 4-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Potentilla gracilis is moderately drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 80 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Potentilla-gracilis-%28Slender-Cinquefoil%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Potentilla gracilis var. elmeri', null, 'Butterflies, Caterpillars', null, null, null, 'Moderate', null, 'Pinyon-Juniper Woodland, Wetland-Riparian, Yellow Pine Forest', null, null, 'https://calscape.org/Potentilla-gracilis-var.-elmeri-%28%29');
