INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Primula pauciflora', 'Dark Throated Shooting Star', 'Butterflies, Caterpillars', null, null, 'Full Sun', null, null, 'Sagebrush Scrub, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 8 inches deep, with a pH of 6-7.8. It is tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Dodecatheon pulchellum is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 30 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun. Likes wet meadows.', null, 'https://calscape.org/Primula-pauciflora-%28Dark-Throated-Shooting-Star%29');
