INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Prunella vulgaris', 'Common Selfheal', null, 'Purple, Pink', 'Summer', 'Full Sun, Partial Shade', 'Moderate', 'Ocean spray (Holodiscus discolor), willows (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), Pacific Ninebark (Physocarpus capitatus), Blue wildrye (Elymus glaucus).', 'Weed (disturbed places), Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 5.4-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Prunella vulgaris is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun.', 'Selfheal is generally impervious to most pests, but beware of predation by slugs and snails on young plants.', 'https://calscape.org/Prunella-vulgaris-%28Common-Selfheal%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Prunella vulgaris var. lanceolata', 'Lance Leaf Self Heal', null, 'Purple', 'Summer', 'Full Sun, Partial Shade', 'Moderate', null, 'Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Prunella-vulgaris-var.-lanceolata-%28Lance-Leaf-Self-Heal%29');
