INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Pseudognaphalium biolettii', 'Bicolored Everlasting', 'Bees, Butterflies, Caterpillars', 'Cream, White', 'Winter, Spring', 'Full Sun', null, null, 'Chaparral, Coastal Sage Scrub, Mixed Evergreen Forest', '<p>Limited or no summer water once established, requires fast draining soil. Prefers sun.</p>', null, 'https://calscape.org/Pseudognaphalium-biolettii-%28Bicolored-Everlasting%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Pseudognaphalium californicum', 'California Cudweed', 'Bats, Bees, Butterflies, Caterpillars', 'Cream, White, Green', 'Winter, Spring, Summer', 'Full Sun', 'Very Low, Low', 'Works with a wide variety of other plants. In the wild it is often found with other pioneer species such as Lotus (<a href="/search/?plant=Acmispon%20(Genus)">Acmispon spp.</a>), native grasses, and wildflowers such as California Poppy (Eschscholzia californica).', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Mixed Evergreen Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun. Likes dry slopes.', null, 'https://calscape.org/Pseudognaphalium-californicum-%28California-Cudweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Pseudognaphalium canescens', 'Wright''s Cudweed', 'Bees, Butterflies, Caterpillars', 'White, Cream, Yellow, Brown', 'Summer, Fall', 'Full Sun', 'Very Low, Low', null, null, null, null, 'https://calscape.org/Pseudognaphalium-canescens-%28Wright%27s-Cudweed%29');
