INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ranunculus californicus', 'California Buttercup', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Winter', 'Full Sun, Partial Shade', 'Very Low', '<p>Dodecatheon clevelandii (shooting star), Sisyrinchium bellum (blue-eyed grass), Trichostema lancolatum (wooly blue-curls)</p>', 'Foothill Woodland, Mixed Evergreen Forest, Northern Coastal Scrub, Northern Oak Woodland, Red Fir Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Requires fast draining soil. Prefers shade or part shade on a north-facing slope. Goes deciduous in summer. Grows in a variety of soils including clay/serpentine.</p>', null, 'https://calscape.org/Ranunculus-californicus-%28California-Buttercup%29');
