INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ranunculus cymbalaria', 'Desert Buttercup', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun', 'Moderate', null, 'Alpine Fell-Fields, Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 9 inches deep, with a pH of 6.5-8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Ranunculus cymbalaria is only slightly drought tolerant. It requires a minimum of 12 inches of water per year, and a maximum of 48 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Ranunculus-cymbalaria-%28Desert-Buttercup%29');
