INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Ranunculus glaberrimus', 'Smooth Buttercup', 'Butterflies, Caterpillars', 'Yellow', 'Spring', 'Full Sun, Partial Shade', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Sagebrush Scrub, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy soils that are at least 6 inches deep, with a pH of 6-7.5. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Ranunculus glaberrimus is only slightly drought tolerant. It requires a minimum of 35 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Ranunculus-glaberrimus-%28Smooth-Buttercup%29');
