INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Romneya coulteri', 'Coulter''s Matilija Poppy', 'Butterflies, Caterpillars', 'Yellow, White', 'Summer, Spring', 'Full Sun', 'Very Low, Low', '<p>Grows well with a wide variety of chaparral plants including Scrub Oaks, Manzanitas, Coyote Brush (Baccharis pilularis ssp. pilularis), Laurel Sumac (Malosma laurina), Chaparral Mallow (Malacothamnus fasciculatus), Toyon (Heteromeles arbutifolia), and Lemonade Berry</p>', 'Chaparral, Coastal Scrub, Lowland Chaparral, Southern Coastal Scrub', '<p>Limited or no summer water once established, requires fast draining soil. Prefers sun. Likes dry sandy soils and slopes. This plant is not particularly drought tolerant. It likes summer water every 4 weeks.</p>', null, 'https://calscape.org/Romneya-coulteri-%28Coulter%27s-Matilija-Poppy%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Romneya trichocalyx', 'Bristly Matilija Poppy', 'Butterflies, Caterpillars', 'White, Yellow', 'Spring, Summer', 'Full Sun', 'Very Low', 'Grows well with a variety of chaparral plants including Scrub Oaks, Manzanitas, Coyote Brush (Baccharis pilularis ssp. pilularis), Laurel Sumac (Malosma laurina), Chaparral Mallow (Malacothamnus fasciculatus), Toyon and Lemonade Berry', 'Chaparral, Coastal Sage Scrub, Lowland Chaparral, Southern Coastal Scrub', 'Limited or no summer water once established, requires fast draining soil. Prefers sun. Likes dry sandy soils and slopes.  This plant is extremely drought tolerant. After established, it should survive the dry months with no supplementary water.  It''s moderately sensitive to pathogens that grow in warm moist soils.  It can usually handle summer watering as much as once per month.  If you do water during the summer, make sure you do it in the very early morning, and during a stretch of cooler days in the summer season.', null, 'https://calscape.org/Romneya-trichocalyx-%28Bristly-Matilija-Poppy%29');
