INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Rubus parviflorus', 'Thimbleberry', 'Bats, Butterflies, Caterpillars', 'White, Yellow', 'Spring', 'Partial Shade', 'Low, Moderate', 'Use with trees from its native range, such as Fir (<a href="/search/?plant=Abies%20(Genus)">Abies spp.</a>), Pine (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), and Redwood (Sequoia sempervirens)', 'Closed-cone Pine Forest, Mixed Evergreen Forest, Red Fir Forest, Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 4.8-7.2. It is intolerant of anaerobic soils, tolerant of calcareous soils, and requires only moderately fertile soils. Rubus parviflorus is moderately drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 45 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade.', 'Prune in winter to control height and/or spread', 'https://calscape.org/Rubus-parviflorus-%28Thimbleberry%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Rudbeckia californica', 'California Coneflower', 'Butterflies, Caterpillars', 'Green, Yellow', 'Summer', 'Partial Shade', 'Low, Moderate, High', 'Other wet loving plants such as Lilium pardalinum, Western Azalea (Rhododendron occidentale), Green Alder (Alnus viridis)', 'Douglas-Fir Forest, North Coastal Coniferous Forest, Red Fir Forest, Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. Prefers part shade.', 'Susceptible to leaf spots (remove infected leaves) and aster yellow (remove and destroy infected plants).', 'https://calscape.org/Rudbeckia-californica-%28California-Coneflower%29');
