INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sagittaria latifolia', 'Wappato', null, 'Yellow', 'Spring', 'Full Sun', null, null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 18 inches deep, with a pH of 4.7-8.9. It is tolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Sagittaria latifolia is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 50 inches of water per year once established. Prefers moist soil. It does not tolerate shade well. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Sagittaria-latifolia-%28Wappato%29');
