INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salicornia pacifica', 'Pickleweed', 'Butterflies, Caterpillars', 'Red', 'Summer, Fall', 'Full Sun', 'Moderate, High', null, 'Coastal Salt Marsh, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes saline or alkaline soils.  This plant needs plenty of water throughout the year.  Water 1-2 times per week.', null, 'https://calscape.org/Salicornia-pacifica-%28Pickleweed%29');
