INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia carduacea', 'Thistle Sage', 'Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Blue', 'Spring', 'Full Sun', 'Very Low', 'Use with Saltbush (<a href="/search/?plant=Atriplex%20(Genus)">Atriplex spp.</a>), Brittlebush (Encelia farinosa or actonii), Buckwheat (<a href="/search/?plant=Eriogonum%20(Genus)">Eriogonum spp.</a>), Lupine (<a href="/search/?plant=Lupinus%20(Genus)">Lupinus spp.</a>), Chuparosa (Justicia californica), Bladderpod (Peritoma arborea), and various cactus and succulent species. Also can be mixed with other annuals herbs.', 'Coastal Sage Scrub, Creosote Bush Scrub, Valley Grassland', 'Requires fast draining soil. Prefers sun. Likes sandy or gravelly soils.', null, 'https://calscape.org/Salvia-carduacea-%28Thistle-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia cedrosensis ''Baja Blanca''', 'Baja Blanca Cedros Island Sage', null, 'White', 'Spring', 'Full Sun', 'Moderate, Very Low', null, null, null, null, 'https://calscape.org/Salvia-cedrosensis-%27Baja-Blanca%27-%28Baja-Blanca-Cedros-Island-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia columbariae', 'Chia', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Blue, Purple', 'Spring', 'Full Sun', 'Extremely Low, Very Low', '<p>Works with many other annual and perennial plants depending on locations within the state. Near the coast it can be used with coastal sage scrub and chaparral plants. In mountainous areas it can be used in openings of woodlands and montane chaparral. In the central valley and arid areas it can be used in open, sandy gardens with any desert plants.</p>', 'Chaparral, Creosote Bush Scrub, Foothill Woodland', '<p>Limited or no summer water once established, requires fast draining soil. Prefers sun. Likes dry slopes.</p>', null, 'https://calscape.org/Salvia-columbariae-%28Chia%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia sonomensis', 'Sonoma Sage', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Blue, Lavender, Purple, White', 'Spring, Summer', 'Full Sun, Partial Shade', 'Extremely Low, Very Low', 'Use with shrubs or trees from its native ranges, such as larger <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Toyon (Heteromeles arbutifolia), Scrub Oak (Quercus berberidifolia or dumosa), tree Oaks (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a>), and various Pines (Pinus ponderosa and others)', 'Chaparral, Northern Oak Woodland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade. Tolerates clay and serpentine. Likes dry slopes. It likes summer water every 4 weeks.', null, 'https://calscape.org/Salvia-sonomensis-%28Sonoma-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia vaseyi', 'Scallopleaf Sage', 'Bees, Butterflies, Hummingbirds, Caterpillars', 'White', null, null, null, null, 'Creosote Bush Scrub', null, null, 'https://calscape.org/Salvia-vaseyi-%28Scallopleaf-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Samolus parviflorus', 'Seaside Brookweed', null, null, null, null, null, null, 'Chaparral, Coastal Sage Scrub, Wetland-Riparian', null, null, 'https://calscape.org/Samolus-parviflorus-%28Seaside-Brookweed%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia spathacea', 'Hummingbird Sage', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Pink, Red', 'Winter, Spring, Summer', 'Deep Shade, Full Sun, Partial Shade', 'Very Low', '<p>It is often found under trees or large shrubs such as Coast Live Oak (Quercus agrifolia), Bay Laurel (Umbellularia californica) or Madrone (Arbutus menziesii). Companion understory plants include California Peony (Paeonia californica), Yerba Buena (Clinopodium douglasii), Ocean Spray (Holodiscus discolor), Snowberry (Symphoricarpos mollis, Miners Lettuce Claytonia perfiolata), and Canyon Sunflower (Venegasia carpesioides).</p>', 'Chaparral, Foothill Woodland, Northern Oak Woodland, Southern Oak Woodland', '<p>Tolerates clay and serpentine. In its native range it gets 20 to 35 inches of rainfall per year. After established, it should survive the dry months with little to no supplementary water. It''s fairly sensitive to pathogens that grow in warm moist soils, and will usually die if watered more than once per month. If you do water during the summer, do it in the very early morning, and during a stretch of cooler days.</p>', null, 'https://calscape.org/Salvia-spathacea-%28Hummingbird-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia spathacea ''Avis Keedy''', 'Avis Keedy Hummingbird Sage', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Yellow', 'Spring', 'Deep Shade, Full Sun, Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Salvia-spathacea-%27Avis-Keedy%27-%28Avis-Keedy-Hummingbird-Sage%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Salvia spathacea ''Cerro Alto''', 'Cerro Alto Hummingbird Sage', 'Bats, Bees, Birds, Butterflies, Hummingbirds, Caterpillars', 'Yellow, Pink', 'Spring', 'Deep Shade, Full Sun, Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Salvia-spathacea-%27Cerro-Alto%27-%28Cerro-Alto-Hummingbird-Sage%29');
