INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sidalcea neomexicana', 'Salt Spring Checkerbloom', 'Birds, Butterflies, Caterpillars', 'Purple, Pink', 'Spring', 'Full Sun', 'Moderate', null, 'Alkali Sink, Chaparral, Coastal Sage Scrub, Creosote Bush Scrub, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 12 inches deep, with a pH of 6.2-7.8. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Sidalcea neomexicana is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 28 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Sidalcea-neomexicana-%28Salt-Spring-Checkerbloom%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Spergularia canadensis var. occidentalis', 'Western Sand-spurrey', null, null, null, null, null, null, null, null, null, 'https://calscape.org/Spergularia-canadensis-var.-occidentalis-%28Western-Sand-spurrey%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sidalcea oregana', 'Oregon Checker Mallow', 'Birds, Butterflies, Caterpillars', 'Purple, Pink, Red', 'Spring', 'Partial Shade', 'Moderate', null, 'Freshwater Marsh, Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Forest, Sagebrush Scrub, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 6.4-8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Sidalcea oregana is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 28 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers part shade. Likes wet soils.', null, 'https://calscape.org/Sidalcea-oregana-%28Oregon-Checker-Mallow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sidalcea oregana ssp. eximia', 'Coast Checkerbloom', 'Butterflies, Caterpillars', 'Pink', null, null, 'Moderate', null, null, null, null, 'https://calscape.org/Sidalcea-oregana-ssp.-eximia-%28Coast-Checkerbloom%29');
