INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Silene laciniata', 'Cardinal Catchfly', 'Butterflies, Hummingbirds, Caterpillars', 'Red', 'Spring, Summer', 'Partial Shade', 'Low, Moderate', 'Works well in a woodland or rock garden with other low growing plants in part shade, such as Meadow Rue (Thalicturm species), Yerba Buena (Clinopodium douglasii), Western Columbine (Aquilegia formosa), Monkeyflower (Mimulus cardinalis or guttatus). Can be planted under larger shrubs and allowed to grow up through them.', 'Chaparral, Coastal Sage Scrub, Coastal Strand', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Silene-laciniata-%28Cardinal-Catchfly%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Silene laciniata ssp. californica', 'Cardinal Catchfly', 'Butterflies, Caterpillars', 'Red', 'Spring, Summer', 'Full Sun, Partial Shade', 'Low, Moderate', null, 'Chaparral, Mixed Evergreen Forest, Northern Coastal Scrub, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun or part shade.', null, 'https://calscape.org/Silene-laciniata-ssp.-californica-%28Cardinal-Catchfly%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Silene laciniata ssp. laciniata', 'Cardinal Catchfly', 'Butterflies, Caterpillars', 'Red, Pink', 'Summer, Spring', 'Full Sun', 'Low, Moderate', '<p>Chamise (Adenostoma fasciculatum var. fasciculatum), Woolly Bluecurls (Trichostema lanatum), White Sage (Salvia apiana), California Buckwheat (Eriogonum fasciculatum var. fasciculatum), California Coffeeberry (Frangula californica ssp. californica), Toyon (Heteromeles arbutifolia), Lemonade Berry (Rhus integrifolia), Coastal Prickly Pear Cactus, Manzanita species, <a href="/search/?plant=Yucca%20(Genus)">Yucca spp.</a>, various native grasses</p>', 'Chaparral', '<p>Requires fast draining soil. Prefers sun or part shade.</p>', null, 'https://calscape.org/Silene-laciniata-ssp.-laciniata-%28Cardinal-Catchfly%29-2');
