INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sisyrinchium bellum', 'Blue-eyed Grass', 'Butterflies', 'Blue, Purple, Lavender', 'Spring, Winter', 'Full Sun, Partial Shade', 'Low', '<p>Chamise (Adenostoma fasciculatum var. fasciculatum), California Buckwheat (Eriogonum fasciculatum var. fasciculatum), Lemonade Berry (Rhus integrifolia), Ponderosa Pine (Pinus ponderosa), Box Elder (Acer negundo), Bigleaf Maple, Pacific Madrone (Arbutus menziesii), Manzanita species, Artemisia species, native grass species, <a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>, <a href="/search/?plant=Allium%20(Genus)">Allium spp.</a></p>', 'Coastal Scrub, Foothill Woodland, Freshwater Marsh, Inland Closed-Cone Coniferous Forest, Lower Montane Coniferous Forest, Lowland Chaparral, Meadows, Montane Chaparral, Perennial Grassland--Remnant Non-desert Grassland, Riparian Woodland, Sagebrush', '<p>Blue eyed grass grows well in a wide variety of soils - clay, loam or sand. While it prefers moist soils, and meadows or grasslands with plenty of ground water. Once established, it can survive on as little as 8" of rain per year. It handles regular irrigation and seasonal flooding without a problem as well. It likes sun or part shade.</p>', null, 'https://calscape.org/Sisyrinchium-bellum-%28Blue-eyed-Grass%29');
