INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sisyrinchium californicum', 'Yellow Eyed Grass', null, 'Yellow', null, 'Full Sun, Partial Shade', 'Moderate', '<p>Glossyleaf Manzanita (Arctostaphylos nummularia), Thrift Seapink (Armeria maritima), Ceanothus species, Giant Chinquapin (Chrysolepis chrysophylla), Yerba Buena (Clinopodium douglasii), Woodland Strawberry (Fragraria vesca), Gowen Cypress (Hesperocyparis goveniana), Monterey Cypress (Hesperocyparis macrocarpa), Alumroot (<a href="/search/?plant=Heuchera%20(Genus)">Heuchera spp.</a>), Twinberry (Lonicera involucrata), Lodgepole Pine (Pinus contorta), Bishop Pine (Pinus muricata), Monterey Pine (Pinus radiata), Western Hemlock (Tsuga heterophylla), and California Huckleberry (Vaccinium ovatum).</p>', 'Freshwater Marsh, Wetland-Riparian', '<p>Requires moist soil and tolerates seasonal flooding. Prefers shade unless grown along coast ranges where it likes full sun. It likes summer water every other week.</p>', null, 'https://calscape.org/Sisyrinchium-californicum-%28Yellow-Eyed-Grass%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sisyrinchium californicum ''Yellow Stone''', 'Yellow Stone Yellow-eyed Grass', null, 'Yellow', 'Summer, Spring', 'Full Sun, Partial Shade', 'Moderate', null, null, null, null, 'https://calscape.org/Sisyrinchium-californicum-%27Yellow-Stone%27-%28Yellow-Stone-Yellow-eyed-Grass%29');
