INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sisyrinchium idahoense', 'Idaho Blue Eyed Grass', null, 'Blue, Yellow, Purple', 'Spring', 'Full Sun', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 8 inches deep, with a pH of 6.4-8.2. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Sisyrinchium idahoense is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 32 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Sisyrinchium-idahoense-%28Idaho-Blue-Eyed-Grass%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sisyrinchium idahoense var. idahoense', 'Idaho Blue Eyed Grass', null, null, null, 'Full Sun', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', '<p>Requires moist soil. Prefers sun.</p>', null, 'https://calscape.org/Sisyrinchium-idahoense-var.-idahoense-%28Idaho-Blue-Eyed-Grass%29');
