INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solanum umbelliferum var. wallacei', 'Catalina Nightshade', 'Birds, Butterflies, Caterpillars', 'Purple, Black', 'Spring, Summer', 'Deep Shade', 'Low', null, 'Chaparral, Foothill Woodland', 'Requires fast draining soil. Prefers shade. Likes slopes.  This plant is not particularly drought tolerant.  It likes summer water every 2-4 weeks.', null, 'https://calscape.org/Solanum-umbelliferum-var.-wallacei-%28Catalina-Nightshade%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solanum umbelliferum var. xanti', 'Purple Nightshade', 'Bats, Birds, Butterflies, Caterpillars', 'Blue, Purple', 'Winter, Spring, Summer', 'Full Sun, Partial Shade', 'Very Low', 'Best used in habitat restoration or "wild" gardens with shrubs such as Chamise (Adenostoma fasciculatum), Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a> or <a href="/search/?plant=Xylococcus%20(Genus)">Xylococcus spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Coyote Brush (Baccharis pilularis), Scrub Oak (Quercus dumosa or berberidifolia), and other woody plants.', 'Chaparral, Foothill Woodland, Lodgepole Forest, Northern Oak Woodland, Red Fir Forest, Southern Oak Woodland, Yellow Pine Forest', 'Requires fast draining soil, but is tolerant of clay. Prefers sun or part shade. It should get 10" to 20" of rainfall and does well when grown near leaf litter.', null, 'https://calscape.org/Solanum-umbelliferum-var.-xanti-%28Purple-Nightshade%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solanum xanti ''Mountain Pride''', 'Mountain Pride Blue Witch', 'Bats, Bees, Birds, Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun, Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Solanum-xanti-%27Mountain-Pride%27-%28Mountain-Pride-Blue-Witch%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solanum xanti ''Navajo Creek''', 'Navajo Creek Blue Witch', 'Bats, Birds, Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun, Partial Shade', 'Very Low', null, null, null, null, 'https://calscape.org/Solanum-xanti-%27Navajo-Creek%27-%28Navajo-Creek-Blue-Witch%29');
