INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago elongata', 'Canadian Goldenrod', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'Moderate', null, 'Chaparral, Coastal Prairie, Foothill Woodland, Valley Grassland, Yellow Pine Forest', 'Prefers moist soil. Prefers sun.', null, 'https://calscape.org/Solidago-elongata-%28Canadian-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago guiradonis', 'Guirado''s Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', null, null, null, null, null, null, null, 'https://calscape.org/Solidago-guiradonis-%28Guirado%27s-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago lepida', 'Canada Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Low', null, 'Chaparral, Coastal Prairie, Foothill Woodland, Valley Grassland, Yellow Pine Forest', 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 4.8-7.5. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Solidago canadensis is moderately drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Prefers moist soil. It does not tolerate shade well. Prefers sun.', null, 'https://calscape.org/Solidago-lepida-%28Canada-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago lepida var. salebrosa', 'Rough Canada Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', null, 'Partial Shade', null, null, 'Chaparral, Coastal Prairie, Foothill Woodland, Valley Grassland, Yellow Pine Forest', 'Prefers part shade.', null, 'https://calscape.org/Solidago-lepida-var.-salebrosa-%28Rough-Canada-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago multiradiata', 'Rocky Mountain Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun', 'Low', null, 'Alpine Fell-Fields, Lodgepole Forest, Subalpine Forest', 'Plant in sandy soils that are at least 12 inches deep, with a pH of 5-7.3. It is intolerant of anaerobic soils, , and requires only moderately fertile soils. Solidago multiradiata is only slightly drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 100 inches of water per year once established. Requires fast draining soil. It does not tolerate shade well. Prefers sun. Likes slopes and meadows.', null, 'https://calscape.org/Solidago-multiradiata-%28Rocky-Mountain-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago spathulata', 'Coast Goldenrod', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer, Fall', 'Full Sun', 'Extremely Low, Very Low', null, 'Coastal Strand, Northern Coastal Scrub', 'Requires fast draining soil. Prefers sun. Likes sandy soils .', null, 'https://calscape.org/Solidago-spathulata-%28Coast-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago spectabilis', 'Showy Goldenrod', 'Bees, Butterflies, Caterpillars', 'Yellow', null, 'Full Sun', null, null, 'Alkali Sink, Sagebrush Scrub, Shadscale Scrub, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes alkali soils.', null, 'https://calscape.org/Solidago-spectabilis-%28Showy-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago velutina', 'Threenerve Goldenrod', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', null, 'Low', 'Use with a wide variety of native plants, depending on region of the state and garden conditions.', null, null, null, 'https://calscape.org/Solidago-velutina-%28Threenerve-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago velutina ssp. californica', 'California Goldenrod', 'Bats, Bees, Butterflies, Caterpillars', 'Yellow', 'Summer, Fall', 'Full Sun, Partial Shade', 'Very Low, Low', '<p>Use with complementary flower colors such as Sages (<a href="/search/?plant=Salvia%20(Genus)">Salvia spp.</a>), Wild Rose (Rosa californica), Common Yarrow (Achillea millefolium), and Penstemon species</p>', 'Chaparral, Coastal Sage Scrub, Foothill Woodland, Lodgepole Forest, Northern Coastal Scrub, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', '<p>It likes summer water at least once per month, and at most twice per week. It does well when the soil is wet in March and drier in summer.</p>', null, 'https://calscape.org/Solidago-velutina-ssp.-californica-%28California-Goldenrod%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Solidago velutina ssp. sparsiflora', 'Great Basin Goldenrod', 'Bees, Butterflies, Caterpillars', null, null, 'Full Sun, Partial Shade', null, null, 'Woodland', 'Prefers sun or part shade.', null, 'https://calscape.org/Solidago-velutina-ssp.-sparsiflora-%28Great-Basin-Goldenrod%29');
