INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sparganium eurycarpum', 'Broadfruit Bur-reed', 'Butterflies, Caterpillars', 'Green', null, 'Full Sun', null, null, 'Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 12 inches deep, with a pH of 5-8.5. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Sparganium eurycarpum is not drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun. Likes wet soils.', null, 'https://calscape.org/Sparganium-eurycarpum-%28Broadfruit-Bur-reed%29');
