INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sphaeralcea grossulariifolia', 'Gooseberryleaf Globemallow', 'Bees, Butterflies, Caterpillars', 'Red, Orange', 'Spring, Summer, Fall', 'Full Sun', 'Low, Very Low', null, null, 'Plant in sandy or loamy soils that are at least 12 inches deep, with a pH of 5-7. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Sphaeralcea grossulariifolia is moderately drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 14 inches of water per year once established. It is moderately tolerant of shade. Prefers sun. Likes dry sandy soils.', null, 'https://calscape.org/Sphaeralcea-grossulariifolia-%28Gooseberryleaf-Globemallow%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Sphaeralcea munroana', 'Munro''s Globemallow', 'Bees, Butterflies, Caterpillars', 'Orange', 'Spring', 'Full Sun', 'Low, Very Low', null, null, 'Plant in sandy or loamy soils that are at least 16 inches deep, with a pH of 6.3-8. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Sphaeralcea munroana is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. Requires fast draining soil. It does not tolerate shade well. Prefers sun. Likes dry volcanic soils.', null, 'https://calscape.org/Sphaeralcea-munroana-%28Munro%27s-Globemallow%29');
