INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Stachys bullata', 'California Hedgenettle', 'Bats, Bees, Birds, Hummingbirds, Butterflies, Caterpillars', 'Lavender', 'Spring, Summer, Fall', 'Deep Shade, Partial Shade', 'Moderate, High', 'Use with other plants of wet areas including Willow (<a href="/search/?plant=Salix%20(Genus)">Salix spp.</a>), Cottonwood (<a href="/search/?plant=Populus%20(Genus)">Populus spp.</a>), Sycamore (Plataunus racemosa), Sedge (<a href="/search/?plant=Carex%20(Genus)">Carex spp.</a>), Rush (<a href="/search/?plant=Juncus%20(Genus)">Juncus spp.</a>), Monkeyflower (Mimulus cardinalis and guttatus), and Stream Orchid (Epipactis gigantea)', 'Chaparral, Coastal Sage Scrub, Mixed Evergreen Forest, Forest', 'Prefers shade. Likes wet swampy seepy soils.  This plant is not drought tolerant.  It likes summer water every 1-4 weeks.', null, 'https://calscape.org/Stachys-bullata-%28California-Hedgenettle%29');
