INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Tellima grandiflora', 'Bigflower Tellima', null, 'Pink, Red, White', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Moderate', 'Use under trees such as Coast Redwood (Sequoia sempervirens), Firs (<a href="/search/?plant=Abies%20(Genus)">Abies spp.</a>), Maples (<a href="/search/?plant=Acer%20(Genus)">Acer spp.</a>), Pines (<a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>), Bay Laurel (Umbellularia californica), Chinquapin (Chrysolepis chrysophylla or sempervirens), and Tanoak (Notholithocarpus densiflorus), along with other shade-loving and moisture loving plants such as native ferns, Elk''s Clover (Aralia californica), Wild Ginger (Asarum caudatum), Columbine (Aquilegia formosa), Chinese Houses (Collinsia heterophylla), Larkspur (<a href="/search/?plant=Delphinium%20(Genus)">Delphinium spp.</a>), Bleeding Heart (Dicentra formosa), Western Wallflower (Erysimum capitatum), and Tiger Lily (Lilium pardalinum)', 'Mixed Evergreen Forest, Forest, Yellow Pine Forest', 'Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Tellima-grandiflora-%28Bigflower-Tellima%29');
