INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Teucrium canadense', 'Canada Germander', null, 'Purple', 'Summer', null, null, null, null, 'Plant in loamy or clay soils that are at least 4 inches deep, with a pH of 4.5-8. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Teucrium canadense is only slightly drought tolerant. It requires a minimum of 20 inches of water per year, and a maximum of 60 inches of water per year once established. It is moderately tolerant of shade.', null, 'https://calscape.org/Teucrium-canadense-%28Canada-Germander%29');
