INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Thalictrum fendleri', 'Meadow Rue', 'Bats, Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Deep Shade, Partial Shade', 'Low', 'Trees: Red Fir (Abies magnifica), other <a href="/search/?plant=Abies%20(Genus)">Abies spp.</a> and <a href="/search/?plant=Pseudotsuga%20(Genus)">Pseudotsuga spp.</a>, Lodgepole Pine (Pinus contorta), Yellow Pine (Pinus ponderosa), other <a href="/search/?plant=Pinus%20(Genus)">Pinus spp.</a>, Quaking Aspen (Populus tremuloides), Maple (<a href="/search/?plant=Acer%20(Genus)">Acer spp.</a>), Incense Cedar (Calocedrus decurrens), Giant Chinquapin (Chrysolepis chrysophylla), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Oak (<a href="/search/?plant=Quercus%20(Genus)">Quercus spp.</a> and <a href="/search/?plant=Notholithocarpus%20(Genus)">Notholithocarpus spp.</a>), and Redwoods (Sequoia sempervirens and Sequoiadendron giganteum)<br><br>Other plants: Ferns (Adiantum spp., Asplenium spp., Athyrium spp., Blechnum spicant, Dryopteris spp., Pellaea spp., Pentagramma spp., Polypodium spp., Polystichum spp., Woodwardia fimbriata), Wild Ginger (Asarum caudatum), and <a href="/search/?plant=Trillium%20(Genus)">Trillium spp.</a>', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Thalictrum-fendleri-%28Meadow-Rue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Thalictrum fendleri var. fendleri', 'Fendler''s Meadow Rue', 'Butterflies, Caterpillars', null, null, 'Deep Shade, Partial Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Thalictrum-fendleri-var.-fendleri-%28Fendler%27s-Meadow-Rue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Thalictrum fendleri var. polycarpum', 'Torrey''s Meadow Rue', 'Butterflies, Caterpillars', 'Cream, Green, Yellow', 'Spring', 'Partial Shade', 'Moderate', 'Western Columbine (Aquilegia formosa), Coral Bells (<a href="/search/?plant=Heuchera%20(Genus)">Heuchera spp.</a>), Western Sword Fern (Polystichum munitum), Southern Maiden Hair fern (Adiantum capillus-veneris), Giant Chain Fern (Woodwardia fimbriata), Western Wild Ginger (Asarum caudatum)', 'Foothill Woodland, Mixed Evergreen Forest, Northern Oak Woodland, Southern Oak Woodland', 'Requires moist soil. Prefers shade.', null, 'https://calscape.org/Thalictrum-fendleri-var.-polycarpum-%28Torrey%27s-Meadow-Rue%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Thalictrum occidentale', 'Western Meadow Rue', 'Butterflies, Caterpillars', null, null, 'Partial Shade', null, null, 'Yellow Pine Forest, Wetland-Riparian', 'Requires moist soil. It grows in shady habitat types such as forest understories and more open, moist habitat such as meadows.', null, 'https://calscape.org/Thalictrum-occidentale-%28Western-Meadow-Rue%29');
