INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Trifolium macrocephalum', 'Big Headed Clover', 'Bees, Butterflies, Caterpillars', 'Purple', 'Spring', 'Full Sun', null, null, 'Northern Juniper Woodland, Sagebrush Scrub, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 6.2-7.1. It is tolerant of anaerobic soils, tolerant of calcareous soils, and tolerant of infertile soils. Trifolium macrocephalum is moderately drought tolerant. It requires a minimum of 10 inches of water per year, and a maximum of 20 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of shade. Prefers sun.', null, 'https://calscape.org/Trifolium-macrocephalum-%28Big-Headed-Clover%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Trifolium microcephalum', 'Maiden Clover', 'Bees, Butterflies, Caterpillars', 'Pink', 'Spring', 'Full Sun, Partial Shade', 'Very Low', null, 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest', 'Requires moist soil. Prefers sun or part shade. Likes rocky flats or slopes.', null, 'https://calscape.org/Trifolium-microcephalum-%28Maiden-Clover%29');
