INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Triteleia laxa', 'Ithuriel''s Spear', 'Bees, Butterflies', 'Blue, Lavender, Purple, White', 'Spring, Summer', 'Deep Shade, Partial Shade, Full Sun', 'Very Low', 'Best used with other geopytes such as wild onions (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Mariposa Lily (<a href="/search/?plant=Calochortus%20(Genus)">Calochortus spp.</a>), <a href="/search/?plant=Dichelostemma%20(Genus)">Dichelostemma spp.</a>, and <a href="/search/?plant=Brodiaea%20(Genus)">Brodiaea spp.</a>; also with annual wildflowers such as California Poppy (Eschscholzia californica), <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>, Baby Blue Eyes (Nemophila menziesii), and Chinese Houses (Collinsia heterophylla); and bunch grasses such as California Melic (Melica californica), Small-flowered Melic (Melica imperfecta), Purple-Needlegrass (Stipa pulchera), and Foothill Needlegrass (Stipa lepida).', 'Chaparral, Foothill Woodland, Mixed Evergreen Forest', 'Requires fast draining soil. Prefers sun or part shade. Likes sandy soils.', null, 'https://calscape.org/Triteleia-laxa-%28Ithuriel%27s-Spear%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Triteleia laxa ''4u''', '4u Ithuriel''s Spear', 'Bees, Butterflies', 'Pink, Lavender', 'Spring', 'Deep Shade, Partial Shade, Full Sun', 'Very Low', null, null, null, null, 'https://calscape.org/Triteleia-laxa-%274u%27-%284u-Ithuriel%27s-Spear%29');
