INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Typha angustifolia', 'Narrowleaf Cattail', 'Butterflies, Caterpillars', 'Green', 'Spring', 'Full Sun', null, null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 10 inches deep, with a pH of 3.7-8.5. It is tolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Typha angustifolia is only slightly drought tolerant. It requires a minimum of 30 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It does not tolerate shade well. Prefers sun. Likes dry granitic slopes .', null, 'https://calscape.org/Typha-angustifolia-%28Narrowleaf-Cattail%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Typha domingensis', 'Southern Cattail', 'Butterflies, Caterpillars', null, null, 'Full Sun', 'Moderate, High', null, 'Freshwater Marsh, Wetland-Riparian', 'Requires moist soil. Prefers sun. Likes wet soils.  This plant needs heavy water throughout the year.  Water 2x per week.', null, 'https://calscape.org/Typha-domingensis-%28Southern-Cattail%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Typha latifolia', 'Broadleaf Cattail', 'Bats, Butterflies, Caterpillars', 'Brown', 'Spring', 'Full Sun', 'Moderate, High', null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in sandy, loamy or clay soils that are at least 14 inches deep, with a pH of 5.5-8.7. It is tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Typha latifolia is not drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 180 inches of water per year once established. Requires moist soil. It is moderately tolerant of shade. Prefers sun. Likes wet soils.  This plant needs heavy water throughout the year.  Water 2x per week.', null, 'https://calscape.org/Typha-latifolia-%28Broadleaf-Cattail%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Uropappus lindleyi', 'Silverpuffs', null, null, null, 'Full Sun', null, null, 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest', '<p>Prefers sun. Likes slopes.</p>', null, 'https://calscape.org/Uropappus-lindleyi-%28Uropappus%29');
