INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Veratrum californicum', 'California False Hellebore', 'Butterflies, Caterpillars', 'White', 'Spring', 'Partial Shade', null, null, 'Douglas-Fir Forest, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 10 inches deep, with a pH of 5.5-7.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Veratrum californicum is only slightly drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 30 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers part shade.', null, 'https://calscape.org/Veratrum-californicum-%28California-False-Hellebore%29');
