INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Verbena lasiostachys', 'Vervain', 'Bats, Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Blue, Purple, Lavender', 'Summer, Spring, Fall', 'Full Sun', 'Low', '<p>Use with plants that prefer damp areas, such as Columbine (Aquilegia formosa or exima), Virgin''s Bower (Clematis ligusticifolia), Dogwood (<a href="/search/?plant=Cornus%20(Genus)">Cornus spp.</a>), Sticky Cinquefoil (Drymocallis glandulosa), Stream Orchid (Epipactis gigantea), Gum Plant (<a href="/search/?plant=Grindelia%20(Genus)">Grindelia spp.</a>), Ocean Spray (Holodiscus discolor), Iris species, Leopard Lily (Lilium pardalinum), Scarlet Monkeyflower (Erythranthe cardinalis), Seep Monkeyflower (Erythranthe guttata), Evening Primrose (Oenothera elata), California Buttercup (Ranunculus californicus), Bee Plant (Scrophularia californica), Triteleia species, and Viola species.</p>', 'Chaparral, Foothill Woodland, Lodgepole Forest, Red Fir Forest, Subalpine Forest, Valley Grassland, Yellow Pine Forest, Wetland-Riparian', '<p>Prefers sun. Likes wet soils.</p>', null, 'https://calscape.org/Verbena-lasiostachys-%28Vervain%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Verbena lasiostachys var. lasiostachys', 'Western Vervain', 'Bees, Birds, Butterflies, Caterpillars, Hummingbirds', 'Pink', 'Summer, Spring, Fall', 'Full Sun', 'Low', null, 'Wetland-Riparian', '<p>Prefers sun.</p>', null, 'https://calscape.org/Verbena-lasiostachys-var.-lasiostachys-%28Western-Vervain%29');
