INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Veronica americana', 'Brooklime', 'Butterflies, Caterpillars', 'Blue, Purple', 'Summer', 'Full Sun', 'Moderate', null, 'Freshwater Marsh, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 5.7-7.5. It is moderately tolerant of anaerobic soils, moderately tolerant of calcareous soils, and requires only moderately fertile soils. Veronica americana is only slightly drought tolerant. It requires a minimum of 16 inches of water per year, and a maximum of 60 inches of water per year once established. Requires moist soil. It is very tolerant of shade. Prefers sun.', null, 'https://calscape.org/Veronica-americana-%28Brooklime%29');
