INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Veronica wormskjoldii', 'Alpine Speedwell', 'Butterflies, Caterpillars', 'Blue', 'Summer', 'Partial Shade', 'Moderate', null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 6 inches deep, with a pH of 6-7.3. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires only moderately fertile soils. Veronica wormskjoldii is only slightly drought tolerant. It requires a minimum of 32 inches of water per year, and a maximum of 55 inches of water per year once established. Requires moist soil. It is moderately tolerant of full shade. Prefers part shade.', null, 'https://calscape.org/Veronica-wormskjoldii-%28Alpine-Speedwell%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Vicia americana', 'American Vetch', 'Butterflies, Caterpillars', 'Purple, Pink, Lavender', 'Spring', 'Full Sun, Partial Shade', null, null, 'Lodgepole Forest, Mixed Evergreen Forest, Red Fir Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 10 inches deep, with a pH of 5.9-7.2. It is intolerant of anaerobic soils, intolerant of calcareous soils, and requires fertile soil. Vicia americana is extremely drought tolerant. It requires a minimum of 9 inches of water per year, and a maximum of 50 inches of water per year once established. Requires moist soil. It does not tolerate full shade well. Prefers sun or part shade.', null, 'https://calscape.org/Vicia-americana-%28American-Vetch%29');
