INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Viola macloskeyi', 'Small White Violet', 'Butterflies, Caterpillars', 'White', 'Spring', 'Deep Shade', null, null, 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest, Wetland-Riparian', 'Plant in loamy or clay soils that are at least 4 inches deep, with a pH of 6-7.3. It is tolerant of anaerobic soils, intolerant of calcareous soils, and requires fertile soil. Viola macloskeyi is only slightly drought tolerant. It requires a minimum of 14 inches of water per year, and a maximum of 45 inches of water per year once established. Requires fast draining soil. Prefers shade.', null, 'https://calscape.org/Viola-macloskeyi-%28Small-White-Violet%29');
