INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Wyethia angustifolia', 'Narrow Leaf Mule Ears', 'Butterflies, Caterpillars', 'Yellow', 'Spring, Summer', 'Full Sun', 'Low', 'Use with various native grasses, geophytes such as onion (<a href="/search/?plant=Allium%20(Genus)">Allium spp.</a>), Milkweed (<a href="/search/?plant=Asclepias%20(Genus)">Asclepias spp.</a>), and annual wildflowers such as <a href="/search/?plant=Clarkia%20(Genus)">Clarkia spp.</a>', 'Chaparral, Foothill Woodland, Valley Grassland, Yellow Pine Forest', 'Requires fast draining soil. Prefers sun. Likes stream banks.', null, 'https://calscape.org/Wyethia-angustifolia-%28Narrow-Leaf-Mule-Ears%29');
