INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Wyethia mollis', 'Mule Ears', null, 'White, Yellow', 'Spring, Summer', 'Partial Shade, Full Sun', 'Very Low', 'Trees: Lodgepole Pine (Pinus contorta), Red Fir (Abies magnifica), Douglas Fir (Pseudotsuga menziesii), Yellow Pine (Pinus ponderosa), Limber Pine (Pinus flexilis), White Pine (Pinus monticola), Quaking Aspen (Populus tremuloides), Western Hemlock (Tsuga mertensiana)<br><br>Shrubs: Manzanita (<a href="/search/?plant=Arctostaphylos%20(Genus)">Arctostaphylos spp.</a>), <a href="/search/?plant=Ceanothus%20(Genus)">Ceanothus spp.</a>, Serviceberry (<a href="/search/?plant=Amelanchier%20(Genus)">Amelanchier spp.</a>), Antelope Bush (Purshia tridentata), grasses such as <a href="/search/?plant=Agrostis%20(Genus)">Agrostis spp.</a>', 'Lodgepole Forest, Red Fir Forest, Subalpine Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 20 inches deep, with a pH of 6.5-8.5. It is intolerant of anaerobic soils, moderately tolerant of calcareous soils, and tolerant of infertile soils. Wyethia mollis is extremely drought tolerant. It requires a minimum of 8 inches of water per year, and a maximum of 16 inches of water per year once established. It is very tolerant of shade. Prefers sun or part shade.', null, 'https://calscape.org/Wyethia-mollis-%28Mule-Ears%29');
INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Wyethia ovata', 'Southern Mule''s Ears', null, 'Yellow', null, null, null, null, 'Chaparral, Yellow Pine Forest', null, null, 'https://calscape.org/Wyethia-ovata-%28Southern-Mule%27s-Ears%29');
