INSERT INTO public.flowers ("Botanical Name", "Common Name", "Attracts Wildlife", "Flower Color", "Flowering Season", "Sun", "Water Requirement", "Companions", "Communities", "Tips", "Pests", "Plant Url") VALUES ('Xerophyllum tenax', 'Beargrass', null, 'White', 'Summer', 'Full Sun, Partial Shade, Deep Shade', 'Low, Very Low', null, 'Mixed Evergreen Forest, Yellow Pine Forest', 'Plant in sandy or loamy soils that are at least 6 inches deep, with a pH of 5.5-7.2. It is intolerant of anaerobic soils, intolerant of calcareous soils, and tolerant of infertile soils. Xerophyllum tenax is moderately drought tolerant. It requires a minimum of 19 inches of water per year, and a maximum of 69 inches of water per year once established. Requires fast draining soil. It is moderately tolerant of shade. Grows well in sun, shade or part shade. Likes dry rocky slopes.', null, 'https://calscape.org/Xerophyllum-tenax-%28Beargrass%29');
